import{createBiologyLesson as t}from"./shared.js?v=7388f68cc0f433fd";export const source=':::mcq\nid: bio-q-p080-q1\ntitle: تصنيف الأسئلة، السؤال 1، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: إذا تزوج شاب شعره مجعد من فتاة مجهولة الطراز الشكلي لهذه الصفة، وكان جميع أبنائهما بشعر مموج، فما الطراز الشكلي والجيني للفتاة؟\n- [ ] option-1 | أ. مموج CW\n- [ ] option-2 | ب. مموج WW\n- [ ] option-3 | ج. مستقيم SW\n- [x] option-4 | د. مستقيم SS\nexplanation:\nالأليل صورة من الجين؛\nنرمز للمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` وللمستقيم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>`. في السيادة غير التامة يظهر الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` بشعر مموج.\nالأب المجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC</mtext></math>` ، فيمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` في كل غاميت. لكي يكون النسل المتوقع كله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` يجب أن تمنح الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` دائماً، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SS</mtext></math>` مستقيمة الشعر.\nالتزاوج : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC × SS</mtext></math>` ؛\nالغاميتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` ؛\nجميع التركيبات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>`. إذن الاختيار د. هذا استنتاج التزاوج المدرسي المتوقع، وليس ضماناً إحصائياً من عدد قليل من الأبناء.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q2\ntitle: تصنيف الأسئلة، السؤال 2، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: أجري تلقيح بين نباتي فجل أحدهما طويل الجذور، والآخر كروي الجذور، فكان جميع أفراد الجيل الأول بجذور بيضوية، أي النسب الآتية تمثل أفراد الجيل الثاني؟\n- [ ] option-1 | أ. 1:1\n- [ ] option-2 | ب. 1:3:3:9\n- [x] option-3 | ج. 1:2:1\n- [ ] option-4 | د. 2:1\nexplanation:\nالسيادة غير التامة تجعل الهجين وسطياً : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LL</mtext></math>` طويل، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` كروي، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` بيضوي.\nالآباء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LL × RR</mtext></math>` ؛\nغاميتاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` ، فيكون الجيل الأول كله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>`.\nيتزاوج أفراد الجيل الأول : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR × LR</mtext></math>` ؛\nغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>`.\n\n| الغاميت | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LL</mtext></math>` طويل | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` بيضوي |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` بيضوي | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` كروي |\n\nإذن الجيل الثاني : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` طويل : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` بيضوي : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` كروي، أي الاختيار ج.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q3\ntitle: تصنيف الأسئلة، السؤال 3، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: إذا أجري تلقيح بين نباتي فجل أحدهما كروي الجذور والآخر بيضوي الجذور وكانت الطرز الشكلية للأفراد الناتجة كروية وبيضوية بالنسبة (1:1)، ما آلية وراثة الصفة؟\n- [x] option-1 | أ. سيادة غير تامة\n- [ ] option-2 | ب. مرتبطة بالجنس\n- [ ] option-3 | ج. جينات متعددة\n- [ ] option-4 | د. أليلات متعددة\nexplanation:\nفي السيادة غير التامة يحمل الهجين طرازاً وسطياً؛\nنرمز للطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` وللكروي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` بيضوياً.\nالكروي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` فقط، والبيضوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` بالتساوي.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR × LR</mtext></math>` ينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LR</mtext></math>` بيضوياً بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` كروياً بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nهذا يفسر ظهور الكروي والبيضوي بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` ؛\nالإجابة أ، السيادة غير التامة.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q4\ntitle: تصنيف الأسئلة، السؤال 4، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: أيّ أنماط الوراثة الآتية يمكن أن يعطي نسبة الطرز الشكلية 1:2:1، من ثلاثة مظاهر مختلفة، عند تزاوج فردين هجينين؟\n\n- [ ] option-1 | أ. السيادة التامة\n- [ ] option-2 | ب. ارتباط جينات\n- [x] option-3 | ج. السيادة غير التامة\n- [ ] option-4 | د. الجينات القاتلة\nexplanation:\nالإجابة المنهجية المقصودة **ج: السيادة غير التامة** عند تفسير النسبة على أنها نسبة الطرز الشكلية.\nالسيادة غير التامة تعني أن الهجين يظهر مظهراً وسطياً بين الأبوين؛ فـRW زهري بينRR الأحمر وWW الأبيض.\nكل والدRW يعطيR أوW. ينتج منRW×RW:\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>R</mi><mi>R</mi><mo>:</mo><mi>R</mi><mi>W</mi><mo>:</mo><mi>W</mi><mi>W</mi><mo>=</mo><mn>1</mn><mo>:</mo><mn>2</mn><mo>:</mo><mn>1</mn></mrow></math>\n```\n\n\nولكل طراز هنا مظهر مختلف، فتكون النسبة الشكلية نفسها1:2:1.\nنميز النسبة الشكلية من الجينية: في السيادة التامة قد تظهر نسبة جينية 1:2:1 أيضًا، لكن الطرز الشكلية تكون 3:1، بخلاف النسبة الشكلية المحددة هنا.\n\n**المصدر:** صفحة 28 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q5\ntitle: تصنيف الأسئلة، السؤال 5، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: إذا حصل تزاوج بين قط وقطة كلاهما قصير الذيل، وكانت الأفراد الناتجة من التزاوج بالنسب الآتية: (49) بدون ذيل : (48) طويل الذيل : (97) قصير الذيل، فما نوع الوراثة لهذه الصفة؟\n- [x] option-1 | أ. سيادة غير تامة\n- [ ] option-2 | ب. سيادة تامة\n- [ ] option-3 | ج. جينات متعددة\n- [ ] option-4 | د. صفات مرتبطة بالجنس\nexplanation:\nالأعداد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>49</mtext></math>` بلا ذيل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>97</mtext></math>` قصير الذيل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>48</mtext></math>` طويل الذيل تقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ؛\nفالعدد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>97</mtext></math>` يقارب ضعفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>49</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>48</mtext></math>`.\nنرمز لطرفي الصفة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B: AA</mtext></math>` بلا ذيل، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` طويل، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` قصير ذو مظهر وسطي. هذا معنى السيادة غير التامة.\nالأبوان قصيرا الذيل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB × AB</mtext></math>` ، وغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. النواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` ، فتوافق الأعداد المعطاة.\nإذن الاختيار أ، ولا تفسر السيادة التامة وجود المظهر الوسطي المستقل.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p086-q1-1\ntitle: تصنيف الأسئلة، السؤال 1، الفرع 1، صفحة 86\nquestion: السؤال 1، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نبتتين أحدهما طويل الساق زهري الأزهار أملس البذور مع نبات آخر مجهول الطراز الشكلي، فكانت النتائج لأفراد الجيل الأول: طويل زهري أملس32؛ قصير زهري مجعد32؛ طويل أحمر أملس18؛ طويل أبيض أملس14؛ قصير أحمر مجعد16؛ قصير أبيض مجعد16. أجب مستخدماً (T،t لطول الساق)، (R،W للون الأزهار)، (B،b لشكل البذور).\n\n1- ما الطراز الجيني لكلا الأبوين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` سائد للطول و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصر، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد لملمس البذور الأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للمجعد؛\nأما اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض لسيادة غير تامة.\nالطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+18+14=64</mtext></math>`\nوالقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+16+16=64</mtext></math>` ؛\nوكذلك الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=64</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=64</mtext></math>`. النسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` لكل منهما تلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb × bb</mtext></math>`.\nالأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=18+16=34</mtext></math>`\nوالزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+32=64</mtext></math>`\nوالأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=14+16=30</mtext></math>` ؛\nوهي تقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` فتدل على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nإذن المعروف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRWBb</mtext></math>` والمجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttRWbb</mtext></math>`.\nالارتباط يعني وجود الجينين على الكروموسوم نفسه وتوارثهما معاً عندما لا يفصلهما عبور. لو توزعا مستقلاً لتوقعنا أيضاً طويلاً مجعداً وقصيراً أملس؛ لكن هذين الصنفين غائبان. لذلك اقتران الطول بالأملس والقصر بالمجعد في جميع الأفراد يوافق ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TB/tb</mtext></math>` في النبات الأول بلا عبور ظاهر في هذه العينة؛\nولا يصح توقع استقلال الطول وشكل البذور من هذه النتائج. عند هذا التفسير تكون غاميتاته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TBR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TBW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tbR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tbW</mtext></math>` ، والمجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tbR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tbW</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p086-q1-2\ntitle: تصنيف الأسئلة، السؤال 1، الفرع 2، صفحة 86\nquestion: السؤال 1، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نبتتين أحدهما طويل الساق زهري الأزهار أملس البذور مع نبات آخر مجهول الطراز الشكلي، فكانت النتائج لأفراد الجيل الأول: طويل زهري أملس32؛ قصير زهري مجعد32؛ طويل أحمر أملس18؛ طويل أبيض أملس14؛ قصير أحمر مجعد16؛ قصير أبيض مجعد16. أجب مستخدماً (T،t لطول الساق)، (R،W للون الأزهار)، (B،b لشكل البذور).\n\n2- ما الطراز الشكلي للنبات المجهول؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` سائد للطول و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصر، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد لملمس البذور الأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للمجعد؛\nأما اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض لسيادة غير تامة.\nالطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+18+14=64</mtext></math>`\nوالقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+16+16=64</mtext></math>` ؛\nوكذلك الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=64</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=64</mtext></math>`. النسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` لكل منهما تلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb × bb</mtext></math>`.\nالأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=18+16=34</mtext></math>`\nوالزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=32+32=64</mtext></math>`\nوالأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=14+16=30</mtext></math>` ؛\nوهي تقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` فتدل على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nالنبات المعروف طويل زهري أملس؛\nأما الطرف المقابل فطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttRWbb</mtext></math>` ، ولذلك مظهره قصير الساق زهري الأزهار مجعد البذور.\nفي الطول: غاميتا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` من المعروف مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` من المجهول تعطيان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`.\nوفي البذور : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` تعطيان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، مناصفة في كل صفة.\n:::\n\n:::exam-question\nid: bio-q-p086-q1-3\ntitle: تصنيف الأسئلة، السؤال 1، الفرع 3، صفحة 86\nquestion: السؤال 1، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نبتتين أحدهما طويل الساق زهري الأزهار أملس البذور مع نبات آخر مجهول الطراز الشكلي، فكانت النتائج لأفراد الجيل الأول: طويل زهري أملس32؛ قصير زهري مجعد32؛ طويل أحمر أملس18؛ طويل أبيض أملس14؛ قصير أحمر مجعد16؛ قصير أبيض مجعد16. أجب مستخدماً (T،t لطول الساق)، (R،W للون الأزهار)، (B،b لشكل البذور).\n\n3- ما نوع وراثة لون الأزهار؟\nsolution:\nالسيادة غير التامة تعني أن الهجينRW يظهر زهرياً، وهو مظهر وسطي بينRR الأحمر وWW الأبيض.\n\nنجمع أفراد كل لون من المعطيات:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mi>R</mi><mi>R</mi><mo stretchy="false">)</mo><mo>=</mo><mn>18</mn><mo>+</mo><mn>16</mn><mo>=</mo><mn>34</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mi>R</mi><mi>W</mi><mo stretchy="false">)</mo><mo>=</mo><mn>32</mn><mo>+</mo><mn>32</mn><mo>=</mo><mn>64</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mi>W</mi><mi>W</mi><mo stretchy="false">)</mo><mo>=</mo><mn>14</mn><mo>+</mo><mn>16</mn><mo>=</mo><mn>30</mn></mrow></math>\n```\n\n\n\nتقترب الأعداد من1:2:1؛ وهي نواتج تزاوج زهريين:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>R</mi><mi>W</mi><mo>×</mo><mi>R</mi><mi>W</mi><mo>⟶</mo><mi>R</mi><mi>R</mi><mo>:</mo><mi>R</mi><mi>W</mi><mo>:</mo><mi>W</mi><mi>W</mi><mo>=</mo><mn>1</mn><mo>:</mo><mn>2</mn><mo>:</mo><mn>1</mn></mrow></math>\n```\n\n\n\nإذن وراثة لون الأزهار **سيادة غير تامة**، كما يوضح مظهر الزهري والنسبة معاً.\n\n**المصدر:** صفحة 28 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p094-q36-1\ntitle: تصنيف الأسئلة، السؤال 36، الفرع 1، صفحة 94\nquestion: السؤال 36، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نباتين ثم جمعت البذور الناتجة وزرعت فنتجت نباتات بالصفات والنسب: (1) أحمر طويل؛ (2) زهري طويل؛ (2) زهري قصير؛ (1) أبيض طويل؛ (1) أبيض قصير؛ (1) أحمر قصير.\n\n1- اكتب الطرز الشكلية للآباء.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` للأبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` للزهري الوسطي، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير.\nنجمع اللون: أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>`\nزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>`\nأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ؛\nلذا لون الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nنجمع الطول: طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+2+1=4</mtext></math>`\nوقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+1+1=4</mtext></math>` ؛\nلذا التزاوج المدرسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>`.\nالطرزان الشكليان إذن: زهري طويل الساق × زهري قصير الساق.\nغاميتا الطول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` من الطويل، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` فقط من القصير، تفسران نصفي النسل؛\nوغاميتا اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` من كلا الأبوين تفسران الألوان الثلاثة.\n:::\n\n:::exam-question\nid: bio-q-p094-q36-2\ntitle: تصنيف الأسئلة، السؤال 36، الفرع 2، صفحة 94\nquestion: السؤال 36، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نباتين ثم جمعت البذور الناتجة وزرعت فنتجت نباتات بالصفات والنسب: (1) أحمر طويل؛ (2) زهري طويل؛ (2) زهري قصير؛ (1) أبيض طويل؛ (1) أبيض قصير؛ (1) أحمر قصير.\n\n2- اكتب الطرز الجينية للآباء.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` للأبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` للزهري الوسطي، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير.\nنجمع اللون: أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>`\nزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>`\nأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ؛\nلذا لون الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nنجمع الطول: طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+2+1=4</mtext></math>`\nوقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+1+1=4</mtext></math>` ؛\nلذا التزاوج المدرسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>`.\nالطرزان الجينيان للأبوين : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRW × ttRW</mtext></math>` ؛\nإذ لا يعطي الطويل قصاراً إلا إذا حمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` ، بينما القصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` حتماً.\nللون : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\nوللطول : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p094-q36-3\ntitle: تصنيف الأسئلة، السؤال 36، الفرع 3، صفحة 94\nquestion: السؤال 36، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نباتين ثم جمعت البذور الناتجة وزرعت فنتجت نباتات بالصفات والنسب: (1) أحمر طويل؛ (2) زهري طويل؛ (2) زهري قصير؛ (1) أبيض طويل؛ (1) أبيض قصير؛ (1) أحمر قصير.\n\n3- اكتب الطرز الجينية لجاميتات الآباء.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` للأبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` للزهري الوسطي، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير.\nنجمع اللون: أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>`\nزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>`\nأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+1=2</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ؛\nلذا لون الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nنجمع الطول: طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1+2+1=4</mtext></math>`\nوقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+1+1=4</mtext></math>` ؛\nلذا التزاوج المدرسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>`.\nإذن الأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRW × ttRW</mtext></math>`. الغاميت يحمل أليلاً واحداً من كل جين؛\nوبافتراض استقلال هاتين الصفتين كما تلائم الفئات الست: غاميتات الأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tW</mtext></math>` ، واحتمال كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nغاميتات الثاني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tW</mtext></math>` ، واحتمال كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`. جمع هذه الغاميتات يعطي الأحمر والزهري والأبيض بين الطوال والقصار بالنسب المعطاة.\n:::\n\n:::exam-question\nid: bio-q-p094-q36-4\ntitle: تصنيف الأسئلة، السؤال 36، الفرع 4، صفحة 94\nquestion: السؤال 36، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتم تلقيح نباتين ثم جمعت البذور الناتجة وزرعت فنتجت نباتات بالصفات والنسب: (1) أحمر طويل؛ (2) زهري طويل؛ (2) زهري قصير؛ (1) أبيض طويل؛ (1) أبيض قصير؛ (1) أحمر قصير.\n\n4- ما آلية الوراثة للصفتين؟\nsolution:\nلون الأزهار سيادة غير تامة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` الأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` الأبيض؛\nوتزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR:RW:WW</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، المطابقة لمجموع الألوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2:4:2</mtext></math>`.\nطول الساق سيادة تامة في نموذج المسألة: وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` يكفي للطول، فلا يوجد مظهر وسطي؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>` ينتج نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` طويل ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` قصير، المطابق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4:4</mtext></math>`.\nالنسب وحدها لا تثبت آلية جزيئية؛\nهذا التصنيف يطبق تعريف صفتي المنهج.\n:::\n\n:::mcq\nid: bio-b-p040-q1-5\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-5\nquestion: أجري تلقيح بين نوعين من الأحصنة كلاهما مبرقع اللون (يجمع اللونين الأبيض والأسود)، ما احتمال ظهور أنثى حصان (فرس) سوداء اللون في أفراد الجيل الأول؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [ ] option-1 | 1/4\n- [x] option-2 | 1/8\n- [ ] option-3 | 1/2\n- [ ] option-4 | 1\nexplanation:\nالمبرقع يُظهر اللونين معاً، وهذه سيادة مشتركة؛\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض، فيكون كل أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>`.\nغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>`. التزاوج يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` أسوداً ومرتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` مبرقعاً و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᵂCᵂ</mtext></math>` أبيضاً.\nاحتمال الأسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`. احتمال الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ، مستقل عن لون الجسم في هذا السؤال.\nاحتمال أنثى سوداء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/4)×(1/2)=1/8</mtext></math>`.\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q6\ntitle: تصنيف الأسئلة، السؤال 6، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: أجري تلقيح بين ديك ودجاجة كلاهما رزي الريش، ما النسبة المئوية لظهور أفراد بيضاء الريش في الجيل الأول؟\n- [x] option-1 | أ. 25%\n- [ ] option-2 | ب. 50%\n- [ ] option-3 | ج. 75%\n- [ ] option-4 | د. 100%\nexplanation:\nالرزي يظهر الريش الأسود والأبيض معاً، وهو هجين السيادة المشتركة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>`.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ × CᴮCᵂ</mtext></math>` ؛\nكل منهما يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` بالتساوي.\nالنواتج : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` أسود، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` رزي، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` رزي، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᵂCᵂ</mtext></math>` أبيض.\nالأبيض حالة واحدة من أربع : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4×100=25%</mtext></math>` ، الاختيار أ.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-b-p038-q1-2\ntitle: الرزمة التعليمية، صفحة 38، السؤال 1-2\nquestion: ما سبب الاختلاف بين فصائل الدم؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\n- [x] option-1 | نوع الأنتيجين على سطح خلايا الدم الحمراء\n- [ ] option-2 | اختلاف موقع الأليلات على الكروموسوم رقم 9\n- [ ] option-3 | نوع الأنتيجين في بلازما الدم\n- [ ] option-4 | نوع الأجسام المضادة على سطح خلايا الدم الحمراء\nexplanation:\n**الإجابة:** نوع الأنتيجين على سطح خلايا الدم الحمراء\n\n**الشاهد من الكتاب:**\n\n> يعد نظام الدم من الأمثلة على الأليلات المتعددة، وفي هذا النظام توجد ثلاثة أليلات هيIᴬ وIᴮ وi حيث تشغل نفس الموقع على الكروموسوم رقم9، والمسؤولة عن ظهور أربعة طرز شكلية مختلفة بالاعتماد على وجود أي من الأنتيجينين(مولد الضد)A وB، أو وجودهما معاً، أو عدم وجودهما على أغشية خلايا الدم الحمراء.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-7\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-7\nquestion: إذا كانت فصيلة دم الأب AB وفصيلة دم الأم O، فما نسبة احتمال إنجاب طفل ذكر فصيلة دمه A؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [ ] option-1 | 100%\n- [ ] option-2 | 50%\n- [x] option-3 | 25%\n- [ ] option-4 | صفر%\nexplanation:\nفي نظام `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يُظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` المستضد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ويُظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` المستضد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، ويسودان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>`.\nالأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` ، والأم تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فقط. الأبناء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` من فصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` من فصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، مناصفة.\nاحتمال ذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/2</mtext></math>` ، واحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=1/2</mtext></math>`.\nاحتمال ذكر فصيلته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=(1/2)×(1/2)=1/4=25%</mtext></math>`.\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-10\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-10\nquestion: ما نوع مولدات الضد الموجودة على سطح خلايا الدم الحمراء لشخص فصيلة دمه A؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [ ] option-1 | B\n- [x] option-2 | A\n- [ ] option-3 | A,B\n- [ ] option-4 | لا يوجد\nexplanation:\n**الإجابة:** A\n\n**الشاهد من الكتاب:**\n\n> فصيلة الدمA: أنتيجينA؛ فصيلة الدمB: أنتيجينB؛ فصيلة الدمAB: أنتيجينA وأنتيجينB؛ فصيلة الدمO: لا يوجد.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q7\ntitle: تصنيف الأسئلة، السؤال 7، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: ماذا يحوي دم الشخص الذي فصيلة دمه A؟\n- [ ] option-1 | أ. مولدات ضد من نوع A ويكون أجساماً مضادة من نوع A\n- [ ] option-2 | ب. مولدات ضد من نوع A ولا يكون أي نوع من الأجسام المضادة\n- [ ] option-3 | ج. مولدات ضد من نوع B ويكون أجساماً مضادة من نوع A\n- [x] option-4 | د. مولدات ضد من نوع A ويكون أجساماً مضادة من نوع B\nexplanation:\n**الإجابة:** د. مولدات ضد من نوع A ويكون أجساماً مضادة من نوع B\n\n**الشاهد من الكتاب:**\n\n> فصيلة الدمA: الأنتيجينA، الأجسام المضادة في بلازما الدمAnti-B؛ فصيلة الدمAB: الأنتيجينA وB، لا توجد أجسام مضادة.\n\n**المصدر:** صفحة 31 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p080-q8\ntitle: تصنيف الأسئلة، السؤال 8، صفحة 80\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 80\nquestion: تزوج شاب وفتاة مجهولي الطراز الشكلي لصفة فصيلة الدم، أنجبا ولداً فصيلة دمه O وبنتاً فصيلة دمها AB، ما الطرز الشكلية للأبوين لهذه الصفة؟\n- [ ] option-1 | أ. A، AB\n- [ ] option-2 | ب. AB، AB\n- [ ] option-3 | ج. A، A\n- [x] option-4 | د. A، B\nexplanation:\nالأليل صورة من الجين؛\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` وتظهر آثارهما معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\nالولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيلزم أن يحمل كلا الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`. والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` ، فيلزم أن يأتي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` من أحدهما و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الآخر.\nإذن الأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × Iᴮi</mtext></math>` ، وفصيلتاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nالغاميتات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`. الإجابة د.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p081-q9\ntitle: تصنيف الأسئلة، السؤال 9، صفحة 81\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 81\nquestion: إذا كانت فصائل الدم للأبناء المتوقع إنجابهم (AB,B,A) وكانت فصيلة دم الأم AB، ما الطراز الجيني لفصيلة دم الأب؟\n- [ ] option-1 | أ. IᴬIᴬ\n- [ ] option-2 | ب. IᴮIᴮ\n- [x] option-3 | ج. Iᴬi\n- [ ] option-4 | د. ii\nexplanation:\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` ، فتنتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>`. لكي تظهر الفصائل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` يلزم من البدائل أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nغاميتا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ، والنتائج : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ=A</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ=AB</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi=A</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi=B</mtext></math>`.\nإذن الاحتمالات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=1/2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=1/4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=1/4</mtext></math>` ، ولا تظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ؛\nالاختيار ج.\nهذه نتيجة المقارنة بين البدائل؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` يعطي الفصائل الثلاث أيضاً لكنه غير وارد بينها.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p081-q10\ntitle: تصنيف الأسئلة، السؤال 10، صفحة 81\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 81\nquestion: شخص يحمل في بلازما دمه أجساماً مضادة A (Anti) فقط، أي الطرز الجينية الآتية لا يمكن أن يكون لوالد هذا الشخص؟\n- [ ] option-1 | أ. IᴬIᴮ\n- [x] option-2 | ب. IᴬIᴬ\n- [ ] option-3 | ج. Iᴮi\n- [ ] option-4 | د. ii\nexplanation:\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فقط يعني فصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nفأليلها إما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ، إذ يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` لكل أبنائه، فينتج مع أي أليل أمومي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ولا ينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nأما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` فيستطيع إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` يستطيع إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` يستطيع إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nلذلك يمكن أن يكون أي منها أباً لصاحب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند اختيار أم ملائمة. الإجابة ب.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p087-q4-2\ntitle: تصنيف الأسئلة، السؤال 4، الفرع 2، صفحة 87\nquestion: السؤال 4، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمه A، كان والده ذا شعر طبيعي، من فتاة غير صلعاء وفصيلة دمها غير معروفة، فأنجبا طفلة صلعاء فصيلة دمها B، ولم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت عملية نقل الدم من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- فسر فشل نقل الدم من الزوجة إلى زوجها.\n\nsolution:\nالزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يستقبل خلايا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ، وتوجد في بلازمته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. ونجاح إعطائه الدم للزوجة يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nولأن البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تتطلب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم فالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\nخلايا الزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` تحمل مولدي الضد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. عند نقلها إلى الزوج يرتبط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لديه بمولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` على الخلايا المنقولة، فيحدث التراص؛\nلذلك فشل النقل.\nهذا تفسير نقل خلايا الدم وفق نظام `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` المدرسي.\n:::\n\n:::exam-question\nid: bio-q-p087-q6-3\ntitle: تصنيف الأسئلة، السؤال 6، الفرع 3، صفحة 87\nquestion: السؤال 6، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من نزف الدم فصيلة دمه غير محددة، من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا طفلين ذكرين الأول مصاب بمرض نزف الدم فصيلة دمه O والثاني سليم وفصيلة دمه B. تبين أنه لا يستطيع أي الوالدين التبرع للآخر بالدم، واحتوت أغشية خلايا الدم الحمراء للأم على الأنتيجينB.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- فسر وجود نمطين من السيادة في فصائل الدم.\n\nsolution:\nالسيادة تعني كيفية ظهور أثر أليلي الجين عند اجتماعهما. في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` تظهر سيادة تامة لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحدها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` وحدها؛\nفأثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` لا يظهر بوجود أي منهما.\nوتظهر سيادة مشتركة في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` ؛\nإذ يُنتج مولد الضد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ومولد الضد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` معاً، فتكون الفصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\nإذن وجود ثلاثة أليلات في الجماعة يسمح بعلاقتي سيادة مختلفتين؛\nكل فرد يحمل أليلين فقط.\n:::\n\n:::exam-question\nid: bio-q-p088-q8-3\ntitle: تصنيف الأسئلة، السؤال 8، الفرع 3، صفحة 88\nquestion: السؤال 8، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع سليم من مرض نزف الدم وفصيلة دمه B من فتاة ذات شعر طبيعي ومصابة بنزف الدم وفصيلة دمها غير معروفة، فأنجبا أنثى صلعاء فصيلة دمها A وذكراً ذا شعر طبيعي فصيلة دمه B (متماثل الجينات).\n\n3- ما نوع مولد الضد على أغشية خلايا الدم الحمراء للرجل؟\nsolution:\n**الإجابة:** مولد الضدB.\n\n**الشاهد من الكتاب:**\n\n> فصيلة الدمA: أنتيجينA؛ فصيلة الدمB: أنتيجينB؛ فصيلة الدمAB: أنتيجينA وأنتيجينB؛ فصيلة الدمO: لا يوجد.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p090-q19-2\ntitle: تصنيف الأسئلة، السؤال 19، الفرع 2، صفحة 90\nquestion: السؤال 19، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل الأجسام المضادة في بلازما دمه من نوعA فقط وغير محدد الطراز الشكلي لصفة نزف الدم من فتاة غير مصابة بنزف الدم وغير محددة فصيلة دمها، فأنجبا بنتاً فصيلة دمهاA ومصابة بنزف الدم. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى زوجته.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- اكتب الطراز الشكلي للفتاة لصفة فصيلة الدم.\n\nsolution:\nالمقصود بالفتاة هنا الزوجة. وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فقط لدى الرجل يجعله من الفصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nنجاح إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للزوجة يعني أنها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. فشل إعطائها الدم إلى الزوج يستبعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\nوالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` تؤكد أن الأم أعطتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` ، بينما أعطاها الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nفطرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. إذن فصيلة الزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ، وتظهر مولدي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` معاً بسبب السيادة المشتركة.\n:::\n\n:::exam-question\nid: bio-q-p091-q25-1\ntitle: تصنيف الأسئلة، السؤال 25، الفرع 1، صفحة 91\nquestion: السؤال 25، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمهA شعره على شكل قمة الأرملة من فتاة فصيلة دمها غير معروفة وشعرها بخط مستقيم، فأنجبا طفلاً فصيلة دمهO وشعره بخط مستقيم. عملية نقل الدم لم تنجح من الزوج إلى الزوجة ولا من الزوجة إلى الزوج. استخدمG لقمة الأرملة وg للشعر بخط مستقيم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- ما الطراز الشكلي للفتاة لصفة فصيلة الدم؟\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` سائدان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيلزم أن يحمل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. والأم لا تتبادل الدم مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ولا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nوبوجود الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nإذن الطراز الشكلي للأم بالنسبة للدم هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B:</mtext></math>` خلاياها تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` وبلازمتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فيفشل النقل بينها وبين الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` في الاتجاهين.\n:::\n\n:::exam-question\nid: bio-q-p091-q25-2\ntitle: تصنيف الأسئلة، السؤال 25، الفرع 2، صفحة 91\nquestion: السؤال 25، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمهA شعره على شكل قمة الأرملة من فتاة فصيلة دمها غير معروفة وشعرها بخط مستقيم، فأنجبا طفلاً فصيلة دمهO وشعره بخط مستقيم. عملية نقل الدم لم تنجح من الزوج إلى الزوجة ولا من الزوجة إلى الزوج. استخدمG لقمة الأرملة وg للشعر بخط مستقيم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- ما الطرز الجينية لكل من الشاب والفتاة للصفتين معاً؟\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` سائدان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيلزم أن يحمل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. والأم لا تتبادل الدم مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ولا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nوبوجود الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد لقمة الأرملة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` متنح للخط المستقيم. الأم مستقيمة الخط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` ، والطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` من كل أب، فالأب ذو القمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>`.\nإذن الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi Gg</mtext></math>` والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi gg</mtext></math>`. في صفة الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg × gg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` مناصفة، وفي الدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × Iᴮi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع.\n:::\n\n:::exam-question\nid: bio-q-p091-q25-3\ntitle: تصنيف الأسئلة، السؤال 25، الفرع 3، صفحة 91\nquestion: السؤال 25، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمهA شعره على شكل قمة الأرملة من فتاة فصيلة دمها غير معروفة وشعرها بخط مستقيم، فأنجبا طفلاً فصيلة دمهO وشعره بخط مستقيم. عملية نقل الدم لم تنجح من الزوج إلى الزوجة ولا من الزوجة إلى الزوج. استخدمG لقمة الأرملة وg للشعر بخط مستقيم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما الطراز الجيني للطفل؟\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` يظهر فقط عند اجتماع الأليلين المتنحيين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ؛\nوالطفل ذو فصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ، فطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` لقمة الأرملة سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` ؛\nوالخط المستقيم لا يظهر بوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` ، لذلك يكون الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>`.\nإذن طرازه للصفتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii gg</mtext></math>`. أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` من كل من أبويه؛\nوهو ما يلائم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi Gg</mtext></math>` وأماً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi gg</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p091-q25-4\ntitle: تصنيف الأسئلة، السؤال 25، الفرع 4، صفحة 91\nquestion: السؤال 25، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمهA شعره على شكل قمة الأرملة من فتاة فصيلة دمها غير معروفة وشعرها بخط مستقيم، فأنجبا طفلاً فصيلة دمهO وشعره بخط مستقيم. عملية نقل الدم لم تنجح من الزوج إلى الزوجة ولا من الزوجة إلى الزوج. استخدمG لقمة الأرملة وg للشعر بخط مستقيم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nاعتمد استقلال الصفات والنموذج المدرسي لسيادة قمة الأرملة.\n\n4- ما احتمال إنجاب بنت فصيلة دمهاAB بشعر على شكل قمة أرملة؟\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` سائدان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيلزم أن يحمل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. والأم لا تتبادل الدم مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ولا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nوبوجود الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nقمة الأرملة سائدة؛\nولأن الأم والطفل مستقيمان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>`.\nالدم: غاميتا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=1/4</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg × gg</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` بقمة ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` مستقيم.\nاحتمال أنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/2</mtext></math>`. بافتراض استقلال الصفات : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/4)×(1/2)=1/16</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q27-1\ntitle: تصنيف الأسئلة، السؤال 27، الفرع 1، صفحة 92\nquestion: السؤال 27، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل يستطيع ثني لسانه (غير نقي) فصيلة دمهAB من فتاة لا تستطيع ثني لسانها فصيلة دمهاA وفصيلة دم والدتهاO. جين ثني اللسانR سائد على جين عدم ثني اللسانr.\n\n1- ما الطرز الجينية للرجل والفتاة؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سائد لثني اللسان و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` لعدمه في نموذج السؤال. الرجل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr</mtext></math>` ، والفتاة لا تثني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rr</mtext></math>`.\nدم الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من أمها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ذات الطراز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، لذا هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nإذن الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr IᴬIᴮ</mtext></math>` والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rr Iᴬi</mtext></math>`. لا يغيّر عدم ظهور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ضرورة حملها له، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` يسود عليه.\n:::\n\n:::exam-question\nid: bio-q-p092-q27-2\ntitle: تصنيف الأسئلة، السؤال 27، الفرع 2، صفحة 92\nquestion: السؤال 27، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل يستطيع ثني لسانه (غير نقي) فصيلة دمهAB من فتاة لا تستطيع ثني لسانها فصيلة دمهاA وفصيلة دم والدتهاO. جين ثني اللسانR سائد على جين عدم ثني اللسانr.\n\n2- ما الطرز الجينية لغاميتات الرجل؟\nsolution:\nالرجل غير نقي لثني اللسان؛ فطرازهRr. وفصيلة دمهAB؛ فطرازهIᴬIᴮ، لأن الأليلين يظهران معاً.\n\nيحمل كل غاميت أليلاً واحداً من كل جين. نختارR أوr، ومع كل منهماIᴬ أوIᴮ.\n\nبالتوزيع المستقل تكون الأنواع الأربعة:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>R</mi><msup><mi>I</mi><mi>A</mi></msup><mo separator="true">,</mo><mtext> </mtext><mi>R</mi><msup><mi>I</mi><mi>B</mi></msup><mo separator="true">,</mo><mtext> </mtext><mi>r</mi><msup><mi>I</mi><mi>A</mi></msup><mo separator="true">,</mo><mtext> </mtext><mi>r</mi><msup><mi>I</mi><mi>B</mi></msup></mrow></math>\n```\n\n\n\nاحتمال كل نوع **1/4**.\n\n**المصدر:** الصفحات 25، 30 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p092-q27-3\ntitle: تصنيف الأسئلة، السؤال 27، الفرع 3، صفحة 92\nquestion: السؤال 27، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل يستطيع ثني لسانه (غير نقي) فصيلة دمهAB من فتاة لا تستطيع ثني لسانها فصيلة دمهاA وفصيلة دم والدتهاO. جين ثني اللسانR سائد على جين عدم ثني اللسانr.\n\n3- ما احتمال إنجاب طفل ذكر لا يستطيع ثني لسانه وفصيلة دمهA؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سائد لثني اللسان و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` لعدمه في نموذج السؤال. الرجل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr</mtext></math>` ، والفتاة لا تثني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rr</mtext></math>`.\nدم الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من أمها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ذات الطراز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، لذا هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nثني اللسان : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr × rr</mtext></math>` ؛\nغاميتا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` تعطيان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rr</mtext></math>` ، فيكون احتمال عدم الثني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ × Iᴬi</mtext></math>` ينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ؛\nنصف النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>`.\nاحتمال الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`. بالاستقلال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/2)×(1/2)=1/8</mtext></math>` من جميع الأبناء.\n:::\n\n:::exam-question\nid: bio-q-p093-q32-1\ntitle: تصنيف الأسئلة، السؤال 32، الفرع 1، صفحة 93\nquestion: السؤال 32، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عسلي العيون فصيلة دمهA من فتاة زرقاء العيون فصيلة دمهاAB، فأنجبا ابناً عيونه زرقاء فصيلة دمهB. جين العيون العسليةE سائد على جين العيون الزرقاءe.\n\n1- ما الطرز الجينية للأبوين؟\nsolution:\nوفق نموذج السؤال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` سائد للعسلي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` متنح للأزرق. الأم الزرقاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` ، والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` من أبيه؛\nلذلك الأب العسلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>`.\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` ، والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` منها. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` لا يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` ، فيكون قد أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nالجواب: الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee Iᴬi</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee IᴬIᴮ</mtext></math>`. هذا تطبيق النموذج المبسط المعطى للون العين.\n:::\n\n:::exam-question\nid: bio-q-p093-q32-2\ntitle: تصنيف الأسئلة، السؤال 32، الفرع 2، صفحة 93\nquestion: السؤال 32، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عسلي العيون فصيلة دمهA من فتاة زرقاء العيون فصيلة دمهاAB، فأنجبا ابناً عيونه زرقاء فصيلة دمهB. جين العيون العسليةE سائد على جين العيون الزرقاءe.\n\n2- ما نوع الأنتيجين (مولد الضد) في دم الأم؟\nsolution:\n**الإجابة:** مولد الضدA ومولد الضدB على سطح خلايا الدم الحمراء؛ فصيلة الأمAB.\n\n**الشاهد من الكتاب:**\n\n> فصيلة الدمA: أنتيجينA؛ فصيلة الدمB: أنتيجينB؛ فصيلة الدمAB: أنتيجينA وأنتيجينB؛ فصيلة الدمO: لا يوجد.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p093-q32-3\ntitle: تصنيف الأسئلة، السؤال 32، الفرع 3، صفحة 93\nquestion: السؤال 32، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عسلي العيون فصيلة دمهA من فتاة زرقاء العيون فصيلة دمهاAB، فأنجبا ابناً عيونه زرقاء فصيلة دمهB. جين العيون العسليةE سائد على جين العيون الزرقاءe.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- إلى أي الأبوين يستطيع الابن التبرع بدمه؟\n\nsolution:\nالابن فصيلته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nفخلاياه تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. يستطيع إعطاء خلايا الدم للأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` لأن بلازمتها لا تحتوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ولا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` في نموذج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>`.\nلا يستطيع إعطاءها للأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nإذ تحتوي بلازمته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` الذي يتفاعل مع مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` على خلايا الابن. إذن يستطيع التبرع للأم.\n:::\n\n:::exam-question\nid: bio-q-p093-q32-4\ntitle: تصنيف الأسئلة، السؤال 32، الفرع 4، صفحة 93\nquestion: السؤال 32، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عسلي العيون فصيلة دمهA من فتاة زرقاء العيون فصيلة دمهاAB، فأنجبا ابناً عيونه زرقاء فصيلة دمهB. جين العيون العسليةE سائد على جين العيون الزرقاءe.\n\n4- ما احتمال إنجاب فرد فصيلة دمهA عسلي العيون؟\nsolution:\nوفق نموذج السؤال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` سائد للعسلي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` متنح للأزرق. الأم الزرقاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` ، والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` من أبيه؛\nلذلك الأب العسلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>`.\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` ، والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` منها. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` لا يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` ، فيكون قد أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nالعيون : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee × ee</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>` عسلياً و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` أزرق، احتمال العسلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × IᴬIᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ=A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ=AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi=A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi=B</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=2/4=1/2</mtext></math>`.\nلا يُطلب جنس محدد. بالاستقلال يكون احتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عسلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/2)=1/4</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p094-q35-3\ntitle: تصنيف الأسئلة، السؤال 35، الفرع 3، صفحة 94\nquestion: السؤال 35، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمهA من امرأة شعرها طبيعي فصيلة دمها غير معروفة، فأنجبا بنتاً تظهر صفة الصلع فصيلة دمهاO وولداً طبيعي الشعر. لم تنجح عملية نقل الدم من الرجل إلى زوجته ولا من الزوجة إلى زوجها.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما الطراز الشكلي لصفة فصيلة الدم بالنسبة للأم؟\n\nsolution:\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ، والأم تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` أيضاً.\nعدم نجاح النقل في الاتجاهين بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` والأم يستبعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للتوافق، ويستبعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` لأنها تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، ويستبعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` لأنها تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>`. تبقى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` فقط.\nإذن الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` وطرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ؛\nفي بلازمتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، بينما بلازما الزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` تحتوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\n:::\n\n:::mcq\nid: bio-q-p102-q1\ntitle: صفحة 102، السؤال 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 102\nquestion: اعتماداً على الجدول: رقم الشخص 1 يحتوي بلازما دمه Anti-A؛ الشخص 2: Anti-B؛ الشخص 3: Anti-A وAnti-B؛ الشخص 4: لا يوجد جسم مضاد. أي البدائل الآتية تضم أرقام شخصين يستطيع كلاهما التبرع بدمه لمريض تحوي أغشية خلايا دمه الحمراء على بروتينات سكرية من نوع B؟ اعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n- [x] option-1 | (3،1)\n- [ ] option-2 | (4،2)\n- [ ] option-3 | (2،1)\n- [ ] option-4 | (3،2)\nexplanation:\nالمريض يحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، إذن فصيلته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ويحتوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nيقبل خلايا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` وفق جدول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>`.\nالشخص `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` لديه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nالشخص `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` لديه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nالشخص `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` لديه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ؛\nالشخص `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` بلا هذين المضادين فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\nالمتبرعان المناسبان إذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:</mtext></math>` الأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` والثالث `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ، وكلاهما يخلو من مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` الذي يرفضه المريض. الإجابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(3</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1)</mtext></math>`.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p116-q1-2\ntitle: صفحة 116، السؤال 1-2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 116\nquestion: يتحكم في لون الريش بعض أنواع الطيور3 أليلات (a، A^h، A^z)، ما عدد الطرز الجينية المتوقعة في سرب من الطيور تحمل هذه الجينات؟\n- [ ] option-1 | 8\n- [ ] option-2 | 16\n- [x] option-3 | 6\n- [ ] option-4 | 3\nexplanation:\nالأليل صورة من الجين؛\nتوجد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` صور في السرب لكن كل طائر ثنائي المجموعة يحمل أليلين فقط.\nالمتماثلة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AʰAʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AᶻAᶻ</mtext></math>` ، وعددها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>`.\nغير المتماثلة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aAʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aAᶻ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AʰAᶻ</mtext></math>` ، وعددها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` ؛\nلا نعد تبديل ترتيب الأليلين طرازاً جديداً.\nالمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3+3=6</mtext></math>` طرز جينية، وهو الاختيار الثالث.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q27\ntitle: تصنيف الأسئلة، السؤال 27، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: خلية أنثى حيوان ثدي تحتوي 18 كروموسوم جسمي، ما التركيب الكروموسومي لخلاياها الجسمية؟\n- [ ] option-1 | أ. X + 18\n- [x] option-2 | ب. XX + 18\n- [ ] option-3 | ج. X + 9\n- [ ] option-4 | د. XX + 9\nexplanation:\nفي نظام الثدييات الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` والذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>`. السؤال أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` كروموسوماً جسمياً بالفعل، فلا نقسمها على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` لأن المطلوب خلية جسمية.\nنضيف الكروموسومين الجنسيين للأنثى : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18+XX</mtext></math>` ، ومجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>20</mtext></math>` كروموسوماً. الإجابة ب.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q29\ntitle: تصنيف الأسئلة، السؤال 29، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: أي الكائنات الحية الآتية ينتج نوعين من الغاميتات ويحدد جنس الأبناء؟\n- [ ] option-1 | أ. أنثى الإنسان\n- [x] option-2 | ب. أنثى الطيور\n- [ ] option-3 | ج. ذكر الطيور\n- [ ] option-4 | د. ذكر الفراش\nexplanation:\n**الإجابة:** ب. أنثى الطيور\n\n**الشاهد من الكتاب:**\n\n> أما عند الطيور وبعض أنواع الحشرات كالفراش، وبعض أنواع الأسماك، فإن نظامZZ-ZW هو الشائع، أي أن الأنثى هي المسؤولة عن تحديد الجنس.\n\n**المصدر:** صفحة 32 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-b-p041-q3-1\ntitle: الرزمة التعليمية، صفحة 41، السؤال 3-1\nquestion: ما الطراز الشكلي للأب بالنسبة لصفة عمى الألوان؟\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B من فتاة فصيلة دمها A سليمة من مرض عمى الألوان، فأنجبا طفلة فصيلة دمها O مصابة بعمى الألوان. جين الرؤية الطبيعية R سائد على جين عمى الألوان r.\n\nما الطراز الشكلي للأب بالنسبة لصفة عمى الألوان؟\nsolution:\nعمى الألوان متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\nالأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للرؤية الطبيعية و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمرض، ولا يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` الأليل المقابل في النموذج.\nالطفلة المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أبيها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أمها، فيجب أن يعطيها الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>`. الأب الذكر يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، ولذلك هو مصاب بعمى الألوان. لا يمكن أن يعطي الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` لابنته.\n:::\n\n:::exam-question\nid: bio-b-p041-q3-4\ntitle: الرزمة التعليمية، صفحة 41، السؤال 3-4\nquestion: ما نوع وراثة مرض عمى الألوان؟\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B من فتاة فصيلة دمها A سليمة من مرض عمى الألوان، فأنجبا طفلة فصيلة دمها O مصابة بعمى الألوان. جين الرؤية الطبيعية R سائد على جين عمى الألوان r.\n\nما نوع وراثة مرض عمى الألوان؟\nsolution:\n**الإجابة:** صفة متنحية مرتبطة بالكروموسومX.\n\n**الشاهد من الكتاب:**\n\n> XʰY مصاب؛ XᴴXʰ حاملات.\n\n\n\n[عرض الشاهد الأصلي في الكتاب](assets/lessons/curriculum-evidence/5811d6a047dd54cba595.webp)\n\nيبين مثال دليل المعلم أنXʰY مصاب، وأنXᴴXʰ حاملة؛ أي إنh متنحٍّ أمامH ومحمول علىX.\n\n:::\n\n:::mcq\nid: bio-q-p083-q28\ntitle: تصنيف الأسئلة، السؤال 28، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: ينتج اللون الرمادي للريش لدى بعض أنواع العصافير كصفة وسطية مرتبطة بالجنس، أي الألوان الآتية تظهر لدى إناث هذا النوع من العصافير؟\n- [x] option-1 | أ. الأسود\n- [ ] option-2 | ب. الأسود والرمادي\n- [ ] option-3 | ج. الرمادي\n- [ ] option-4 | د. الأبيض والرمادي\nexplanation:\nفي الطيور الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>`. إذا كان اللون على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` فلا تحمل الأنثى إلا أليلاً واحداً للون، ولذلك لا تجمع أليلي الأسود والأبيض لتظهر الصفة الوسطية الرمادية.\nيمكن للأنثى أن تكون سوداء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮW</mtext></math>` أوبيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵂW</mtext></math>`. من البدائل المعروضة الصحيح أ «الأسود»؛\nلا تعني الإجابة أن الأبيض مستحيل، بل إنه غير معروض منفرداً في البدائل.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q30\ntitle: تصنيف الأسئلة، السؤال 30، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: في الدجاج صفة الريش المخطط B سائدة على الريش غير المخطط b وهذه الصفة مرتبطة بالجنس، ما الطراز الجيني لأنثى مخططة الريش؟\n- [x] option-1 | أ. ZᴮW\n- [ ] option-2 | ب. ZᵇW\n- [ ] option-3 | ج. ZᴮZᵇ\n- [ ] option-4 | د. ZᴮZᴮ\nexplanation:\nالأنثى في الطيور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ، والصفة المحمولة على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` تظهر بأليل واحد فيها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. B</mtext></math>` يعطي الريش المخطط، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` غير المخطط.\nلأن الأنثى مخططة يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` لديها حاملاً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B: ZᴮW</mtext></math>` ، الاختيار أ. أما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵇ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` فذكران `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` وليسا أنثى.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q31\ntitle: تصنيف الأسئلة، السؤال 31، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: حدث تزاوج بين طائر بني الريش B وأنثى بيضاء الريش M ونتجت أفراد بالنسب الآتية: 4 إناث بنية الريش، 4 ذكور كريمية الريش، فإذا علمت أن صفة اللون مرتبطة بالجنس، فأي الآتية تمثل الطرز الجينية للأبوين؟\n- [ ] option-1 | أ. ZᴮZᴹ × ZᴹW\n- [x] option-2 | ب. ZᴮZᴮ × ZᴹW\n- [ ] option-3 | ج. ZᴹZᴹ × ZᴮW\n- [ ] option-4 | د. ZᴹZᵐ × ZᴮW\nexplanation:\nفي الطيور الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ؛\nاللون محمول على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>`. نرمز للبني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` وللأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` ، واجتماعهما في الذكر يعطي الكريم ذا المظهر الوسطي.\nكل البنات بنية وتأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` من الأب، فيكون الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` ؛\nوالأم البيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴹW</mtext></math>`.\nغاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` ، وغاميتا الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴹ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>`. النواتج نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴹ</mtext></math>` ذكور كريمية ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮW</mtext></math>` إناث بنية، مطابقة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4:4</mtext></math>`. الإجابة ب.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p087-q2-1\ntitle: تصنيف الأسئلة، السؤال 2، الفرع 1، صفحة 87\nquestion: السؤال 2، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب سليم من مرض نزف الدم الوراثي وأصابعه قصيرة لكن أحد والديه ذو أصابع طويلة، من فتاة أصابعها طويلة وسليمة من مرض نزف الدم الوراثي، فأنجبا طفلاً ذكراً أصابعه طويلة ومصاب بمرض نزف الدم الوراثي. صفة الأصابع القصيرة سائدة على الطويلة. استخدم G لجين الأصابع القصيرة، وH لجين عدم الإصابة بنزف الدم.\n\n1- ما الطرز الجينية لكل من الشاب والفتاة والطفل الذكر للصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد للأصابع القصيرة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للطويلة؛\nذو الأصابع الطويلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>`. الشاب قصير وله والد طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` ، فأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` منه ويكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` ؛\nوالفتاة والطفل طويلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>`.\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للمرض. الشاب السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>`. الطفل المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` من الأم، وهي سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالطرز للصفتين: الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg XᴴY</mtext></math>` ، الفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg XᴴXʰ</mtext></math>` ، والطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg XʰY</mtext></math>`. في الأصابع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg × gg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` ؛\nوفي المرض يعطي الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p087-q2-2\ntitle: تصنيف الأسئلة، السؤال 2، الفرع 2، صفحة 87\nquestion: السؤال 2، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب سليم من مرض نزف الدم الوراثي وأصابعه قصيرة لكن أحد والديه ذو أصابع طويلة، من فتاة أصابعها طويلة وسليمة من مرض نزف الدم الوراثي، فأنجبا طفلاً ذكراً أصابعه طويلة ومصاب بمرض نزف الدم الوراثي. صفة الأصابع القصيرة سائدة على الطويلة. استخدم G لجين الأصابع القصيرة، وH لجين عدم الإصابة بنزف الدم.\n\n2- ما احتمال إنجاب طفلة أصابعها طويلة ومصابة بمرض نزف الدم من بين النسل؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد للأصابع القصيرة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للطويلة؛\nذو الأصابع الطويلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>`. الشاب قصير وله والد طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>` ، فأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` منه ويكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` ؛\nوالفتاة والطفل طويلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gg</mtext></math>`.\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للمرض. الشاب السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>`. الطفل المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` من الأم، وهي سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nكل بنت تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` من الأب السليم؛\nبناته إما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXᴴ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>` ، وكلتاهما سليمة.\nإذن احتمال بنت مصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=0</mtext></math>` ، ومن ثم احتمال بنت طويلة الأصابع ومصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=0</mtext></math>` مهما كان احتمال طول الأصابع.\n:::\n\n:::exam-question\nid: bio-q-p087-q3\ntitle: تصنيف الأسئلة، السؤال 3، صفحة 87\nquestion: السؤال 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي الدجاج صفة الريش المخطط سائدة على صفة الريش غير المخطط، وهذه الصفة مرتبطة بالجنس. حصل تزاوج بين ذكر ريشه مخطط وأنثى غير مخططة الريش فكان الناتج: نصف الذكور مخطط الريش ونصفها غير مخطط، ونصف الإناث مخطط الريش ونصفها غير مخطط. ما الطرز الجينية والشكلية للآباء والأبناء؟\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للمخطط السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لغير المخطط؛\nالجين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` والذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>`. الأم غير مخططة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵇW</mtext></math>`. ووجود نسل غير مخطط يثبت أن الذكر المخطط يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` أيضاً، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵇ</mtext></math>`.\nغاميتا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵇ</mtext></math>` ، وغاميتا الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵇ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>`.\n\n| غاميت الأم | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵇ</mtext></math>` |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵇ</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵇ</mtext></math>` ذكر مخطط | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵇZᵇ</mtext></math>` ذكر غير مخطط |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮW</mtext></math>` أنثى مخططة | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵇW</mtext></math>` أنثى غير مخططة |\n\nكل فئة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` من النسل، فيكون داخل كل جنس نصف مخطط ونصف غير مخطط.\n:::\n\n:::exam-question\nid: bio-q-p087-q6-1\ntitle: تصنيف الأسئلة، السؤال 6، الفرع 1، صفحة 87\nquestion: السؤال 6، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من نزف الدم فصيلة دمه غير محددة، من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا طفلين ذكرين الأول مصاب بمرض نزف الدم فصيلة دمه O والثاني سليم وفصيلة دمه B. تبين أنه لا يستطيع أي الوالدين التبرع للآخر بالدم، واحتوت أغشية خلايا الدم الحمراء للأم على الأنتيجينB.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- اكتب الطرز الجينية لكل من الرجل والزوجة للصفتين معاً.\n\nsolution:\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`. الابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيحمل كلا الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`. الأم تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nولأنها تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` وليست `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. في نموذج نقل الكريات، فصيلة A تحمل مولد A ومضاد B، وفصيلة B تحمل مولد B ومضاد A؛ لذلك يفشل النقل بينهما في الاتجاهين.\nعدم التبرع بينهما بالاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الأب السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` ؛\nوجود ابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` وآخر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` يعني أن الأم تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` ، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالنتيجة: الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XᴴY</mtext></math>` ، والزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XᴴXʰ</mtext></math>`. يحمل الابنان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب، فتحدد بويضتا الأم اختلاف حالتهما المرضية.\n:::\n\n:::exam-question\nid: bio-q-p087-q6-2\ntitle: تصنيف الأسئلة، السؤال 6، الفرع 2، صفحة 87\nquestion: السؤال 6، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من نزف الدم فصيلة دمه غير محددة، من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا طفلين ذكرين الأول مصاب بمرض نزف الدم فصيلة دمه O والثاني سليم وفصيلة دمه B. تبين أنه لا يستطيع أي الوالدين التبرع للآخر بالدم، واحتوت أغشية خلايا الدم الحمراء للأم على الأنتيجينB.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- ما احتمال إنجاب طفل ذكر سليم من المرض وفصيلة دمه B من بين النسل؟\n\nsolution:\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`. الابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيحمل كلا الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`. الأم تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nولأنها تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` وليست `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. في نموذج نقل الكريات، فصيلة A تحمل مولد A ومضاد B، وفصيلة B تحمل مولد B ومضاد A؛ لذلك يفشل النقل بينهما في الاتجاهين.\nعدم التبرع بينهما بالاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الأب السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` ؛\nوجود ابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` وآخر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` يعني أن الأم تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` ، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × Iᴮi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=1/4</mtext></math>`.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY × XᴴXʰ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXᴴ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` بأرباع؛\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nبالاستقلال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/4)×(1/4)=1/16</mtext></math>` من جميع النسل.\n:::\n\n:::exam-question\nid: bio-q-p088-q10-1\ntitle: تصنيف الأسئلة، السؤال 10، الفرع 1، صفحة 88\nquestion: السؤال 10، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عادي الشعر فصيلة دمه B نقي الطراز الجيني للصفة سليم من مرض عسر النمو العضلي التدريجي من فتاة صلعاء وسليمة من عسر النمو العضلي التدريجي ولكن والدتها مصابة به. عملية نقل الدم من الشاب إلى الفتاة تنجح ولا تنجح من الفتاة إلى الشاب.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- ما الطرز الجينية لكل من الشاب والفتاة؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع صفة جسمية متأثرة بالجنس؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` يسود في الأنثى. لذا الشاب طبيعي الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والفتاة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nالشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>`. نجاح إعطائه الدم للفتاة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`.\nعسر النمو العضلي متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمصاب. الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ؛\nالفتاة سليمة وأمها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` ، فتلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nإذن الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ IᴮIᴮ XᴿY</mtext></math>` ، والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb IᴬIᴮ XᴿXʳ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p088-q10-2\ntitle: تصنيف الأسئلة، السؤال 10، الفرع 2، صفحة 88\nquestion: السؤال 10، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عادي الشعر فصيلة دمه B نقي الطراز الجيني للصفة سليم من مرض عسر النمو العضلي التدريجي من فتاة صلعاء وسليمة من عسر النمو العضلي التدريجي ولكن والدتها مصابة به. عملية نقل الدم من الشاب إلى الفتاة تنجح ولا تنجح من الفتاة إلى الشاب.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- ما الطرز الجينية لغاميتات الشاب؟\n\nsolution:\nالمطلوب غاميتات الشاب؛ نحدد أليلاته للصفات الثلاث.\nفي نموذج الصلع، يسودb في الذكر؛ لذلك طبيعي الشعر هوb⁺b⁺.\nفصيلةB النقية طرازهاIᴮIᴮ.\nعسر النمو العضلي صفة متنحية علىX؛ والشاب سليم، فطرازهXᴿY.\nكل غاميت يحمل أليلاً واحداً من كل جين. يثبتb⁺ وIᴮ في جميع غاميتاته، ويتنوع الكروموسوم الجنسي بينXᴿ وY.\nإذن النوعان:\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><msup><mi>I</mi><mi>B</mi></msup><msup><mi>X</mi><mi>R</mi></msup><mo separator="true">,</mo><mspace width="1em"/><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><msup><mi>I</mi><mi>B</mi></msup><mi>Y</mi></mrow></math>\n```\n\n\nاحتمال كل نوع **1/2**.\n\n**المصدر:** الصفحات 30، 32، 33 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p088-q10-3\ntitle: تصنيف الأسئلة، السؤال 10، الفرع 3، صفحة 88\nquestion: السؤال 10، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب عادي الشعر فصيلة دمه B نقي الطراز الجيني للصفة سليم من مرض عسر النمو العضلي التدريجي من فتاة صلعاء وسليمة من عسر النمو العضلي التدريجي ولكن والدتها مصابة به. عملية نقل الدم من الشاب إلى الفتاة تنجح ولا تنجح من الفتاة إلى الشاب.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما احتمال إنجاب ولد أصلع فصيلة دمه B وسليم من عسر النمو العضلي التدريجي؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع صفة جسمية متأثرة بالجنس؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` يسود في الأنثى. لذا الشاب طبيعي الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والفتاة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nالشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>`. نجاح إعطائه الدم للفتاة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`.\nعسر النمو العضلي متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمصاب. الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ؛\nالفتاة سليمة وأمها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` ، فتلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ × bb</mtext></math>` يعطي جميع الأبناء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nكل الذكور صلع وكل الإناث طبيعية.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ × IᴬIᴮ</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nالمرض : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY × XᴿXʳ</mtext></math>` يعطي ربع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ذكوراً سليمة.\nاحتمال ولد أصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/4)×1×(1/2)=1/8</mtext></math>` من جميع النسل.\n:::\n\n:::exam-question\nid: bio-q-p088-q11-1\ntitle: تصنيف الأسئلة، السؤال 11، الفرع 1، صفحة 88\nquestion: السؤال 11، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B والدته سليمة من عمى الألوان نقية من امرأة غير مصابة بالمرض وفصيلة دمها مجهولة، فأنجبا طفلاً فصيلة دمه A مصاباً بالمرض. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- اكتب الطرز الجينية للرجل والمرأة والطفل للصفتين معاً.\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للرؤية الطبيعية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` لعمى الألوان المتنحي على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`. أم الرجل نقية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXᴿ</mtext></math>` ، فأعطته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` ؛\nلذلك هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>`. الابن المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من أمه السليمة، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nفي الدم الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح عطائه للزوجة وفشل العكس يجعل الزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` منها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالطرز النهائية: الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XᴿY</mtext></math>` ، المرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ XᴿXʳ</mtext></math>` ، والطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XʳY</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p088-q11-2\ntitle: تصنيف الأسئلة، السؤال 11، الفرع 2، صفحة 88\nquestion: السؤال 11، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B والدته سليمة من عمى الألوان نقية من امرأة غير مصابة بالمرض وفصيلة دمها مجهولة، فأنجبا طفلاً فصيلة دمه A مصاباً بالمرض. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- اكتب الطرز الجينية لغاميتات المرأة.\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للرؤية الطبيعية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` لعمى الألوان المتنحي على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`. أم الرجل نقية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXᴿ</mtext></math>` ، فأعطته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` ؛\nلذلك هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>`. الابن المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من أمه السليمة، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nفي الدم الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح عطائه للزوجة وفشل العكس يجعل الزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` منها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nطراز المرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ XᴿXʳ</mtext></math>` ؛\nتحمل البويضة أليلاً واحداً للدم وكروموسوم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحداً.\nبالتوزيع المستقل : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬXᴿ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬXʳ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮXᴿ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮXʳ</mtext></math>` ، ولكل منها احتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p088-q11-3\ntitle: تصنيف الأسئلة، السؤال 11، الفرع 3، صفحة 88\nquestion: السؤال 11، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B والدته سليمة من عمى الألوان نقية من امرأة غير مصابة بالمرض وفصيلة دمها مجهولة، فأنجبا طفلاً فصيلة دمه A مصاباً بالمرض. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما نوع الوراثة لمرض عمى الألوان؟\n\nsolution:\n**الإجابة:** صفة متنحية مرتبطة بالكروموسومX.\n\n**الشاهد من الكتاب:**\n\n> XʰY مصاب؛ XᴴXʰ حاملات.\n\n\n\n[عرض الشاهد الأصلي في الكتاب](assets/lessons/curriculum-evidence/5811d6a047dd54cba595.webp)\n\nيبين مثال دليل المعلم أنXʰY مصاب، وأنXᴴXʰ حاملة؛ أي إنh متنحٍّ أمامH ومحمول علىX.\n\n:::\n\n:::exam-question\nid: bio-q-p090-q19-1\ntitle: تصنيف الأسئلة، السؤال 19، الفرع 1، صفحة 90\nquestion: السؤال 19، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل الأجسام المضادة في بلازما دمه من نوعA فقط وغير محدد الطراز الشكلي لصفة نزف الدم من فتاة غير مصابة بنزف الدم وغير محددة فصيلة دمها، فأنجبا بنتاً فصيلة دمهاA ومصابة بنزف الدم. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى زوجته.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- اكتب الطراز الشكلي للرجل لصفة نزف الدم.\n\nsolution:\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمصاب. البنت المصابة لا بد أن تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` ، إذ لا يصيبها وجود أليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` واحد مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>`.\nتأخذ البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أبيها؛\nلذا أعطاها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ويكون الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>`. إذن الرجل مصاب بنزف الدم.\n:::\n\n:::exam-question\nid: bio-q-p090-q19-3\ntitle: تصنيف الأسئلة، السؤال 19، الفرع 3، صفحة 90\nquestion: السؤال 19، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل الأجسام المضادة في بلازما دمه من نوعA فقط وغير محدد الطراز الشكلي لصفة نزف الدم من فتاة غير مصابة بنزف الدم وغير محددة فصيلة دمها، فأنجبا بنتاً فصيلة دمهاA ومصابة بنزف الدم. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى زوجته.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- اكتب الطرز الجينية لكل من الرجل والفتاة والبنت.\n\nsolution:\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تستلزم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` وأماً تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nوالأم سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده عند الرجل يعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح إعطائه للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` لا تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من أبيها، بل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nفالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالنتيجة: الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XʳY</mtext></math>` ، الفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ XᴿXʳ</mtext></math>` ، والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XʳXʳ</mtext></math>`. يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p090-q19-4\ntitle: تصنيف الأسئلة، السؤال 19، الفرع 4، صفحة 90\nquestion: السؤال 19، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل الأجسام المضادة في بلازما دمه من نوعA فقط وغير محدد الطراز الشكلي لصفة نزف الدم من فتاة غير مصابة بنزف الدم وغير محددة فصيلة دمها، فأنجبا بنتاً فصيلة دمهاA ومصابة بنزف الدم. لم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت من الزوج إلى زوجته.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n4- ما احتمال إنجاب ذكر فصيلة دمهB وسليم من نزف الدم؟\n\nsolution:\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تستلزم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` وأماً تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nوالأم سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده عند الرجل يعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح إعطائه للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` لا تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من أبيها، بل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nفالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi × IᴬIᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالمرض والجنس: الأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ، وباستقلال الدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/4)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q28-1\ntitle: تصنيف الأسئلة، السؤال 28، الفرع 1، صفحة 92\nquestion: السؤال 28، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع نقي سليم من نزف الدم وعسر النمو العضلي التدريجي من فتاة شعرها طبيعي وسليمة من نزف الدم وعسر النمو العضلي التدريجي، ووالدتها مصابة بنزف الدم وعسر النمو العضلي التدريجي. أنجبت العائلة طفلاً ذكراً أصلع نقياً ومصاباً بالمرضين. على فرض عدم حدوث عبور، ارمز لجين نزف الدمh ولجين عسر النمو العضلي التدريجيr.\n\n1- اكتب الطرز الجينية لكل من الطفل والرجل والفتاة.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nنزف الدم وعسر النمو العضلي صفتان متنحيتان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمرضين. نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]</mtext></math>` لحمل أليلي السلامة على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` نفسه.\nالصلع متأثر بالجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. الرجل أصلع نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، والطفل أصلع نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nأعطته الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع أنها طبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالرجل السليم من المرضين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]Y</mtext></math>`. أم الفتاة مصابة بالمرضين، فتمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[hr]</mtext></math>` ؛\nوالفتاة سليمة فتحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]</mtext></math>` الآخر.\nإذن الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb X[hr]Y</mtext></math>` ، الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb X[HR]Y</mtext></math>` ، والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b X[HR]X[hr]</mtext></math>`. أخذ الطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من أبيه و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[hr]</mtext></math>` من أمه.\n:::\n\n:::exam-question\nid: bio-q-p092-q28-2\ntitle: تصنيف الأسئلة، السؤال 28، الفرع 2، صفحة 92\nquestion: السؤال 28، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع نقي سليم من نزف الدم وعسر النمو العضلي التدريجي من فتاة شعرها طبيعي وسليمة من نزف الدم وعسر النمو العضلي التدريجي، ووالدتها مصابة بنزف الدم وعسر النمو العضلي التدريجي. أنجبت العائلة طفلاً ذكراً أصلع نقياً ومصاباً بالمرضين. على فرض عدم حدوث عبور، ارمز لجين نزف الدمh ولجين عسر النمو العضلي التدريجيr.\n\n2- اكتب الطرز الجينية لغاميتات الرجل والفتاة.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nنزف الدم وعسر النمو العضلي صفتان متنحيتان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمرضين. نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]</mtext></math>` لحمل أليلي السلامة على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` نفسه.\nالصلع متأثر بالجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. الرجل أصلع نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، والطفل أصلع نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nأعطته الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع أنها طبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالرجل السليم من المرضين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]Y</mtext></math>`. أم الفتاة مصابة بالمرضين، فتمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[hr]</mtext></math>` ؛\nوالفتاة سليمة فتحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[HR]</mtext></math>` الآخر.\nدون عبور تبقى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hr</mtext></math>` معاً، فلا تنتج الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Hr]</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[hR]</mtext></math>`.\nالرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb X[HR]Y</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bX[HR]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bY</mtext></math>` مناصفة.\nالفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b X[HR]X[hr]</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺X[HR]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bX[HR]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺X[hr]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bX[hr]</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ؛\nجين الشعر جسمي يتوزع مستقلاً عن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q29-3\ntitle: تصنيف الأسئلة، السؤال 29، الفرع 3، صفحة 92\nquestion: السؤال 29، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nرجل أصلع غير نقي مصاب بعمى الألوان تزوج امرأة طبيعية الشعر غير مصابة بعمى الألوان، والدها طبيعي الشعر ومصاب بعمى الألوان ووالدتها تظهر صفة الصلع. جين الرؤية الطبيعيةH سائد على جين عمى الألوانh.\n\n3- ما احتمال إنجاب أنثى مصابة بعمى الألوان؟\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>`. المرأة سليمة وأبوها مصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ، فأخذت منه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` ؛\nوبما أنها سليمة فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nغاميتا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ، وغاميتا الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>`.\nالنواتج : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>` بنت سليمة، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰXʰ</mtext></math>` بنت مصابة، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` ولد سليم، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ولد مصاب.\nالأنثى المصابة حالة من أربع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/4</mtext></math>` من جميع النسل، أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` بين البنات وحدهن. لا نضيف عامل الشعر لأنه غير مطلوب.\n:::\n\n:::exam-question\nid: bio-q-p093-q30-1\ntitle: تصنيف الأسئلة، السؤال 30، الفرع 1، صفحة 93\nquestion: السؤال 30، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nالجدول المرفق يظهر نتائج تزاوجات مختلفة في أحد أنواع الأرانب.\n\n| الطرز الشكلية للآباء | ذكور بيضاء | ذكور سوداء | إناث رمادية | إناث سوداء |\n|---|---|---|---|---|\n| أرنب أسود × أرنبة رمادية |2|2|2|2|\n| أرنب أبيض × أرنبة سوداء |صفر|2|2|صفر|\n\n1- ما الطرز الجينية للأبوين في التزاوج الأول والتزاوج الثاني؟\nsolution:\nيفسر اللون هنا نموذج سيادة غير تامة على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X: XᴮXᴮ</mtext></math>` أنثى سوداء، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵂXᵂ</mtext></math>` بيضاء، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>` رمادية. الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` يظهر لون أليله الوحيد.\nالأول: أسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮY ×</mtext></math>` رمادية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>`. غاميتا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵂ</mtext></math>` ؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᴮ</mtext></math>` سوداء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>` رمادية و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮY</mtext></math>` أسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵂY</mtext></math>` أبيض بأرباع، مطابقة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` لكل فئة.\nالثاني: أبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵂY ×</mtext></math>` سوداء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᴮ</mtext></math>` ؛\nتعطي الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴮ</mtext></math>` فقط، فينتج نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>` إناث رمادية ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮY</mtext></math>` ذكور سوداء. لا توجد ذكور بيضاء ولا إناث سوداء، كما في الجدول.\n:::\n\n:::exam-question\nid: bio-q-p093-q30-2\ntitle: تصنيف الأسئلة، السؤال 30، الفرع 2، صفحة 93\nquestion: السؤال 30، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nالجدول المرفق يظهر نتائج تزاوجات مختلفة في أحد أنواع الأرانب.\n\n| الطرز الشكلية للآباء | ذكور بيضاء | ذكور سوداء | إناث رمادية | إناث سوداء |\n|---|---|---|---|---|\n| أرنب أسود × أرنبة رمادية |2|2|2|2|\n| أرنب أبيض × أرنبة سوداء |صفر|2|2|صفر|\n\n2- ما نوع الوراثة؟\nsolution:\nيفسر اللون هنا نموذج سيادة غير تامة على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X: XᴮXᴮ</mtext></math>` أنثى سوداء، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵂXᵂ</mtext></math>` بيضاء، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>` رمادية. الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` يظهر لون أليله الوحيد.\nالأنثى الرمادية تجمع أليلي اللونين فيظهر مظهر وسطي؛\nهذه سيادة غير تامة.\nوالتزاوج الثاني أبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵂY ×</mtext></math>` سوداء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᴮ</mtext></math>` يعطي الذكور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮY</mtext></math>` سوداء والإناث `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴮXᵂ</mtext></math>` رمادية؛\nاختلاف اللون مع الجنس يفسره حمل الجين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\nإذن الوراثة سيادة غير تامة مرتبطة بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، وفق النموذج المعطى لهذا النوع.\n:::\n\n:::exam-question\nid: bio-q-p093-q33-1\ntitle: تصنيف الأسئلة، السؤال 33، الفرع 1، صفحة 93\nquestion: السؤال 33، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل من امرأة فأنجبا طفلة مصابة بعمى الألوان وطفلاً سليماً من المرض. جين عدم الإصابة بعمى الألوانR سائد على جين الإصابةr.\n\n1- اكتب الطرز الجينية للأبوين.\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وأخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأم. الطفل الذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` من الأم؛\nلذلك الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nإذن الطراز الجيني للأبوين: الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` والمرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`. لا يمكن أن تكون الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` لأنها عندئذ لا تمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` لابن سليم.\n:::\n\n:::exam-question\nid: bio-q-p093-q33-2\ntitle: تصنيف الأسئلة، السؤال 33، الفرع 2، صفحة 93\nquestion: السؤال 33، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل من امرأة فأنجبا طفلة مصابة بعمى الألوان وطفلاً سليماً من المرض. جين عدم الإصابة بعمى الألوانR سائد على جين الإصابةr.\n\n2- اكتب الطرز الشكلية للأبوين.\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وأخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأم. الطفل الذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` من الأم؛\nلذلك الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` مصاب لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` لا يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` الذي يغطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>`. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` سليمة حاملة؛\nأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سائد فيمنع ظهور المرض مع أنها تنقله إلى بعض أبنائها.\nإذن الطرازان الشكليان: أب مصاب وأم سليمة حاملة.\n:::\n\n:::exam-question\nid: bio-q-p093-q33-3\ntitle: تصنيف الأسئلة، السؤال 33، الفرع 3، صفحة 93\nquestion: السؤال 33، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل من امرأة فأنجبا طفلة مصابة بعمى الألوان وطفلاً سليماً من المرض. جين عدم الإصابة بعمى الألوانR سائد على جين الإصابةr.\n\n3- اكتب الطراز الجيني للطفل.\nsolution:\nالطفل المقصود ذكر سليم؛\nالذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` ويأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من أبيه و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أمه. ولأن عمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، فإن سلامة الذكر تستلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>`.\nإذن طرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ؛\nولا يصح كتابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` لذكر في هذا النموذج.\n:::\n\n:::exam-question\nid: bio-q-p093-q33-4\ntitle: تصنيف الأسئلة، السؤال 33، الفرع 4، صفحة 93\nquestion: السؤال 33، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل من امرأة فأنجبا طفلة مصابة بعمى الألوان وطفلاً سليماً من المرض. جين عدم الإصابة بعمى الألوانR سائد على جين الإصابةr.\n\n4- اكتب الطراز الجيني للطفلة.\nsolution:\nالطفلة أنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` ومصابة بعمى الألوان المتنحي. وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` واحد يجعل الأنثى سليمة، لذا لا تصاب إلا إذا حمل كلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` الأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>`.\nطرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` ، أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ومن الأم الحاملة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p093-q33-5\ntitle: تصنيف الأسئلة، السؤال 33، الفرع 5، صفحة 93\nquestion: السؤال 33، الفرع 5\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل من امرأة فأنجبا طفلة مصابة بعمى الألوان وطفلاً سليماً من المرض. جين عدم الإصابة بعمى الألوانR سائد على جين الإصابةr.\n\n5- ما احتمال إنجاب بنت سليمة من المرض؟\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وأخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأم. الطفل الذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` من الأم؛\nلذلك الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>`.\n\n| غاميت الأم | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` بنت سليمة | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ولد سليم |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` بنت مصابة | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ولد مصاب |\n\nالبنت السليمة حالة من أربع متساوية : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4=25%</mtext></math>` من كل النسل؛\nوهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` بين البنات فقط.\n:::\n\n:::exam-question\nid: bio-q-p094-q37\ntitle: تصنيف الأسئلة، السؤال 37، صفحة 94\nquestion: السؤال 37\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعمى الألوان وخصلة الشعر البيضاء في الإنسان صفتان مرتبطتان بالجنس وجيناتهما تحمل على نفس الكروموسوم. حصل تزاوج بين رجل سليم من عمى الألوان وذي خصلة شعر بيضاء بأنثى غير متماثلة الجينات لكلا الصفتين فكانت النتائج:25% ذكور سليمة من عمى الألوان وبشعر طبيعي؛25% ذكور مصابة بعمى الألوان وبخصلة بيضاء؛25% إناث سليمة من عمى الألوان وبخصلة بيضاء؛25% إناث سليمة من عمى الألوان وبشعر طبيعي. فسر النتائج على أسس وراثية مستخدماًB لسليم من عمى الألوان وb لمصاب، وR لشعر طبيعي وr لخصلة شعر بيضاء.\nsolution:\nنلتزم النموذج المفترض في السؤال: الجينان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سليم من عمى الألوان يسود على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` شعر طبيعي يسود على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للخصلة البيضاء. الارتباط يعني انتقال الأليلين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحد معاً ما لم يقع عبور.\nالرجل سليم ذو خصلة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Br]Y</mtext></math>`. الأم غير متماثلة؛\nنتيجتا الذكور تكشفان نوعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` لديها : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BR]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[br]</mtext></math>` ، لأنها تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` للذكور وهم يأخذون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب.\nغاميتا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Br]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ؛\nوالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BR]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[br]</mtext></math>` مناصفة دون مؤتلفات ظاهرة.\nالنواتج بأرباع : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BR]Y</mtext></math>` ذكر سليم طبيعي الشعر؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[br]Y</mtext></math>` ذكر مصاب ذو خصلة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BR]X[Br]</mtext></math>` أنثى سليمة طبيعية؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Br]X[br]</mtext></math>` أنثى سليمة ذات خصلة.\nكل فئة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/2)=25%</mtext></math>`. هذا نموذج المصدر للخصلة البيضاء وليس تعميماً طبياً عن وراثتها.\n:::\n\n:::exam-question\nid: bio-q-p094-q39-2\ntitle: تصنيف الأسئلة، السؤال 39، الفرع 2، صفحة 94\nquestion: السؤال 39، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nحدث تزاوج بين طائر ذكر أسود الريش وأنثى بيضاء الريش فكان الناتج:(4) إناث سوداء الريش، و(4) ذكور رمادية الريش. إذا رمزنا لجين اللون الأسودB ولجين اللون الأبيضT، اكتب الطرز الجينية للأبوين والأفراد الناتجة.\nsolution:\nالذكر في الطيور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ؛\nلون الريش هنا على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` ، واجتماع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` الأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` الأبيض ينتج الرمادي الوسطي.\nالأب الأسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` فقط؛\nالأم البيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵀW</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵀ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵀ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵀ</mtext></math>` ذكراً رمادياً، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮW</mtext></math>` أنثى سوداء.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵀW</mtext></math>` ، والنسل نصف ذكور رمادية ونصف إناث سوداء، مطابق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4:4</mtext></math>`.\n:::\n\n:::mcq\nid: bio-q-p102-q6\ntitle: صفحة 102، السؤال 6\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 102\nquestion: ما الطرز الجينية المحتملة لآباء أنجبوا بنتاً مصابة بعمى الألوان وولداً سليماً من عمى الألوان؟\n- [ ] option-1 | \\(X^aX^a \\times X^aY\\)\n- [ ] option-2 | \\(X^aX^a \\times X^AY\\)\n- [x] option-3 | \\(X^AX^a \\times X^aY\\)\n- [ ] option-4 | \\(X^AX^a \\times X^AY\\)\nexplanation:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` مصاب. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵃXᵃ</mtext></math>` تتطلب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵃ</mtext></math>` من كلا الأبوين، فيلزم أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵃY</mtext></math>`.\nالولد السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴬY</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴬ</mtext></math>` من الأم؛\nومع ضرورة منحها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵃ</mtext></math>` للبنت تصبح الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴬXᵃ</mtext></math>`.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴬXᵃ × XᵃY</mtext></math>` ، الاختيار الثالث. غاميتات الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵃ</mtext></math>` والأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵃ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` تحقق البنت المصابة والولد السليم.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p038-q1-3\ntitle: الرزمة التعليمية، صفحة 38، السؤال 1-3\nquestion: ما النمط الوراثي الذي يفسر ترجمة الطراز الجيني غير متماثل الأليلات إلى طرز شكلية مختلفة عند الذكور والإناث؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\n- [x] option-1 | الصفات المتأثرة بالجنس\n- [ ] option-2 | الجينات المتعددة\n- [ ] option-3 | الأليلات المتعددة\n- [ ] option-4 | الصفات المرتبطة بالجنس\nexplanation:\n**الإجابة:** الصفات المتأثرة بالجنس\n\n**الشاهد من الكتاب:**\n\n> هي الصفات التي تحمل جيناتها على الكروموسومات الجسمية، ولكنها تتأثر بالهرمونات الجنسية، ومن الأمثلة عليها صفة الصلع عند الإنسان. حيث يكون جين الصلع(b) سائداً على جين وجود الشعر الطبيعي(b⁺) عند الذكور، أما عند الإناث فيكون جين وجود الشعر الطبيعي سائداً على جين الصلع.\n\n**المصدر:** صفحة 33 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-3\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-3\nquestion: ما نمط الوراثة الذي يفسر ترجمة الطراز الجيني (Dd) لدى نوع من أنواع الغزلان إلى أنثى بقرون وذكر بدون قرون؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [x] option-1 | الصفات المتأثرة بالجنس\n- [ ] option-2 | الصفات المرتبطة بالجنس\n- [ ] option-3 | الجينات المتعددة\n- [ ] option-4 | الأليلات المتعددة\nexplanation:\nالطراز غير المتماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Dd</mtext></math>` نفسه يظهر في الأنثى بقرون وفي الذكر بدون قرون.\nهذا يوافق صفة متأثرة بالجنس: الجين جسمي، لكن علاقة السيادة تتغير تبعاً للجنس والبيئة الهرمونية.\nإذن الاختيار الأول «الصفات المتأثرة بالجنس». اختلاف المظهر وحده لا يجعل الجين محمولاً على كروموسوم جنسي.\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-11\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-11\nquestion: تزوج شاب بشعر من أنثى بشعر (غير متماثلة الجينات)، ما احتمال إنجاب طفل ذكر أصلع من بين الأبناء؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [x] option-1 | 1/4\n- [ ] option-2 | 1/2\n- [ ] option-3 | 3/4\n- [ ] option-4 | 1\nexplanation:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nفي نموذج الصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` يسود عند الإناث؛\nلذلك الشاب الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` والمرأة الطبيعية غير المتماثلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ؛\nالناتج نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nبين الذكور يكون الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` أصلع، فيكون احتمال الصلع للذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`. احتمال الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nالاحتمال من كل الأبناء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/2)=1/4</mtext></math>`.\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p071-q6\ntitle: تصنيف الأسئلة، السؤال 6، صفحة 71\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 71\nquestion: في بعض سلالات الأرانب تكون الإناث عادة أكبر حجماً من الذكور (وهي صفة سائدة في الإناث)، حصل تزاوج بين ذكر حجمه صغير وأنثى حجمها كبير كلاهما يحمل الطراز الجيني نفسه، ما نسبة الطرز الشكلية بين الذكور الناتجة؟\n- [ ] option-1 | أ. 1 صغير الحجم: 1 كبير الحجم\n- [x] option-2 | ب. 3 صغير الحجم: 1 كبير الحجم\n- [ ] option-3 | ج. 2 صغير الحجم: 1 كبير الحجم\n- [ ] option-4 | د. 1 صغير الحجم: 3 كبير الحجم\nexplanation:\nصفة الحجم متأثرة بالجنس: نرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` للكبير و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>l</mtext></math>` للصغير؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` يسود في الإناث ويتنحى في الذكور.\nاختلاف مظهر الأبوين مع تماثل طرازهما يعني أنهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ll</mtext></math>` ؛\nالذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ll</mtext></math>` صغير والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ll</mtext></math>` كبيرة.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ll × Ll</mtext></math>` ؛\nغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>L</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>l</mtext></math>` ؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 LL</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2 Ll</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 ll</mtext></math>`.\nفي الذكور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>LL</mtext></math>` فقط كبير، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ll</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ll</mtext></math>` صغيران؛\nلذا صغير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2+1/4)=3/4</mtext></math>` وكبير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/4</mtext></math>`. النسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` صغير : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` كبير، الاختيار ب.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q32\ntitle: تصنيف الأسئلة، السؤال 32، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: أيّ الطرز الجينية الآتية يمكن أن يمثل شابًا أصلع ومصابًا بنزف الدم، وفق نموذج الوراثة في الدرس؟\n\n- [ ] option-1 | أ. XᴴYbb\n- [x] option-2 | ب. XʰYbb⁺\n- [ ] option-3 | ج. XᴴYbb⁺\n- [ ] option-4 | د. XʰYb⁺b⁺\nexplanation:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nنزف الدم متنح مرتبط بـ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\nالمصاب الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ، فيستبعد الخياران اللذان يحملان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴴ</mtext></math>`.\nالصلع صفة جسمية متأثرة بالجنس؛\nالذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb⁺</mtext></math>` أصلع، أما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` فطبيعي الشعر.\nمن البدائل وحده `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰYbb⁺</mtext></math>` يجمع المرض والصلع، وهو ب. ليس المقصود أن كل أصلع يجب أن يكون هجيناً، بل هذا الطراز الموافق المتاح.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p083-q33\ntitle: تصنيف الأسئلة، السؤال 33، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: إذا تزوج شاب أصلع من فتاة تماثله جينياً وتخالفه شكلياً، فما احتمال إنجاب طفل ذكر ذو شعر طبيعي؟\n- [x] option-1 | أ. 1/8\n- [ ] option-2 | ب. 1/4\n- [ ] option-3 | ج. 1/2\n- [ ] option-4 | د. 3/4\nexplanation:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. لا يختلف مظهر الرجل والمرأة مع تماثل الجينات إلا في الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` ، وغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nالذكر الطبيعي يجب أن يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، واحتماله الجيني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nاحتمال ذكر طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/4)=1/8</mtext></math>` من كل النسل؛\nالاختيار أ.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p086-q57\ntitle: تصنيف الأسئلة، السؤال 57، صفحة 86\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nquestion: شاب أصلع والده بشعر طبيعي، ما الطراز الجيني للشاب؟\n- [x] option-1 | أ. b⁺b\n- [ ] option-2 | ب. bb\n- [ ] option-3 | ج. b⁺b⁺\n- [ ] option-4 | د. XᵇY\nexplanation:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع جسمي متأثر بالجنس؛\nالذكر الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والذكر الأصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nوالد الشاب طبيعي الشعر، فلا يعطي إلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>`. الشاب أصلع فلا بد أن يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` أيضاً، ويكون قد أخذه من أمه.\nإذن الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ، الاختيار أ؛\nليس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵇY</mtext></math>` لأن جين الصلع هنا جسمي.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p087-q4-1\ntitle: تصنيف الأسئلة، السؤال 4، الفرع 1، صفحة 87\nquestion: السؤال 4، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمه A، كان والده ذا شعر طبيعي، من فتاة غير صلعاء وفصيلة دمها غير معروفة، فأنجبا طفلة صلعاء فصيلة دمها B، ولم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت عملية نقل الدم من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- اكتب الطرز الجينية لكل من الزوج والزوجة والطفلة.\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للطبيعي؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكور ومتنح في الإناث. والد الرجل طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، لذا الرجل الأصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من أمها الطبيعية، فتكون الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. نجاح إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nوالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من أمها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من أبيها، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Iᴬi</mtext></math>` ، الزوجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b IᴬIᴮ</mtext></math>` ، الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb Iᴮi</mtext></math>`.\nتزاوج الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يسمح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، وتزاوج الدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × IᴬIᴮ</mtext></math>` يسمح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` كما يلزم.\n:::\n\n:::exam-question\nid: bio-q-p087-q4-3\ntitle: تصنيف الأسئلة، السؤال 4، الفرع 3، صفحة 87\nquestion: السؤال 4، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 87\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمه A، كان والده ذا شعر طبيعي، من فتاة غير صلعاء وفصيلة دمها غير معروفة، فأنجبا طفلة صلعاء فصيلة دمها B، ولم تنجح عملية نقل الدم من الزوجة إلى زوجها بينما نجحت عملية نقل الدم من الزوج إلى الزوجة.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما احتمال إنجاب ولد أصلع فصيلة دمه A؟\n\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للطبيعي؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكور ومتنح في الإناث. والد الرجل طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، لذا الرجل الأصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من أمها الطبيعية، فتكون الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. نجاح إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` ؛\nوالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من أمها و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من أبيها، فالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2 b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 bb</mtext></math>`. بين الذكور الأصلع هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، فاحتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × IᴬIᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=1/2</mtext></math>`.\nاحتمال ولد أصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A=(1/2)×(3/4)×(1/2)=3/16</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p088-q8-1\ntitle: تصنيف الأسئلة، السؤال 8، الفرع 1، صفحة 88\nquestion: السؤال 8، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع سليم من مرض نزف الدم وفصيلة دمه B من فتاة ذات شعر طبيعي ومصابة بنزف الدم وفصيلة دمها غير معروفة، فأنجبا أنثى صلعاء فصيلة دمها A وذكراً ذا شعر طبيعي فصيلة دمه B (متماثل الجينات).\n\n1- اكتب الطرز الجينية للأبوين للصفات الثلاث معاً.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر ويتنحى في الأنثى.\nالبنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في الأبوين، والابن الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` فيهما؛\nلذا كلاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` والمرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰXʰ</mtext></math>` وفق حالتيهما.\nالدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأب، لكن البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` منه و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` من الأم؛\nفيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`. والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` النقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` أيضاً عند الأم، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XᴴY Iᴮi</mtext></math>` ؛\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʰXʰ IᴬIᴮ</mtext></math>`. يجتمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` بسيادة مشتركة لدى الأم، ويسود كل منهما على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p088-q8-2\ntitle: تصنيف الأسئلة، السؤال 8، الفرع 2، صفحة 88\nquestion: السؤال 8، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع سليم من مرض نزف الدم وفصيلة دمه B من فتاة ذات شعر طبيعي ومصابة بنزف الدم وفصيلة دمها غير معروفة، فأنجبا أنثى صلعاء فصيلة دمها A وذكراً ذا شعر طبيعي فصيلة دمه B (متماثل الجينات).\n\n2- اكتب الطرز الجينية لغاميتات الأم.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر ويتنحى في الأنثى.\nالبنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في الأبوين، والابن الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` فيهما؛\nلذا كلاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` والمرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰXʰ</mtext></math>` وفق حالتيهما.\nالدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأب، لكن البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` منه و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` من الأم؛\nفيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`. والابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` النقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` أيضاً عند الأم، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`.\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b IᴬIᴮ XʰXʰ</mtext></math>` ؛\nجميع بويضاتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` ، وتأخذ واحدة من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` وواحدة من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>`.\nبالتوزيع المستقل : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺IᴬXʰ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺IᴮXʰ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bIᴬXʰ</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bIᴮXʰ</mtext></math>` ؛\nاحتمال كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p089-q12-1\ntitle: تصنيف الأسئلة، السؤال 12، الفرع 1، صفحة 89\nquestion: السؤال 12، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ولون عيونه عسلية كان والده ذو شعر طبيعي وأزرق العينين، من فتاة ذات شعر طبيعي ولون عيونها عسلية فأنجبا طفلة تظهر صفة الصلع ذات عيون زرقاء. أجب مستخدماًb وb⁺ لصفة الصلع وA للعيون العسلية وa للزرقاء.\n\n1- اكتب الطرز الجينية للأب والأم والطفلة.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nللصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت أن أمها الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nوفق النموذج المبسط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق. الرجل عسلي وأبوه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` ؛\nوالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` تثبت أن أمها العسلية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Aa</mtext></math>` ، الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Aa</mtext></math>` ، والطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb aa</mtext></math>`. أخذت الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` من كل أب؛\nليست هذه صيغة عامة لجميع العوامل الحقيقية للون العين.\n:::\n\n:::exam-question\nid: bio-q-p089-q12-2\ntitle: تصنيف الأسئلة، السؤال 12، الفرع 2، صفحة 89\nquestion: السؤال 12، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ولون عيونه عسلية كان والده ذو شعر طبيعي وأزرق العينين، من فتاة ذات شعر طبيعي ولون عيونها عسلية فأنجبا طفلة تظهر صفة الصلع ذات عيون زرقاء. أجب مستخدماًb وb⁺ لصفة الصلع وA للعيون العسلية وa للزرقاء.\n\n2- اكتب الطرز الجينية لجاميتات الزوج والزوجة.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nللصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت أن أمها الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nوفق النموذج المبسط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق. الرجل عسلي وأبوه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` ؛\nوالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` تثبت أن أمها العسلية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>`.\nكلا الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Aa</mtext></math>`. يحمل كل غاميت أليلاً واحداً للشعر وآخر للعين؛\nوباستقلال الجينين تكون الأنواع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺a</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ba</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` لدى كل من الزوج والزوجة.\n:::\n\n:::exam-question\nid: bio-q-p089-q13-1\ntitle: تصنيف الأسئلة، السؤال 13، الفرع 1، صفحة 89\nquestion: السؤال 13، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ومصاب بنزف الدم والده ذو شعر طبيعي من فتاة طبيعية الشعر وغير مصابة بنزف الدم، فأنجبا طفلة عند بلوغها تساقط شعرها ومصابة بنزف الدم. نرمز لجين الإصابة بنزف الدمr.\n\n1- ما الطرز الجينية للصفتين معاً لكل من الرجل والمرأة؟\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع متأثر بالجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` عند الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي، فطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في أمها الطبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الرجل المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، والطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من أمها السليمة، فالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nإذن الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʳY</mtext></math>` والمرأة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XᴿXʳ</mtext></math>`. تنتج الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ، فيفسر الثاني الابنة المصابة عند اتحاده مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` الأب.\n:::\n\n:::exam-question\nid: bio-q-p089-q13-2\ntitle: تصنيف الأسئلة، السؤال 13، الفرع 2، صفحة 89\nquestion: السؤال 13، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ومصاب بنزف الدم والده ذو شعر طبيعي من فتاة طبيعية الشعر وغير مصابة بنزف الدم، فأنجبا طفلة عند بلوغها تساقط شعرها ومصابة بنزف الدم. نرمز لجين الإصابة بنزف الدمr.\n\n2- ما نمط الوراثة لهذه الصفات؟\nsolution:\n**الإجابة:** الصلع صفة جسمية متأثرة بالجنس. نزف الدم صفة متنحية مرتبطة بالكروموسومX في نموذج المنهج.\n\n**الشاهد من الكتاب 1:**\n\n> هي الصفات التي تحمل جيناتها على الكروموسومات الجسمية، ولكنها تتأثر بالهرمونات الجنسية، ومن الأمثلة عليها صفة الصلع عند الإنسان. حيث يكون جين الصلع(b) سائداً على جين وجود الشعر الطبيعي(b⁺) عند الذكور، أما عند الإناث فيكون جين وجود الشعر الطبيعي سائداً على جين الصلع.\n\n**المصدر:** صفحة 33 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> الأم XᴴXʰ؛ الأب XᴴY؛ ولد XʰY مصاب.\n\n\n\n\n\nفي مثال دليل المعلم تبقى الأمXᴴXʰ سليمة مع حملهاh، بينما يُصاب الابنXʰY؛ وهذا يوضح تنحيh ووجوده علىX.\n\n:::\n\n:::exam-question\nid: bio-q-p089-q13-3\ntitle: تصنيف الأسئلة، السؤال 13، الفرع 3، صفحة 89\nquestion: السؤال 13، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ومصاب بنزف الدم والده ذو شعر طبيعي من فتاة طبيعية الشعر وغير مصابة بنزف الدم، فأنجبا طفلة عند بلوغها تساقط شعرها ومصابة بنزف الدم. نرمز لجين الإصابة بنزف الدمr.\n\n3- ما احتمالية إنجاب ولد أصلع من بين الذكور؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع سائد في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي. الأب أصلع وله أب طبيعي، فطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالأم طبيعية لكنها أنجبت بنتاًصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nغاميتا كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nبين الذكور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` أصلع: الهجينان و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`. إذن الاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>`. عبارة «من بين الذكور» تجعل الجنس شرطاً معلوماً، فلا نضرب في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p089-q13-4\ntitle: تصنيف الأسئلة، السؤال 13، الفرع 4، صفحة 89\nquestion: السؤال 13، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع ومصاب بنزف الدم والده ذو شعر طبيعي من فتاة طبيعية الشعر وغير مصابة بنزف الدم، فأنجبا طفلة عند بلوغها تساقط شعرها ومصابة بنزف الدم. نرمز لجين الإصابة بنزف الدمr.\n\n4- ما احتمالية إنجاب بنت صلعاء مصابة بنزف الدم من بين النسل الناتج؟\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع متأثر بالجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` عند الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي، فطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في أمها الطبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الرجل المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، والطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من أمها السليمة، فالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ؛\nهذا وحده يسبب الصلع في الإناث.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ؛\nالبنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` احتمالها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nباستقلال الجين الجسمي عن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X: (1/4)×(1/4)=1/16</mtext></math>` من كل النسل.\n:::\n\n:::exam-question\nid: bio-q-p089-q15-1\ntitle: تصنيف الأسئلة، السؤال 15، الفرع 1، صفحة 89\nquestion: السؤال 15، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع مصاب بنزف الدم والده بشعر طبيعي من فتاة شعرها طبيعي نقية الصفة غير مصابة بنزف الدم ووالدها مصاب بنزف الدم.\n\n1- اكتب الطرز الجينية لكل من الرجل والفتاة للصفتين معاً.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع سائد في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للطبيعي سائد في الإناث. الأب الأصلع ابن رجل طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. الفتاة طبيعية ونقية كما نص السؤال، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، والفتاة سليمة وأبوها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، فتأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` منه وتحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` الآخر، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nإذن الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʳY</mtext></math>` والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ XᴿXʳ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p089-q15-2\ntitle: تصنيف الأسئلة، السؤال 15، الفرع 2، صفحة 89\nquestion: السؤال 15، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع مصاب بنزف الدم والده بشعر طبيعي من فتاة شعرها طبيعي نقية الصفة غير مصابة بنزف الدم ووالدها مصاب بنزف الدم.\n\n2- اكتب الطرز الجينية لأنواع غاميتات كل من الرجل والفتاة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع سائد في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للطبيعي سائد في الإناث. الأب الأصلع ابن رجل طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. الفتاة طبيعية ونقية كما نص السؤال، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، والفتاة سليمة وأبوها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، فتأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` منه وتحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` الآخر، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالغاميت يأخذ أليلاً واحداً للشعر وكروموسوماً جنسياً واحداً. الرجل يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Y</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bY</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` بالاستقلال.\nالفتاة تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xʳ</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nلأنها ثابتة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` في صفة الشعر.\n:::\n\n:::exam-question\nid: bio-q-p089-q15-3\ntitle: تصنيف الأسئلة، السؤال 15، الفرع 3، صفحة 89\nquestion: السؤال 15، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع مصاب بنزف الدم والده بشعر طبيعي من فتاة شعرها طبيعي نقية الصفة غير مصابة بنزف الدم ووالدها مصاب بنزف الدم.\n\n3- ما احتمال إنجاب بنت بشعر طبيعي مصابة بنزف الدم؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع سائد في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للطبيعي سائد في الإناث. الأب الأصلع ابن رجل طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. الفتاة طبيعية ونقية كما نص السؤال، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، والفتاة سليمة وأبوها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، فتأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` منه وتحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` الآخر، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b⁺</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nكلاهما طبيعي في الإناث، فاحتمال الشعر الطبيعي للبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>`.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي أربع حالات متساوية، بينها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` بنت مصابة واحدة.\nإذن احتمال بنت طبيعية الشعر ومصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1×1/4=1/4</mtext></math>` من كل النسل.\n:::\n\n:::exam-question\nid: bio-q-p090-q17-1\ntitle: تصنيف الأسئلة، السؤال 17، الفرع 1، صفحة 90\nquestion: السؤال 17، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي من فتاة غير صلعاء وغير مصابة بنزف الدم، فأنجبا طفلة تظهر صفة الصلع ومصابة بنزف الدم.\n\n1- اكتب الطرز الجينية لكل من الرجل والفتاة للصفتين معاً.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع يسود في الذكر ويتنحى في الأنثى؛\nالأب الأصلع ابن رجل طبيعي فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من أمها الطبيعية فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب.\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` عند أبيها فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وتثبته عند أمها السليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالطرزان الجينيان: الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʳY</mtext></math>` ، والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XᴿXʳ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p090-q17-2\ntitle: تصنيف الأسئلة، السؤال 17، الفرع 2، صفحة 90\nquestion: السؤال 17، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي من فتاة غير صلعاء وغير مصابة بنزف الدم، فأنجبا طفلة تظهر صفة الصلع ومصابة بنزف الدم.\n\n2- ما مبدأ الوراثة لكل من الصفتين؟\nsolution:\n**الإجابة:** الصلع صفة جسمية متأثرة بالجنس. نزف الدم صفة متنحية مرتبطة بالكروموسومX في نموذج المنهج.\n\n**الشاهد من الكتاب 1:**\n\n> هي الصفات التي تحمل جيناتها على الكروموسومات الجسمية، ولكنها تتأثر بالهرمونات الجنسية، ومن الأمثلة عليها صفة الصلع عند الإنسان. حيث يكون جين الصلع(b) سائداً على جين وجود الشعر الطبيعي(b⁺) عند الذكور، أما عند الإناث فيكون جين وجود الشعر الطبيعي سائداً على جين الصلع.\n\n**المصدر:** صفحة 33 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> الأم XᴴXʰ؛ الأب XᴴY؛ ولد XʰY مصاب.\n\n\n\n\n\nفي مثال دليل المعلم تبقى الأمXᴴXʰ سليمة مع حملهاh، بينما يُصاب الابنXʰY؛ وهذا يوضح تنحيh ووجوده علىX.\n\n:::\n\n:::exam-question\nid: bio-q-p090-q17-3\ntitle: تصنيف الأسئلة، السؤال 17، الفرع 3، صفحة 90\nquestion: السؤال 17، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي من فتاة غير صلعاء وغير مصابة بنزف الدم، فأنجبا طفلة تظهر صفة الصلع ومصابة بنزف الدم.\n\n3- ما احتمال إنجاب طفل ذكر أصلع ومصاب بنزف الدم؟\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع يسود في الذكر ويتنحى في الأنثى؛\nالأب الأصلع ابن رجل طبيعي فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من أمها الطبيعية فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب.\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` عند أبيها فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وتثبته عند أمها السليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2 b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 bb</mtext></math>` ؛\nاحتمال الصلع بين الذكور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=3/4</mtext></math>`.\nالجنس والمرض : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ؛\nالذكر المصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nإذن احتمال ذكر أصلع مصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(3/4)×(1/4)=3/16</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p090-q21-1\ntitle: تصنيف الأسئلة، السؤال 21، الفرع 1، صفحة 90\nquestion: السؤال 21، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع مصاب بمرض نزف الدم من فتاة غير صلعاء وغير مصابة بنزف الدم فأنجبا طفلة تحمل جيني الصلع ومصابة بنزف الدم. استخدم b⁺ للشعر الطبيعي وb للإصابة بالصلع، وH لعدم الإصابة بنزف الدم وh للإصابة به.\n\n1- اكتب الطرز الجينية المحتملة للأبوين والطفلة.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكور ومتنح في الإناث. عبارة تحمل جيني الصلع تعني الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nفتحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من كل أب. الأم طبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ، والأب الأصلع قد يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nلا تكفي الطفلة للتمييز.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰXʰ</mtext></math>` والأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ؛\nالأم سليمة لكنها أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالطرز الممكنة: الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb XʰY</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʰY</mtext></math>` ؛\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XᴴXʰ</mtext></math>` ؛\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb XʰXʰ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p090-q21-2\ntitle: تصنيف الأسئلة، السؤال 21، الفرع 2، صفحة 90\nquestion: السؤال 21، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90 · صياغة تعليمية معدّلة\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع متغاير الأليلين للصلع (b⁺b)، مصاب بنزف الدم، من فتاة غير صلعاء وغير مصابة بنزف الدم، فأنجبا طفلة طرازها للصلع bb ومصابة بنزف الدم. استخدم b⁺ للشعر الطبيعي و b للصلع. إذا كان احتمال الذكر والأنثى متساويًا، فما احتمال إنجاب ذكر أصلع في حمل جديد؟\nsolution:\nالصلع صفة متأثرة بالجنس: يكون b سائدًا عند الذكور ومتنحيًا عند الإناث. الأم غير صلعاء، لكنها أعطت ابنتها الأليل b؛ لذلك يكون طراز الأم b⁺b. وطراز الأب b⁺b معطى صراحة.\n\n| غاميتا الأبوين | b⁺ | b |\n|---|---|---|\n| b⁺ | b⁺b⁺ | b⁺b |\n| b | b⁺b | bb |\n\nعند الذكر، الطرازان b⁺b و bb يظهران الصلع؛ فاحتمال الصلع بشرط أن المولود ذكر هو 3/4.\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>P</mi><mo stretchy="false">(</mo><mrow><mi mathvariant="normal">b</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">l</mi><mi mathvariant="normal">d</mi></mrow><mo>∣</mo><mrow><mi mathvariant="normal">m</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">l</mi><mi mathvariant="normal">e</mi></mrow><mo stretchy="false">)</mo><mo>=</mo><mfrac><mn>3</mn><mn>4</mn></mfrac></mrow></math>\n```\n\n\n\nنضرب في احتمال إنجاب ذكر، وهو 1/2. لا تدخل صفة نزف الدم في المطلوب الحالي.\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>P</mi><mo stretchy="false">(</mo><mrow><mi mathvariant="normal">m</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">l</mi><mi mathvariant="normal">e</mi><mtext> </mtext><mi mathvariant="normal">a</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi><mtext> </mtext><mi mathvariant="normal">b</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">l</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false">)</mo><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mfrac><mn>3</mn><mn>4</mn></mfrac><mo>=</mo><mfrac><mn>3</mn><mn>8</mn></mfrac></mrow></math>\n```\n\n\n\nالإجابة:3/8، أي 37.5%.\n\n**المصدر:** صفحة 33 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p091-q23-1\ntitle: تصنيف الأسئلة، السؤال 23، الفرع 1، صفحة 91\nquestion: السؤال 23، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير محدد الطراز الشكلي والده شعره طبيعي من فتاة طبيعية الشعر فصيلة دمهاB فأنجبا بنتاً تظهر صفة الصلع وفصيلة دمهاO، علماً أن الوالدين لا يمكن أن يتبرع أحدهما للآخر بالدم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- ما الطراز الشكلي للشاب للصفتين معاً؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالبنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من الأبوين؛\nلأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` متنح في الإناث وسائد في الذكور. الشاب أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، لذا هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` وأصلع. الأم الطبيعية التي أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`. في نموذج نقل الكريات، خلايا A تحمل مولد A وبلازمتها مضاد B؛ وخلايا B تحمل مولد B وبلازمتها مضاد A. لهذا يفشل النقل بين A وB في الاتجاهين.\nعدم التوافق بالنقل في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nوبمنحه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` للبنت يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nإذن الشاب أصلع وفصيلة دمه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>`. وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لديه كاف لإظهار الصلع لأنه ذكر، ووجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` كاف للفصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p091-q23-2\ntitle: تصنيف الأسئلة، السؤال 23، الفرع 2، صفحة 91\nquestion: السؤال 23، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير محدد الطراز الشكلي والده شعره طبيعي من فتاة طبيعية الشعر فصيلة دمهاB فأنجبا بنتاً تظهر صفة الصلع وفصيلة دمهاO، علماً أن الوالدين لا يمكن أن يتبرع أحدهما للآخر بالدم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- ما الطرز الجينية لكل من الشاب والفتاة والبنت للصفتين معاً؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالبنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من الأبوين؛\nلأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` متنح في الإناث وسائد في الذكور. الشاب أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، لذا هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` وأصلع. الأم الطبيعية التي أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`. في نموذج نقل الكريات، خلايا A تحمل مولد A وبلازمتها مضاد B؛ وخلايا B تحمل مولد B وبلازمتها مضاد A. لهذا يفشل النقل بين A وB في الاتجاهين.\nعدم التوافق بالنقل في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nوبمنحه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` للبنت يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالطرز للصفتين: الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi b⁺b</mtext></math>` ؛\nالفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi b⁺b</mtext></math>` ؛\nالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii bb</mtext></math>`.\nغاميتا الدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` تنتجان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ؛\nوغاميتا الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` من كليهما تنتجان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`. لا يلزم أن تكون الأم صلعاء كي تنقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p091-q23-3\ntitle: تصنيف الأسئلة، السؤال 23، الفرع 3، صفحة 91\nquestion: السؤال 23، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير محدد الطراز الشكلي والده شعره طبيعي من فتاة طبيعية الشعر فصيلة دمهاB فأنجبا بنتاً تظهر صفة الصلع وفصيلة دمهاO، علماً أن الوالدين لا يمكن أن يتبرع أحدهما للآخر بالدم.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n3- ما احتمال إنجاب ولد طبيعي الشعر وفصيلة دمهAB؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع يسود في الذكر ويتنحى في الأنثى. البنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في كلا الأبوين؛\nالأب أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي، والأم طبيعية، لذا كلاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` للبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` وعدم التوافق بالنقل مع الزوج يجعله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي الطبيعي في الذكور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` باحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × Iᴮi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=1/4</mtext></math>`.\nاحتمال ذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/4)×(1/4)=1/32</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q29-1\ntitle: تصنيف الأسئلة، السؤال 29، الفرع 1، صفحة 92\nquestion: السؤال 29، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nرجل أصلع غير نقي مصاب بعمى الألوان تزوج امرأة طبيعية الشعر غير مصابة بعمى الألوان، والدها طبيعي الشعر ومصاب بعمى الألوان ووالدتها تظهر صفة الصلع. جين الرؤية الطبيعيةH سائد على جين عمى الألوانh.\n\n1- اكتب الطرز الجينية للأبوين.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع متأثر بالجنس؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. الرجل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. أم المرأة صلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` وأبوها طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيمنحانها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nلذلك هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ، والمرأة سليمة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` من أبيها المصاب فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XʰY</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b XᴴXʰ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q29-2\ntitle: تصنيف الأسئلة، السؤال 29، الفرع 2، صفحة 92\nquestion: السؤال 29، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nرجل أصلع غير نقي مصاب بعمى الألوان تزوج امرأة طبيعية الشعر غير مصابة بعمى الألوان، والدها طبيعي الشعر ومصاب بعمى الألوان ووالدتها تظهر صفة الصلع. جين الرؤية الطبيعيةH سائد على جين عمى الألوانh.\n\n2- اكتب الطرز الجينية لغاميتات الأبوين.\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع متأثر بالجنس؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. الرجل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. أم المرأة صلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` وأبوها طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيمنحانها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nلذلك هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ، والمرأة سليمة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` من أبيها المصاب فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالغاميت يحمل أليلاً واحداً للشعر وكروموسوماً جنسياً واحداً، والجين الجسمي مستقل عن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\nالأب : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bXʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Y</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bY</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالأم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xᴴ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bXᴴ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Xʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bXʰ</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p092-q29-4\ntitle: تصنيف الأسئلة، السؤال 29، الفرع 4، صفحة 92\nquestion: السؤال 29، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 92\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nرجل أصلع غير نقي مصاب بعمى الألوان تزوج امرأة طبيعية الشعر غير مصابة بعمى الألوان، والدها طبيعي الشعر ومصاب بعمى الألوان ووالدتها تظهر صفة الصلع. جين الرؤية الطبيعيةH سائد على جين عمى الألوانh.\n\n4- ما احتمال إنجاب ذكر سليم من عمى الألوان طبيعي الشعر؟\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع متأثر بالجنس؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الأنثى. الرجل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. أم المرأة صلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` وأبوها طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فيمنحانها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nلذلك هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` مصاب. الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` ، والمرأة سليمة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʰ</mtext></math>` من أبيها المصاب فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ؛\nوهو التركيب الوحيد للذكر الطبيعي.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY × XᴴXʰ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴXʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰXʰ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʰY</mtext></math>` بالتساوي؛\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴴY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nبالاستقلال: احتمال ذكر سليم طبيعي الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/4)×(1/4)=1/16</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p093-q31\ntitle: تصنيف الأسئلة، السؤال 31، صفحة 93\nquestion: السؤال 31\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 93\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعلل: نسبة انتشار صفة الصلع عند الذكور أكثر منها عند الإناث.\nsolution:\nبحسب نموذج المنهج، الصلع صفة جسمية متأثرة بالهرمونات الجنسية؛\nيسود أليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع عند الذكر، فيظهر الصلع في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` وفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nعند الأنثى يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي، فلا يظهر الصلع إلا في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nلذلك يظهر الطراز الهجين نفسه أصلع في الذكور وطبيعي الشعر في الإناث، فيتسع عدد التراكيب التي تُظهر الصلع عند الذكور.\n:::\n\n:::exam-question\nid: bio-q-p094-q35-1\ntitle: تصنيف الأسئلة، السؤال 35، الفرع 1، صفحة 94\nquestion: السؤال 35، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمهA من امرأة شعرها طبيعي فصيلة دمها غير معروفة، فأنجبا بنتاً تظهر صفة الصلع فصيلة دمهاO وولداً طبيعي الشعر. لم تنجح عملية نقل الدم من الرجل إلى زوجته ولا من الزوجة إلى زوجها.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n1- ما الطرز الجينية للأبوين؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكر ويتنحى في الأنثى.\nالابن الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` عند الأب الأصلع، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالبنت الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` عند الأم الطبيعية، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`.\nالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فيحمل كلا الأبوين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. عدم توافق النقل في الاتجاهين يحصر الأم في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Iᴬi</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Iᴮi</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p094-q35-2\ntitle: تصنيف الأسئلة، السؤال 35، الفرع 2، صفحة 94\nquestion: السؤال 35، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمهA من امرأة شعرها طبيعي فصيلة دمها غير معروفة، فأنجبا بنتاً تظهر صفة الصلع فصيلة دمهاO وولداً طبيعي الشعر. لم تنجح عملية نقل الدم من الرجل إلى زوجته ولا من الزوجة إلى زوجها.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n2- ما الطرز الجينية للابنة؟\n\nsolution:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` متنح في الإناث؛\nالابنة التي تظهر الصلع يجب أن تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`. والفصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` لا تظهر إلا عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` يسودان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`.\nإذن الابنة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb ii</mtext></math>` ، وقد أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من كل أب. الأم الطبيعية تستطيع إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لأنها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ، والأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يستطيع إعطاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` لأنه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p094-q35-4\ntitle: تصنيف الأسئلة، السؤال 35، الفرع 4، صفحة 94\nquestion: السؤال 35، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع فصيلة دمهA من امرأة شعرها طبيعي فصيلة دمها غير معروفة، فأنجبا بنتاً تظهر صفة الصلع فصيلة دمهاO وولداً طبيعي الشعر. لم تنجح عملية نقل الدم من الرجل إلى زوجته ولا من الزوجة إلى زوجها.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\n4- ما احتمال إنجاب فرد فصيلة دمهB طبيعي الشعر؟\n\nsolution:\nفي نموذج الصلع بالمقرر نرمزb للصلع وb⁺ للشعر الطبيعي. يسودb في الذكر، ويتنحى في الأنثى.\n\nالابن الطبيعيb⁺b⁺ يثبت وجودb⁺ عند الأب الأصلع، والبنت الصلعاءbb تثبت وجودb عند الأم الطبيعية؛ لذلك كلا الأبوينb⁺b.\n\nالبنتO طرازهاii، فيحمل كل والدi. الأبA هوIᴬi؛ وعدم توافق نقل الكريات بينه وبين الأم في الاتجاهين يجعل الأمB، أيIᴮi.\n\nنحسب الشعر أولاً:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><mi>b</mi><mo>×</mo><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><mi>b</mi><mo>⟶</mo><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><mo>:</mo><msup><mi>b</mi><mo lspace="0em" rspace="0em">+</mo></msup><mi>b</mi><mo>:</mo><mi>b</mi><mi>b</mi><mo>=</mo><mn>1</mn><mo>:</mo><mn>2</mn><mo>:</mo><mn>1</mn></mrow></math>\n```\n\n\n\nبين الذكور يكون الطبيعيb⁺b⁺ فقط، واحتماله1/4. بين الإناث يكونb⁺b⁺ أوb⁺b طبيعياً، واحتماله3/4.\n\nالمطلوب فرد طبيعي الشعر دون تحديد الجنس. نجمع احتمالي الذكر الطبيعي والأنثى الطبيعية:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>P</mi><mo stretchy="false">(</mo><mtext>طبيعي الشعر</mtext><mo stretchy="false">)</mo><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mfrac><mn>1</mn><mn>4</mn></mfrac><mo>+</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mfrac><mn>3</mn><mn>4</mn></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>8</mn></mfrac><mo>+</mo><mfrac><mn>3</mn><mn>8</mn></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac></mrow></math>\n```\n\n\n\nتزاوج الدمIᴬi×Iᴮi يعطيA وB وAB وO بأرباع؛ فاحتمالB هو1/4.\n\nباستقلال الصفتين:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>P</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mfrac><mn>1</mn><mn>4</mn></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>8</mn></mfrac></mrow></math>\n```\n\n\n\nإذن احتمال فرد فصيلتهB وطبيعي الشعر **1/8**.\n\n**المصدر:** الصفحات 30، 31، 33 من الكتاب.\n\n:::\n\n:::mcq\nid: bio-q-p103-q8\ntitle: صفحة 103، السؤال 8\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 103\nquestion: تزوج شاب طبيعي الشعر فتاة طبيعية الشعر غير متماثلة الجينات، ما احتمال إنجاب بنت تظهر صفة الصلع؟\n- [x] option-1 | صفر\n- [ ] option-2 | \\(\\frac14\\)\n- [ ] option-3 | \\(\\frac12\\)\n- [ ] option-4 | \\(\\frac34\\)\nexplanation:\nنرمز بأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للصلع، وبأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` للشعر الطبيعي في نموذج هذه المسألة.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الشاب طبيعي الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والفتاة الطبيعية غير المتماثلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nغاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` فقط، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ؛\nالنسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\nالأنثى لا تصلع إلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، وهو مستحيل لأن الأب لا يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>`. لذلك احتمال بنت صلعاء=صفر.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p108-q16-3\ntitle: صفحة 108، السؤال 16، الفرع 3\nquestion: ما نوع الوراثة لصفة وجود العرف؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع عصافير الزينة صفة وجود العرف سائدة في الذكور ومتنحية في الإناث، ويختلف الطراز الشكلي في الذكور عنه للإناث عند عدم تماثل الجينات. تزاوج ذكر ريشه مخطط وبدون عرف مع أنثى غير مخططة الريش ولها عرف. النسل: نصف الذكور مخطط وله عرف والنصف الآخر غير مخطط وله عرف؛ نصف الإناث مخطط وبدون عرف والنصف الآخر غير مخطط وبدون عرف. A لجين الريش المخطط السائد على غير المخطط a، وهذه الصفة مرتبطة بالجنس.\n\nما نوع الوراثة لصفة وجود العرف؟\nsolution:\nصفة وجود العرف متأثرة بالجنس؛\nفالسؤال ينص أن الطراز غير المتماثل يظهر بعرف في الذكر وبلا عرف في الأنثى.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لعدمه: الأب الذكر بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` والأم الأنثى ذات العرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` ، فيكون النسل كله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>`. ولأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` يسود في الذكور ويتنحى في الإناث يكون كل الذكور ذوي عرف وكل الإناث بلا عرف، كما في النتائج.\nإذن تغير المظهر سببه تغير السيادة باختلاف الجنس.\n:::\n\n:::mcq\nid: bio-b-p038-q1-4\ntitle: الرزمة التعليمية، صفحة 38، السؤال 1-4\nquestion: ما احتمال ظهور فرد طرازه الجيني AaBb لأبوين أحدهما AAbb والثاني AaBb، مع العلم أن الجينين A,b محمولان على نفس الكروموسوم ومع فرض عدم حدوث عملية العبور؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\n- [x] option-1 | 1/2\n- [ ] option-2 | 1/4\n- [ ] option-3 | 1/8\n- [ ] option-4 | صفر\nexplanation:\nالارتباط يعني وجود الجينين على الكروموسوم نفسه؛\nومع عدم العبور لا تتبادل الأليلات بينهما. عبارة أن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` محمولان معاً تحدد الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab/aB</mtext></math>` لدى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>`.\nالأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AAbb</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab</mtext></math>` فقط. الثاني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab/aB</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aB</mtext></math>` مناصفة.\n\n| غاميت الأول | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab</mtext></math>` من الثاني | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aB</mtext></math>` من الثاني |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AAbb</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>` |\n\nإذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>` ينتج في حالة من اثنتين : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ، الاختيار الأول.\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::exam-question\nid: bio-b-p039-q3-1\ntitle: الرزمة التعليمية، صفحة 39، السؤال 3-1\nquestion: ما الطرز الجينية لغاميتات الأبوين للصفتين معاً؟\nreference: [الرزمة التعليمية، صفحة PDF 39](https://moe.edu.ps/m/4061#page=39)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت النتائج: 45.5% سوداء طويلة الذيل، 45.5% بيضاء قصيرة الذيل، 4.5% بيضاء طويلة الذيل، 4.5% سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nما الطرز الجينية لغاميتات الأبوين للصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` سائد للطويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأنثى بيضاء قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` فلا تعطي إلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` ؛\nلذلك يكشف كل طراز في النسل غاميت الأب مباشرة.\nالفئتان الكبيرتان أسود طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` وأبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين؛\nوالفئتان الصغيرتان أبيض طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` وأسود قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` الناتجتين بالعبور.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>` وغاميتاته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>`.\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt/bt</mtext></math>` وغاميتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nاتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbTt</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbTt</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bbtt</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-b-p039-q3-2\ntitle: الرزمة التعليمية، صفحة 39، السؤال 3-2\nquestion: فسر سبب ظهور هذه النسب.\nreference: [الرزمة التعليمية، صفحة PDF 39](https://moe.edu.ps/m/4061#page=39)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت النتائج: 45.5% سوداء طويلة الذيل، 45.5% بيضاء قصيرة الذيل، 4.5% بيضاء طويلة الذيل، 4.5% سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nفسر سبب ظهور هذه النسب.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` سائد للطويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأنثى بيضاء قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` فلا تعطي إلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` ؛\nلذلك يكشف كل طراز في النسل غاميت الأب مباشرة.\nالفئتان الكبيرتان أسود طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` وأبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين؛\nوالفئتان الصغيرتان أبيض طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` وأسود قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` الناتجتين بالعبور.\nوجود الفئتين الكبيرتين بمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5+45.5=91%</mtext></math>` يدل على استمرار التراكيب المرتبطة.\nونتيجة العبور في الانقسام المنصف تظهر التراكيب الجديدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` بمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5+4.5=9%</mtext></math>`.\nالعبور تبادل قطع بين كروماتيدين غير شقيقين لكروموسومين متناظرين؛\nلذلك تظهر أربع فئات بنسب غير متساوية بدلاً من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1:1:1</mtext></math>` المتوقعة عند الاستقلال في التزاوج الاختباري.\n:::\n\n:::mcq\nid: bio-b-p040-q1-4\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-4\nquestion: إذا كانت نسبة الارتباط بين الجينين E وF تساوي85%، كم تساوي نسبة العبور بينهما؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [ ] option-1 | 85%\n- [ ] option-2 | 25%\n- [ ] option-3 | 20%\n- [x] option-4 | 15%\nexplanation:\nفي اصطلاح هذه المسائل، نسبة الارتباط هي نسبة التراكيب الأبوية، ونسبة العبور هي نسبة التراكيب الجديدة؛\nومجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nالمعطى ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>85%</mtext></math>` ، إذن العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−85%=15%</mtext></math>`.\nالاختيار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>15%</mtext></math>`. لا نقسم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>15%</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` إلا إذا طُلبت نسبة كل فئة جديدة على حدة مع تساويهما.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::exam-question\nid: bio-b-p041-q2-a-1\ntitle: الرزمة التعليمية، صفحة 41، السؤال 2-a-1\nquestion: ما تفسير ظهور النسب السابقة؟\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من عصافير الزينة صفتا لون الريش وشكل المنقار مرتبطتان على نفس الكروموسوم. تزاوج ذكر أحمر الريش مدبب المنقار مع أنثى بيضاء الريش عريضة المنقار. النسل:41.5% حمراء مدببة،41.5% بيضاء عريضة،8.5% حمراء عريضة،8.5% بيضاء مدببة. الرمز R للأحمر وr للأبيض، وD للمدبب وd للعريض.\n\nما تفسير ظهور النسب السابقة؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` للمنقار المدبب السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>d</mtext></math>` للعريض. الأنثى البيضاء العريضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrdd</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` فقط؛\nفكل طراز نسلي يكشف غاميت الذكر.\nحمراء مدببة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5%</mtext></math>` تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD</mtext></math>` ، وبيضاء عريضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5%</mtext></math>` تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` ؛\nوهما التركيبان الأبويان، فيكون الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD/rd</mtext></math>`.\nالجينان مرتبطان؛\nفتكثر الفئتان الأبويتان بمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5+41.5=83%</mtext></math>`.\nالعبور بين كروماتيدين غير شقيقين يكوّن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rD</mtext></math>` ، فينتج أحمر عريض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8.5%</mtext></math>` وأبيض مدبب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8.5%</mtext></math>` ، ومجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>17%</mtext></math>`.\nإذن الارتباط مع عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>17%</mtext></math>` يفسر الفئات الأربع غير المتساوية.\n:::\n\n:::exam-question\nid: bio-b-p041-q2-a-2\ntitle: الرزمة التعليمية، صفحة 41، السؤال 2-a-2\nquestion: اكتب الطرز الجينية لغاميتات الذكر.\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من عصافير الزينة صفتا لون الريش وشكل المنقار مرتبطتان على نفس الكروموسوم. تزاوج ذكر أحمر الريش مدبب المنقار مع أنثى بيضاء الريش عريضة المنقار. النسل:41.5% حمراء مدببة،41.5% بيضاء عريضة،8.5% حمراء عريضة،8.5% بيضاء مدببة. الرمز R للأحمر وr للأبيض، وD للمدبب وd للعريض.\n\nاكتب الطرز الجينية لغاميتات الذكر.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` للمنقار المدبب السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>d</mtext></math>` للعريض. الأنثى البيضاء العريضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrdd</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` فقط؛\nفكل طراز نسلي يكشف غاميت الذكر.\nحمراء مدببة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5%</mtext></math>` تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD</mtext></math>` ، وبيضاء عريضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5%</mtext></math>` تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` ؛\nوهما التركيبان الأبويان، فيكون الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD/rd</mtext></math>`.\nالطراز الذكري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD/rd</mtext></math>` ؛\nغاميتاه الأبويتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` ، لكل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5%</mtext></math>`. وغاميتاه المعاد تركيبهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rD</mtext></math>` ، لكل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8.5%</mtext></math>`.\nمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` الأنثى تنتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrDd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrdd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rrdd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrDd</mtext></math>` بالترتيب. مجموع النسب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>41.5+41.5+8.5+8.5=100%</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-b-p041-q2-a-3\ntitle: الرزمة التعليمية، صفحة 41، السؤال 2-a-3\nquestion: علل: ظهور النسبة3:1 بدلاً من النسبة9:3:3:1 عند إجراء تلقيح (تزاوج) بين صفتين سائدتين غير نقيتين مع صفتين سائدتين غير نقيتين.\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعلل: يمكن أن تظهر نسبة شكلية 3:1 بدلًا من 9:3:3:1 عند تزاوج فردين غير نقيين لصفتين، على أن يظهر المظهران السائدان معًا أو المتنحيان معًا.\n\nsolution:\nنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9:3:3:1</mtext></math>` تتطلب توزيع جينين مستقلين مع سيادة تامة. أما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` للصفتين معاً فتظهر إذا كان الجينان مرتبطين تماماً في الطور الاقتراني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB/ab</mtext></math>` في كلا الأبوين، دون عبور.\nكل أب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>` مناصفة.\n\n| الغاميت | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>` |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AABB</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aabb</mtext></math>` |\n\nثلاث حالات من أربع تظهر الصفتين السائدتين، وحالة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aabb</mtext></math>` تظهر المتنحيتين؛\nفتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>`. هذا تعليل حالة ارتباط تام عامة؛\nأما بيانات الطيور السابقة ففيها عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>17%</mtext></math>` ، فلا نفرض غيابه عليها.\n\n:::\n\n:::exam-question\nid: bio-q-p072-q4-1\ntitle: تصنيف الأسئلة، السؤال 4، الفرع 1، صفحة 72\nquestion: السؤال 4، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 72\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأشجار نخيل (العجوة) في بيسان وأريحا من أجود أنواع التمور في العالم، فإذا حصل تلقيح بين شجر نخيل طويل الساق أسود الثمار، مع نبات آخر مجهول الطراز الشكلي، فكانت أفراد النسل الناتج كالآتي: (400) شجرة نخيل طويلة الساق سوداء الثمار؛ (395) شجرة نخيل قصيرة الساق صفراء الثمار. باستخدام الرمز (T) لصفة طول الساق، والرمز (t) صفة قصر الساق، والرمز (r) صفة لون الثمار الأصفر، والرمز (R) لصفة لون الثمار الأسود.\n\n1- ما الطراز الشكلي للنبات المجهول؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأسود سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>`. ظهور أشجار قصيرة صفراء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttrr</mtext></math>` يثبت أن النبات المعروف الطويل الأسود يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRr</mtext></math>`.\nالنسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>400</mtext></math>` طويل أسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>395</mtext></math>` قصير أصفر يقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` ، دون فئتي الطويل الأصفر والقصير الأسود. يوافق ذلك تفسير الارتباط التام `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>` في المعروف مع تلقيح اختباري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr/tr</mtext></math>`.\nالنبات المجهول في هذا التفسير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttrr</mtext></math>` ، أي قصير الساق أصفر الثمار. غاميتاهما : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` من المعروف، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` فقط من المجهول؛\nفينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRr</mtext></math>` طويل أسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttrr</mtext></math>` قصير أصفر مناصفة.\nهذا هو التفسير المدرسي للنسب المتوقعة؛\nغياب الفئات في عينة لا يثبت استحالة العبور مطلقاً.\n:::\n\n:::exam-question\nid: bio-q-p072-q4-2\ntitle: تصنيف الأسئلة، السؤال 4، الفرع 2، صفحة 72\nquestion: السؤال 4، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 72\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأشجار نخيل (العجوة) في بيسان وأريحا من أجود أنواع التمور في العالم، فإذا حصل تلقيح بين شجر نخيل طويل الساق أسود الثمار، مع نبات آخر مجهول الطراز الشكلي، فكانت أفراد النسل الناتج كالآتي: (400) شجرة نخيل طويلة الساق سوداء الثمار؛ (395) شجرة نخيل قصيرة الساق صفراء الثمار. باستخدام الرمز (T) لصفة طول الساق، والرمز (t) صفة قصر الساق، والرمز (r) صفة لون الثمار الأصفر، والرمز (R) لصفة لون الثمار الأسود.\n\n2- فسر الحالة الوراثية في النسل الناتج مبيناً نوع الوراثة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأسود سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>`. ظهور أشجار قصيرة صفراء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ttrr</mtext></math>` يثبت أن النبات المعروف الطويل الأسود يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRr</mtext></math>`.\nالنسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>400</mtext></math>` طويل أسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>395</mtext></math>` قصير أصفر يقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` ، دون فئتي الطويل الأصفر والقصير الأسود. يوافق ذلك تفسير الارتباط التام `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>` في المعروف مع تلقيح اختباري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr/tr</mtext></math>`.\nالارتباط يبقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` على كروموسومين متناظرين. دون عبور يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>` غاميتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` ، ومع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` من المجهول ينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>` طويل أسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr/tr</mtext></math>` قصير أصفر بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>`.\nإذن نوع الوراثة الذي يوافق الفئتين فقط هو ارتباط تام في نموذج المسألة. لو كان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRr × ttrr</mtext></math>` مستقلاً لتوقعنا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1:1:1</mtext></math>` ، أي أربع فئات، وهو لا يوافق النتيجة الواردة.\n:::\n\n:::mcq\nid: bio-q-p083-q34\ntitle: تصنيف الأسئلة، السؤال 34، صفحة 83\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 83\nquestion: فرد طرازه الجيني AaBb إذا علمت أن الجينين A وB محمولان على كروموسوم واحد على فرض عدم حدوث عبور، فما عدد أنواع الغاميتات التي يمكن أن ينتجها هذا الفرد؟\n- [x] option-1 | أ. 2\n- [ ] option-2 | ب. 4\n- [ ] option-3 | ج. 6\n- [ ] option-4 | د. 8\nexplanation:\nالجينان مرتبطان على كروموسوم واحد، والفرد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaBb</mtext></math>` يحمل نسختين متناظرتين. إذا كان ترتيبه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB/ab</mtext></math>` أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>` ؛\nوإذا كان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab/aB</mtext></math>` أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aB</mtext></math>`.\nلعدم العبور لا تتكون تراكيب جديدة في أي من الطورين؛\nلذلك عدد أنواع الغاميتات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، الاختيار أ. قاعدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2²=4</mtext></math>` لا تطبق عند هذا الارتباط التام.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q35\ntitle: تصنيف الأسئلة، السؤال 35، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: حصل تزاوج بين نبتتين كلاهما يحمل الطراز الجيني MmRr فكانت النسبة بين أفراد الجيل الأول (3 سائد : 1 متنحٍ)، فما التفسير الوراثي لذلك؟\n- [ ] option-1 | أ. سيادة تامة\n- [ ] option-2 | ب. سيادة مشتركة\n- [x] option-3 | ج. ارتباط جينات\n- [ ] option-4 | د. ارتباط جينات وعبور\nexplanation:\nوجود صفتين غير نقيتين مع نتيجة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` سائد : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` متنح معاً يوافق انتقال الجينين كوحدة واحدة بارتباط تام، لا توزيعهما المستقل.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>MR/mr × MR/mr</mtext></math>` ، دون عبور؛\nغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>MR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>mr</mtext></math>`. النواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>MMRR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>MmRr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>MmRr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>mmrr</mtext></math>`.\nثلاث حالات تظهر الصفتين السائدتين وحالة تظهر المتنحيتين؛\nالاختيار ج «ارتباط جينات». سيادة كل أليل وحدها لا تفسر اختفاء الفئتين المختلطتين في مسألة الصفتين.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q37\ntitle: تصنيف الأسئلة، السؤال 37، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: فرد طرازه الجيني لصفتين مرتبطتين معاً هو (AaBb) والجينان A,b مرتبطان على نفس الكروموسوم فإذا كانت نسبة تكرار عملية العبور بين جيني الصفتين 10% فما الطرز الجينية للغاميتات ونسبها؟\n- [ ] option-1 | أ. AB 45%، ab 45%، Ab 5%، aB 5%\n- [x] option-2 | ب. aB 45%، Ab 45%، AB 5%، ab 5%\n- [ ] option-3 | ج. AB 40%، ab 40%، Ab 10%، aB 10%\n- [ ] option-4 | د. Ab 40%، aB 40%، AB 10%، ab 10%\nexplanation:\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` على كروموسوم واحد يجعل الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab/aB</mtext></math>` ؛\nوهما الغاميتان الأبويتان. العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10%</mtext></math>` يعني أن مجموع الغاميتين الجديدتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>` يساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10%</mtext></math>`.\nنسبة كل مؤتلف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=10%÷2=5%</mtext></math>`.\nمجموع الأبويتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−10%=90%</mtext></math>` ؛\nنسبة كل واحدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=90%÷2=45%</mtext></math>`.\nإذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aB45%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ab45%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab5%</mtext></math>` ، الاختيار ب.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q38\ntitle: تصنيف الأسئلة، السؤال 38، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: في خريطة الجينات المجاورة ما نسبة الارتباط بين الجينين F وH؟\n- [x] option-1 | أ. 90%\n- [ ] option-2 | ب. 94%\n- [ ] option-3 | ج. 96%\n- [ ] option-4 | د. 10%\nexplanation:\nوحدة الخريطة الواحدة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تراكيب جديدة في نموذج المنهج.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/a6d4dc5bd6ce1c6f7e67.webp)\nمن الخريطة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G=4</mtext></math>` ، ومن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H=6</mtext></math>` ؛\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F–H=4+6=10</mtext></math>` وحدات، أي عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10%</mtext></math>`.\nنسبة الارتباط هي الباقي الأبوي : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%−10%=90%</mtext></math>` ، الاختيار أ.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/a6d4dc5bd6ce1c6f7e67.webp)\n:::\n\n:::mcq\nid: bio-q-p084-q39\ntitle: تصنيف الأسئلة، السؤال 39، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: إذا كانت نسبة الارتباط بين الجينين 80% فما نسبة تكرار عملية العبور بينهما؟\n- [ ] option-1 | أ. 80%\n- [ ] option-2 | ب. 60%\n- [ ] option-3 | ج. 40%\n- [x] option-4 | د. 20%\nexplanation:\nالارتباط هنا نسبة التراكيب الأبوية، والعبور نسبة التراكيب الجديدة، ومجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nالمعطى ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>80%</mtext></math>` ، إذن نسبة العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−80%=20%</mtext></math>` ، الاختيار د.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q40\ntitle: تصنيف الأسئلة، السؤال 40، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: إذا كانت نسبة تكرار عملية العبور بين جينين على أحد الكروموسومات30% فما نسبة الارتباط بينهما؟\n- [ ] option-1 | أ. 30%\n- [ ] option-2 | ب. 60%\n- [x] option-3 | ج. 70%\n- [ ] option-4 | د. 90%\nexplanation:\nنسبة الارتباط في اصطلاح المسألة هي النسبة المتبقية للتراكيب الأبوية بعد استبعاد المؤتلفات الناتجة بالعبور.\nالمعطى عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>30%</mtext></math>` ، لذا الارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−30%=70%</mtext></math>` ، الاختيار ج.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q41\ntitle: تصنيف الأسئلة، السؤال 41، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: إذا كانت نسبة تكرار عملية العبور بين الجين A والجين B تساوي27%، ما نسبة الارتباط بينهما؟\n- [ ] option-1 | أ. 27%\n- [ ] option-2 | ب. 54%\n- [ ] option-3 | ج. 63%\n- [x] option-4 | د. 73%\nexplanation:\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>27%</mtext></math>` يمثل مجموع التراكيب الجديدة بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nوالارتباط يمثل التراكيب الأبوية الباقية.\nالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−27%=73%</mtext></math>` ، الاختيار د. لا نطرح ضعف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>27%</mtext></math>` لأنه مجموع المؤتلفات وليس نسبة فئة واحدة.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p084-q42\ntitle: تصنيف الأسئلة، السؤال 42، صفحة 84\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 84\nquestion: ما نسبة تكرار العبور بين الجينين h وf في خريطة الجينات المجاورة؟\n- [ ] option-1 | أ. 94%\n- [ ] option-2 | ب. 86%\n- [x] option-3 | ج. 14%\n- [ ] option-4 | د. 7%\nexplanation:\nكل وحدة خريطة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تراكيب جديدة في نموذج المسألة.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/898ef5e7e4f71de6eb1e.webp)\nالمسار من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>f</mtext></math>` إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` يمر عبر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g: f–g=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g–h=9</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=5+9=14</mtext></math>` وحدة، فتكرار العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>14%</mtext></math>` ، الاختيار ج. لا نضيف المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e–f</mtext></math>` لأنها خارج الطرفين المطلوبين.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/898ef5e7e4f71de6eb1e.webp)\n:::\n\n:::mcq\nid: bio-q-p085-q43\ntitle: تصنيف الأسئلة، السؤال 43، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: الجين A والجين B مرتبطان على نفس الكروموسوم والمسافة بينهما18 سنتيمورغان، فما نسبة تكرار العبور بين الجينين؟\n- [ ] option-1 | أ. 82%\n- [ ] option-2 | ب. 41%\n- [ ] option-3 | ج. 36%\n- [x] option-4 | د. 18%\nexplanation:\nالسنتيمورغان وحدة خريطة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` من التراكيب المعاد تركيبها بين جينين في النموذج المدرسي.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=18</mtext></math>` سنتيمورغان، إذن نسبة تكرار العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18%</mtext></math>` ، الاختيار د. أما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>82%</mtext></math>` فهي نسبة الارتباط المكملة وليست المطلوب.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q44\ntitle: تصنيف الأسئلة، السؤال 44، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: ما الطرز الجينية للغاميتات التي ينتجها فرد طرازه الجيني (RrGg) إذا كان الجينان (R) و(g) مرتبطان وعند عدم حدوث عملية العبور؟\n- [ ] option-1 | أ. RG، rg\n- [ ] option-2 | ب. RG، Rg، rG، rg\n- [x] option-3 | ج. Rg، rG\n- [ ] option-4 | د. Rr، Gg\nexplanation:\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` على كروموسوم واحد في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrGg</mtext></math>` يحدد الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rg/rG</mtext></math>` ؛\nيحمل الكروموسوم المتناظر الأليلين الباقيين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>`.\nدون عبور تنتقل التركيبات الأصلية نفسها إلى الغاميتات، فينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rG</mtext></math>` فقط، بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` لكل نوع.\nإذن الاختيار ج؛\nلا يضم الغاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rr</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gg</mtext></math>` لأنه أحادي المجموعة ويحمل أليلاً واحداً من كل جين.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q45\ntitle: تصنيف الأسئلة، السؤال 45، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: كانت نتائج التلقيح التجريبي (AaBb × aabb): أفراد يحملون صفة الأبوين900، أفراد تراكيب جينية جديدة100. ما المسافة بين الجينين (a،b) بوحدة السنتيمورغان؟\n\n\n\n- [ ] option-1 | أ. 5\n- [ ] option-2 | ب. 8\n- [ ] option-3 | ج. 9\n- [x] option-4 | د. 10\nexplanation:\nفي التلقيح الاختباري تكشف فئات النسل غاميتات الفرد غير النقي؛\nفتُحسب نسبة التراكيب الجديدة بقسمة عددها على النسل كله ثم الضرب في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100</mtext></math>`.\nالعدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=900+100=1000</mtext></math>`.\nنسبة التراكيب الجديدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(100÷1000)×100=10%</mtext></math>`.\nكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` يقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` سنتيمورغان؛\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` سنتيمورغان، الاختيار د.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q46\ntitle: تصنيف الأسئلة، السؤال 46، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: ذبابة خل طرازها الجيني لصفتين RrDd إذا علمت أن R–D مرتبطان على نفس الكروموسوم، أي الغاميتات الآتية من المتوقع تكونها في حالة عدم حدوث عبور؟\n- [x] option-1 | أ. RD، rd\n- [ ] option-2 | ب. Rd، rD\n- [ ] option-3 | ج. Rr، Dd\n- [ ] option-4 | د. RR، DD\nexplanation:\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` معاً على أحد الكروموسومين في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrDd</mtext></math>` يجعل ترتيب الجينين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD/rd</mtext></math>` ؛\nالآخر يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>d</mtext></math>`.\nدون عبور لا تتبادل القطع، فتظل التراكيب الأبوية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RD</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rd</mtext></math>` وحدها في الغاميتات، مناصفة.\nالإجابة أ؛\nأما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rd</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rD</mtext></math>` فيحتاجان العبور لهذا الطور.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p088-q7\ntitle: تصنيف الأسئلة، السؤال 7، صفحة 88\nquestion: السؤال 7\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند إجراء تلقيح تجريبي لنبات طرازه الجيني RrYy كان النسل يحمل الصفات والنسب:47.5% خضراء مجعدة،2.5% خضراء مستديرة،2.5% صفراء مجعدة،47.5% صفراء مستديرة. إذا علمت أن جينات لون البذرة وشكلها تقع على كروموسوم واحد، فسر هذه النتائج على أسس وراثية.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للمستدير السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمجعد، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` للأصفر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>y</mtext></math>` للأخضر، وفق ترميز البازيلاء المعتاد في المسألة. التلقيح التجريبي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrYy × rryy</mtext></math>` يجعل الكاشف يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ry</mtext></math>` فقط.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` صفراء مستديرة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` خضراء مجعدة تكشفان غاميتين أبويتين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ry</mtext></math>` ؛\nإذن النبات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RY/ry</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` صفراء مجعدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` خضراء مستديرة تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ry</mtext></math>` ؛\nنتجتا بتبادل قطع بين كروماتيدين غير شقيقين.\nالارتباط أبقى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5+47.5=95%</mtext></math>` أبوية، والعبور أعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5+2.5=5%</mtext></math>` مؤتلفات.\nاتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ry</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ry</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ry</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrYy</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rryy</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrYy</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Rryy</mtext></math>` على الترتيب.\n:::\n\n:::exam-question\nid: bio-q-p088-q9-1\ntitle: تصنيف الأسئلة، السؤال 9، الفرع 1، صفحة 88\nquestion: السؤال 9، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تلقيح ذكر ذبابة فاكهة أسود الجسم ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة غير نقية للصفتين، ظهر الأبناء بالأعداد:92 رمادية الجسم طبيعية الأجنحة؛88 سوداء الجسم ضامرة الجناح؛9 سوداء الجسم طبيعية الأجنحة؛11 رمادية الجسم ضامرة الأجنحة. جين اللون الرماديB سائد على الأسودb وجين الأجنحة الطبيعيةG سائد على الضامرةg.\n\n1- اكتب الطرز الجينية للأبوين.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للرمادي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد للجناح الطبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامر. الذكر الأسود الضامر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط، فتُظهر فئات النسل غاميتات الأنثى.\nالأكثر عدداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92</mtext></math>` رمادي طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>88</mtext></math>` أسود ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` الأبويتين؛\nوالأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9</mtext></math>` أسود طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>11</mtext></math>` رمادي ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` الجديدتين.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg/bg</mtext></math>`. الأم رمادية طبيعية غير نقية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` وترتيبها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` ؛\nارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` يفسر كثرة هاتين الفئتين.\n:::\n\n:::exam-question\nid: bio-q-p088-q9-2\ntitle: تصنيف الأسئلة، السؤال 9، الفرع 2، صفحة 88\nquestion: السؤال 9، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تلقيح ذكر ذبابة فاكهة أسود الجسم ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة غير نقية للصفتين، ظهر الأبناء بالأعداد:92 رمادية الجسم طبيعية الأجنحة؛88 سوداء الجسم ضامرة الجناح؛9 سوداء الجسم طبيعية الأجنحة؛11 رمادية الجسم ضامرة الأجنحة. جين اللون الرماديB سائد على الأسودb وجين الأجنحة الطبيعيةG سائد على الضامرةg.\n\n2- اكتب الطرز الجينية لغاميتات الأنثى موضحاً الغاميتات الناتجة بسبب العبور والغاميتات الناتجة بدون العبور.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للرمادي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد للجناح الطبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامر. الذكر الأسود الضامر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط، فتُظهر فئات النسل غاميتات الأنثى.\nالأكثر عدداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92</mtext></math>` رمادي طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>88</mtext></math>` أسود ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` الأبويتين؛\nوالأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9</mtext></math>` أسود طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>11</mtext></math>` رمادي ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` الجديدتين.\nالأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` تعطي دون عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>`. وبسبب العبور تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>`.\nمجموع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92+88+9+11=200</mtext></math>` ؛\nالنسب المشاهدة لكل غاميت، بعد القسمة على مجموع النسل والضرب في 100:\n\n| الغاميت | الحساب والنسبة المئوية |\n|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(92÷200)×100=46%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(88÷200)×100=44%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(9÷200)×100=4.5%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(11÷200)×100=5.5%</mtext></math>` |\n\nاختلاف الفئتين المتناظرتين قليلاً متوقع في عينة.\n:::\n\n:::exam-question\nid: bio-q-p088-q9-3\ntitle: تصنيف الأسئلة، السؤال 9، الفرع 3، صفحة 88\nquestion: السؤال 9، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 88\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تلقيح ذكر ذبابة فاكهة أسود الجسم ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة غير نقية للصفتين، ظهر الأبناء بالأعداد:92 رمادية الجسم طبيعية الأجنحة؛88 سوداء الجسم ضامرة الجناح؛9 سوداء الجسم طبيعية الأجنحة؛11 رمادية الجسم ضامرة الأجنحة. جين اللون الرماديB سائد على الأسودb وجين الأجنحة الطبيعيةG سائد على الضامرةg.\n\n3- ما المسافة بين جين لون الجسم وجين حجم الأجنحة؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للرمادي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` سائد للجناح الطبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامر. الذكر الأسود الضامر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط، فتُظهر فئات النسل غاميتات الأنثى.\nالأكثر عدداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92</mtext></math>` رمادي طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>88</mtext></math>` أسود ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` الأبويتين؛\nوالأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9</mtext></math>` أسود طبيعي و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>11</mtext></math>` رمادي ضامر يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` الجديدتين.\nالمسافة بوحدة الخريطة تساوي نسبة التراكيب الجديدة.\nعدد الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=9+11=20</mtext></math>` ؛\nالعدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=92+88+9+11=200</mtext></math>`.\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(20÷200)×100=10%</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` سنتيمورغان. لا نستخدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>88</mtext></math>` في البسط لأنهما فئتان أبويتان.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p089-q14-1\ntitle: تصنيف الأسئلة، السؤال 14، الفرع 1، صفحة 89\nquestion: السؤال 14، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. عند تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل كانت النسب:45.5% سوداء طويلة؛45.5% بيضاء قصيرة؛4.5% بيضاء طويلة؛4.5% سوداء قصيرة. جين الأسودB سائد على الأبيضb، والطويلT سائد على القصيرt.\n\n1- ما الطرز الجينية للأبوين للصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` سائد للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` سائد للطويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأنثى بيضاء قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt/bt</mtext></math>` ، فتعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` وحده.\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` بين الأبناء يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` عند الذكر الأسود الطويل؛\nلذلك هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbTt</mtext></math>`. الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` سوداء طويلة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` بيضاء قصيرة تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` ؛\nإذن ترتيب الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>`.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt × bt/bt</mtext></math>` ، ومع العبور ينتج الأب أيضاً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` لكل منهما.\n:::\n\n:::exam-question\nid: bio-q-p089-q14-3\ntitle: تصنيف الأسئلة، السؤال 14، الفرع 3، صفحة 89\nquestion: السؤال 14، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 89\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. عند تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل كانت النسب:45.5% سوداء طويلة؛45.5% بيضاء قصيرة؛4.5% بيضاء طويلة؛4.5% سوداء قصيرة. جين الأسودB سائد على الأبيضb، والطويلT سائد على القصيرt.\n\n3- ما المسافة بين جيني الصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` ؛\nفتُعد الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` سوداء طويلة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` بيضاء قصيرة أبويتين، والصغيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` بيضاء طويلة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` سوداء قصيرة جديدتين.\nنسبة المؤتلفات تساوي مجموع الفئتين الجديدتين : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%+4.5%=9%</mtext></math>`.\nإذن المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9</mtext></math>` سنتيمورغان. المقصود رصد العبور بين الجينين، فلا نجمع الفئات الأبوية.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p090-q20-1\ntitle: تصنيف الأسئلة، السؤال 20، الفرع 1، صفحة 90\nquestion: السؤال 20، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل شعره مموج وأصابعه قصيرة وعيونه عسلية من فتاة شعرها مستقيم وأصابعها طويلة وعيونها زرقاء، فكان من بين النسل طفل شعره مستقيم وأصابعه طويلة وعيونه زرقاء. جينا الأصابع ولون العيون محمولان على نفس الكروموسوم. استخدمT للأصابع القصيرة وt للطويلة،H للعيون العسلية وh للزرقاء.\n\n1- اكتب الطرز الجينية لكل من الأبوين للصفات معاً.\nsolution:\nشكل الشعر هنا سيادة غير تامة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` للمجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للمستقيم، والهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SS</mtext></math>`.\nفي نموذج السؤال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للأصابع القصيرة السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للطويلة، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للعسلية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للزرقاء. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt hh</mtext></math>` ؛\nوالطفل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt hh</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` من الأب، فيكون الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtHh</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS TtHh</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SS tthh</mtext></math>`. الجينان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` مرتبطان، لكن الطور غير محسوم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TH/th</mtext></math>` يحقق الطفل دون عبور، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Th/tH</mtext></math>` يستطيع تحقيقه عبر غاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>th</mtext></math>` مؤتلف.\nلا تنص مقدمة السؤال على غياب العبور عند إنجاب الطفل، فلا نستنتج الطور الاقتراني يقيناً.\n:::\n\n:::exam-question\nid: bio-q-p090-q20-2\ntitle: تصنيف الأسئلة، السؤال 20، الفرع 2، صفحة 90\nquestion: السؤال 20، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90 · صياغة تعليمية معدّلة\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل شعره مموج وأصابعه قصيرة وعيونه عسلية من فتاة شعرها مستقيم وأصابعها طويلة وعيونها زرقاء، فولد لهما طفل شعره مستقيم وأصابعه طويلة وعيونه زرقاء. أليل الأصابع القصيرة T سائد على t، وأليل العيون العسلية H سائد على h. الجينان T و H مرتبطان ارتباطًا تامًا، ولا يحدث عبور بينهما. أليل شكل الشعر C للأجعد و S للمستقيم، والطراز CS مموج، وجين الشعر مستقل عن الجينين المرتبطين. ما أنواع غاميتات الأبوين؟\nsolution:\nظهور الطفل tt hh يعني أن كل والد أعطى t و h. والأم طويلة الأصابع زرقاء العينين، فيكون طرازها tt hh. الأب قصير الأصابع عسلي العينين، لكنه أعطى t و h؛ لذلك هو Tt Hh.\n\nمع الارتباط التام وغياب العبور، يكون th الذي أعطاه الأب ترتيبًا أبويًا. والترتيب الآخر لا بد أن يكون TH.\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mrow><mi mathvariant="normal">f</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">t</mi><mi mathvariant="normal">h</mi><mi mathvariant="normal">e</mi><mi mathvariant="normal">r</mi></mrow><mo>:</mo><mspace width="1em"/><mi>C</mi><mi>S</mi><mtext> </mtext><mo separator="true">;</mo><mtext> </mtext><mfrac><mrow><mi>T</mi><mi>H</mi></mrow><mrow><mi>t</mi><mi>h</mi></mrow></mfrac></mrow></math>\n```\n\n\n\nالشعر المموج طرازه CS، والمستقيم SS. لذلك غاميت الأم Sth فقط.\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mrow><mi mathvariant="normal">m</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">t</mi><mi mathvariant="normal">h</mi><mi mathvariant="normal">e</mi><mi mathvariant="normal">r</mi></mrow><mo>:</mo><mspace width="1em"/><mi>S</mi><mi>S</mi><mtext> </mtext><mo separator="true">;</mo><mtext> </mtext><mfrac><mrow><mi>t</mi><mi>h</mi></mrow><mrow><mi>t</mi><mi>h</mi></mrow></mfrac></mrow></math>\n```\n\n\n\nجين الشعر مستقل؛ ندمج كلًا من C و S مع كل من TH و th.\n\nغاميتات الأب: CTH، Cth، STH، Sth.\n\nغاميت الأم: Sth فقط.\n\n**المصدر:** الصفحات 28، 34، 35 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p090-q20-4\ntitle: تصنيف الأسئلة، السؤال 20، الفرع 4، صفحة 90\nquestion: السؤال 20، الفرع 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 90\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل شعره مموج وأصابعه قصيرة وعيونه عسلية من فتاة شعرها مستقيم وأصابعها طويلة وعيونها زرقاء، فكان من بين النسل طفل شعره مستقيم وأصابعه طويلة وعيونه زرقاء. جينا الأصابع ولون العيون محمولان على نفس الكروموسوم. استخدمT للأصابع القصيرة وt للطويلة،H للعيون العسلية وh للزرقاء.\n\n4- ما مبدأ الوراثة للصفات الثلاث؟\nsolution:\nشكل الشعر يخضع للسيادة غير التامة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج وسطياً بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC</mtext></math>` المجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SS</mtext></math>` المستقيم.\nالأصابع ولون العينين، في النموذج المبسط المعطى، لكل منهما سيادة تامة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للقصير يسود على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للطويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للعسلي يسود على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للأزرق.\nجيناهما مرتبطان لأن السؤال ينص على وجودهما على الكروموسوم نفسه؛\nفتقل استقلالية انتقالهما، ويمكن أن يفك العبور بعض هذا الارتباط.\nإذن نميز علاقة السيادة داخل كل جين عن الارتباط بين الجينين.\n:::\n\n:::exam-question\nid: bio-q-p091-q22-1\ntitle: تصنيف الأسئلة، السؤال 22، الفرع 1، صفحة 91\nquestion: السؤال 22، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تزاوج نبات أملس البذور أصفر الأزهار مع نبات مجعد البذور أبيض الأزهار كانت الأفراد الناتجة:47.5% ملساء صفراء؛47.5% مجعدة بيضاء؛2.5% مجعدة صفراء؛2.5% ملساء بيضاء. جين الملساءB سائد على المجعدةb وجين الأزهار الصفراءR سائد على البيضاءr، وجينا الصفتين مرتبطان على نفس الكروموسوم.\n\n1- ما الطرز الجينية للأبوين وغاميتات الأبوين للصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأملس السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للمجعد، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأصفر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للأبيض. المجعد الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbrr</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` فقط؛\nفتُظهر فئات النسل غاميتات الأب الآخر.\nالفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` ملساء صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` مجعدة بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` الأبويتين، فيكون النبات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR/br</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` مجعدة صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` ملساء بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br</mtext></math>` المؤتلفتين.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR/br × br/br</mtext></math>`. غاميتات الأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR47.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br47.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR2.5%</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br2.5%</mtext></math>` ؛\nغاميت الثاني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` فقط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbRr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbrr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbRr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bbrr</mtext></math>` وفق ترتيب الغاميتات المذكور.\n:::\n\n:::exam-question\nid: bio-q-p091-q22-2\ntitle: تصنيف الأسئلة، السؤال 22، الفرع 2، صفحة 91\nquestion: السؤال 22، الفرع 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تزاوج نبات أملس البذور أصفر الأزهار مع نبات مجعد البذور أبيض الأزهار كانت الأفراد الناتجة:47.5% ملساء صفراء؛47.5% مجعدة بيضاء؛2.5% مجعدة صفراء؛2.5% ملساء بيضاء. جين الملساءB سائد على المجعدةb وجين الأزهار الصفراءR سائد على البيضاءr، وجينا الصفتين مرتبطان على نفس الكروموسوم.\n\n2- فسر سبب ظهور النسب المعطاة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأملس السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للمجعد، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأصفر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للأبيض. المجعد الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbrr</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` فقط؛\nفتُظهر فئات النسل غاميتات الأب الآخر.\nالفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` ملساء صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` مجعدة بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` الأبويتين، فيكون النبات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR/br</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` مجعدة صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` ملساء بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br</mtext></math>` المؤتلفتين.\nالارتباط يبقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` غالباً؛\nفتبلغ نسبة الأبويين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5+47.5=95%</mtext></math>`.\nالعبور تبادل قطع بين كروماتيدين غير شقيقين، فيكوّن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br</mtext></math>` ؛\nنسبتهما الكلية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5+2.5=5%</mtext></math>`.\nلذلك تظهر الفئات الأبوية أكثر من الجديدة، ولا تظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1:1:1</mtext></math>` التي تتوقعها صفتان مستقلتان في التلقيح الاختباري.\n:::\n\n:::exam-question\nid: bio-q-p091-q22-3\ntitle: تصنيف الأسئلة، السؤال 22، الفرع 3، صفحة 91\nquestion: السؤال 22، الفرع 3\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 91\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nعند تزاوج نبات أملس البذور أصفر الأزهار مع نبات مجعد البذور أبيض الأزهار كانت الأفراد الناتجة:47.5% ملساء صفراء؛47.5% مجعدة بيضاء؛2.5% مجعدة صفراء؛2.5% ملساء بيضاء. جين الملساءB سائد على المجعدةb وجين الأزهار الصفراءR سائد على البيضاءr، وجينا الصفتين مرتبطان على نفس الكروموسوم.\n\n3- ما الطرز الجينية للأفراد الناتجة التي تحمل تراكيب جينية جديدة؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأملس السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للمجعد، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأصفر السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للأبيض. المجعد الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbrr</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` فقط؛\nفتُظهر فئات النسل غاميتات الأب الآخر.\nالفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` ملساء صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47.5%</mtext></math>` مجعدة بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` الأبويتين، فيكون النبات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BR/br</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` مجعدة صفراء و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` ملساء بيضاء تقابلان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br</mtext></math>` المؤتلفتين.\nالمطلوب طرز الأفراد لا الغاميتات. الغاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Br</mtext></math>` يتحد مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` الكاشف فينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bbrr</mtext></math>` «ملساء بيضاء»؛\nوالغاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` يتحد مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>br</mtext></math>` فينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbRr</mtext></math>` «مجعدة صفراء».\nإذن الفردان الحاملان تراكيب جديدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bbrr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbRr</mtext></math>` ، ولكل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2.5%</mtext></math>` من النسل.\n:::\n\n:::exam-question\nid: bio-q-p095-q41-1\ntitle: صفحة 95، السؤال 41، الفرع 1\nquestion: ما الطراز الشكلي للنباتين الأبوين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج بين نباتي ذرة ونسب الأفراد الناتجة لصفتين مرتبطتين هما لون البذور وشكلها. جين وجود اللون (M) سائد على عدم وجوده (m)، وجين البذور الملساء (B) سائد على جين البذور المجعدة (b).\n\n| الغاميتات | غير مبين | غير مبين | Mb | (1) |\n|---|---|---|---|---|\n| mb | (2)، 46.2% | mmbb، 46.2% | 3.8% | mmBb، 3.8% |\n\nما الطراز الشكلي للنباتين الأبوين؟\nsolution:\nM للون السائد وm لغيابه، وB للأملس السائد وb للمجعد.\n\nغاميت الصفmb يحمل الأليلين المتنحيين؛ لذلك يكون صاحبهmmbb، ويكشف كل ناتج الغاميت الذي ساهم به النبات الآخر.\n\nالفئةmmbb ذات46.2% جاءت منmb، والفئةmmBb ذات3.8% جاءت منmB. وبما أن الفئتين الكبيرتين أبويتان، فالفئة الكبيرة الأخرى جاءت منMB، والفئة الجديدة الأخرى منMb.\n\nإذن النبات الهجينMB/mb، والآخرmb/mb.\n\nوجودM وB يجعل الهجين **ملوناً أملس البذور**، أماmmbb فهو **عديم اللون مجعد البذور**.\n:::\n\n:::exam-question\nid: bio-q-p095-q41-2\ntitle: صفحة 95، السؤال 41، الفرع 2\nquestion: ما الطراز الجيني لكل من الغاميت والفرد المشار إليهما بالرقمين (1،2)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج بين نباتي ذرة ونسب الأفراد الناتجة لصفتين مرتبطتين هما لون البذور وشكلها. جين وجود اللون (M) سائد على عدم وجوده (m)، وجين البذور الملساء (B) سائد على جين البذور المجعدة (b).\n\n| الغاميتات | غير مبين | غير مبين | Mb | (1) |\n|---|---|---|---|---|\n| mb | (2)، 46.2% | mmbb، 46.2% | 3.8% | mmBb، 3.8% |\n\nما الطراز الجيني لكل من الغاميت والفرد المشار إليهما بالرقمين (1،2)؟\nsolution:\nM للون السائد وm لغيابه، وB للأملس السائد وb للمجعد.\n\nغاميت الصفmb يحمل الأليلين المتنحيين؛ لذلك يكون صاحبهmmbb، ويكشف كل ناتج الغاميت الذي ساهم به النبات الآخر.\n\nالفئةmmbb ذات46.2% جاءت منmb، والفئةmmBb ذات3.8% جاءت منmB. وبما أن الفئتين الكبيرتين أبويتان، فالفئة الكبيرة الأخرى جاءت منMB، والفئة الجديدة الأخرى منMb.\n\nإذن النبات الهجينMB/mb، والآخرmb/mb.\n\nالرقم(1) غاميت يقابلmb ويكوّنmmBb؛ إذن **(1)=mB**.\n\nالفرد(2) من اتحادMB معmb:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>M</mi><mi>B</mi><mo>×</mo><mi>m</mi><mi>b</mi><mo>⟶</mo><mi>M</mi><mi>m</mi><mi>B</mi><mi>b</mi></mrow></math>\n```\n\n\n\nإذن **(2)=MmBb**.\n:::\n\n:::exam-question\nid: bio-q-p095-q41-3\ntitle: صفحة 95، السؤال 41، الفرع 3\nquestion: ما المسافة بين جيني الصفتين على الكروموسوم بوحدة خريطة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج بين نباتي ذرة ونسب الأفراد الناتجة لصفتين مرتبطتين هما لون البذور وشكلها. جين وجود اللون (M) سائد على عدم وجوده (m)، وجين البذور الملساء (B) سائد على جين البذور المجعدة (b).\n\n| الغاميتات | غير مبين | غير مبين | Mb | (1) |\n|---|---|---|---|---|\n| mb | (2)، 46.2% | mmbb، 46.2% | 3.8% | mmBb، 3.8% |\n\nما المسافة بين جيني الصفتين على الكروموسوم بوحدة خريطة؟\nsolution:\nM للون السائد وm لغيابه، وB للأملس السائد وb للمجعد.\n\nغاميت الصفmb يحمل الأليلين المتنحيين؛ لذلك يكون صاحبهmmbb، ويكشف كل ناتج الغاميت الذي ساهم به النبات الآخر.\n\nالفئةmmbb ذات46.2% جاءت منmb، والفئةmmBb ذات3.8% جاءت منmB. وبما أن الفئتين الكبيرتين أبويتان، فالفئة الكبيرة الأخرى جاءت منMB، والفئة الجديدة الأخرى منMb.\n\nإذن النبات الهجينMB/mb، والآخرmb/mb.\n\nالمسافة بوحدات الخريطة تساوي نسبة التراكيب الجديدة في نموذج الدرس. نجمع الفئتين الجديدتين:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>r</mi><mo>=</mo><mn>3.8</mn><mi mathvariant="normal">%</mi><mo>+</mo><mn>3.8</mn><mi mathvariant="normal">%</mi><mo>=</mo><mn>7.6</mn><mi mathvariant="normal">%</mi></mrow></math>\n```\n\n\n\nإذن المسافة **7.6 وحدات خريطة**.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q46-1\ntitle: صفحة 96، السؤال 46، الفرع 1\nquestion: ما المسافة بين الجين A والجين G؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط والمسافة بوحدة خريطة بين أربعة جينات مرتبطة:\n\n| الجينات | المسافة | نسبة الارتباط |\n|---|---|---|\n| T وD | 18 | — |\n| G وA | — | 97% |\n| G وD | — | 92% |\n| T وA | 7 | — |\n\nما المسافة بين الجين A والجين G؟\nsolution:\nفي اصطلاح المنهج، الارتباط نسبة الأبويين والعبور نسبة الجديد؛\nمجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>` ، وكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` جديد يقابل وحدة خريطة.\nللزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>97%</mtext></math>` ؛\nإذن العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−97%=3%</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–G=3</mtext></math>` وحدات خريطة.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q46-2\ntitle: صفحة 96، السؤال 46، الفرع 2\nquestion: ما نسبة الارتباط بين الجين D والجين A؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط والمسافة بوحدة خريطة بين أربعة جينات مرتبطة:\n\n| الجينات | المسافة | نسبة الارتباط |\n|---|---|---|\n| T وD | 18 | — |\n| G وA | — | 97% |\n| G وD | — | 92% |\n| T وA | 7 | — |\n\nما نسبة الارتباط بين الجين D والجين A؟\nsolution:\nكل وحدة خريطة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تراكيب جديدة، ونسبة الارتباط مكملة لهذه النسبة إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nنحوّل الارتباط إلى مسافة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–G=100−97=3</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G–D=100−92=8</mtext></math>` وحدات.\nمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T–A=7</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T–D=18</mtext></math>` تكون المسافات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7+3+8=18</mtext></math>` ، فيلائمها الترتيب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D=3+8=11</mtext></math>` وحدة؛\nإذن العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>11%</mtext></math>` ، والارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−11%=89%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q46-3\ntitle: صفحة 96، السؤال 46، الفرع 3\nquestion: ما نسبة تكرار التراكيب الجينية بين الجين G والجين D؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط والمسافة بوحدة خريطة بين أربعة جينات مرتبطة:\n\n| الجينات | المسافة | نسبة الارتباط |\n|---|---|---|\n| T وD | 18 | — |\n| G وA | — | 97% |\n| G وD | — | 92% |\n| T وA | 7 | — |\n\nما نسبة تكرار التراكيب الجينية بين الجين G والجين D؟\nsolution:\nالجدول يعطي ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92%</mtext></math>` بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` ، أي أن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>92%</mtext></math>` من النسل يحتفظ بالتراكيب الأبوية. نفسر «تكرار التراكيب الجينية» هنا باصطلاح المسألة على أنه تكرار **التراكيب الجديدة الناتجة بالعبور**؛ المطلوب نسبتها، فهي مكملة إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−92%=8%</mtext></math>`.\nلو أريدت المسافة لكانت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8</mtext></math>` وحدات خريطة؛\nهنا الجواب نسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q46-4\ntitle: صفحة 96، السؤال 46، الفرع 4\nquestion: ارسم خارطة جينات تحدد مواقع الجينات.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط والمسافة بوحدة خريطة بين أربعة جينات مرتبطة:\n\n| الجينات | المسافة | نسبة الارتباط |\n|---|---|---|\n| T وD | 18 | — |\n| G وA | — | 97% |\n| G وD | — | 92% |\n| T وA | 7 | — |\n\nارسم خارطة جينات تحدد مواقع الجينات.\nsolution:\nنستخدم كل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` عبور كوحدة خريطة، والعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−</mtext></math>` الارتباط.\nنحوّل الارتباط إلى مسافة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–G=100−97=3</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G–D=100−92=8</mtext></math>` وحدات.\nمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T–A=7</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T–D=18</mtext></math>` تكون المسافات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7+3+8=18</mtext></math>` ، فيلائمها الترتيب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>`.\nنجعل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` |\n|---|---|---|---|---|\n| الموقع بوحدة خريطة | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/743b931369ed6ac13336.webp)\nتوافق المسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8</mtext></math>` جميع معطيات الجدول؛\nوعكس الاتجاه يعطي الخريطة نفسها.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q46-5\ntitle: صفحة 96، السؤال 46، الفرع 5\nquestion: ما المقصود بالجينات المرتبطة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط والمسافة بوحدة خريطة بين أربعة جينات مرتبطة:\n\n| الجينات | المسافة | نسبة الارتباط |\n|---|---|---|\n| T وD | 18 | — |\n| G وA | — | 97% |\n| G وD | — | 92% |\n| T وA | 7 | — |\n\nما المقصود بالجينات المرتبطة؟\nsolution:\n**الإجابة:** جينات تقع على الكروموسوم نفسه وتميل إلى أن تورث معاً كوحدة واحدة.\n\n**الشاهد من الكتاب:**\n\n> نستنتج مما سبق أن الجينات المرتبطةLinked Genes هي تلك الجينات(عددها أكثر من زوج من الجينات) التي تقع على الكروموسوم نفسه، وتكون قريبة بعضها من بعض، ومرتبطة بعضها مع بعض؛ لذا فهي تورث معاً كوحدة واحدة.\n\n**المصدر:** صفحة 34 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p097-q47-1\ntitle: صفحة 97، السؤال 47، الفرع 1\nquestion: احسب نسبة الارتباط بين الجينين A وD.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتقع الجينات A وB وC وD على الكروموسوم نفسه. نسبة تكرار التراكيب الجينية الجديدة بين A وB = 5%، وبين C وD = 2%، ونسبة الارتباط بين D وB = 99% وبين C وA = 98%.\n\nاحسب نسبة الارتباط بين الجينين A وD.\nsolution:\nكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` جديد يقابل وحدة خريطة؛\nوالارتباط مكمل للعبور.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=2</mtext></math>` مباشرة من نسبتي الجديد.\nومن الارتباط : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–B=100−99=1</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–A=100−98=2</mtext></math>`.\nإذا وضعنا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` ، فيلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2+2+1=5</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D=2+2=4</mtext></math>` ؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4%</mtext></math>` ، فالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−4%=96%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p097-q47-2\ntitle: صفحة 97، السؤال 47، الفرع 2\nquestion: ما نسبة حدوث عبور بين الجينين C وB؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتقع الجينات A وB وC وD على الكروموسوم نفسه. نسبة تكرار التراكيب الجينية الجديدة بين A وB = 5%، وبين C وD = 2%، ونسبة الارتباط بين D وB = 99% وبين C وA = 98%.\n\nما نسبة حدوث عبور بين الجينين C وB؟\nsolution:\nالعبور يقدّر نسبة المؤتلفات ويقابل المسافة بوحدة الخريطة.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=2</mtext></math>` مباشرة من نسبتي الجديد.\nومن الارتباط : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–B=100−99=1</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–A=100−98=2</mtext></math>`.\nإذا وضعنا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` ، فيلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2+2+1=5</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–B=2+1=3</mtext></math>` وحدات؛\nإذن نسبة العبور بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p097-q47-3\ntitle: صفحة 97، السؤال 47، الفرع 3\nquestion: ما المقصود بالخرائط الجينية؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتقع الجينات A وB وC وD على الكروموسوم نفسه. نسبة تكرار التراكيب الجينية الجديدة بين A وB = 5%، وبين C وD = 2%، ونسبة الارتباط بين D وB = 99% وبين C وA = 98%.\n\nما المقصود بالخرائط الجينية؟\nsolution:\n**الإجابة:** ترتيب خطي افتراضي لمواقع الجينات على طول كروموسوم معين.\n\n**الشاهد من الكتاب:**\n\n> التي تمثل ترتيباً خطياً افتراضياً لمواقع الجينات على طول كروموسوم معين\n\n**المصدر:** صفحة 66 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p097-q47-4\ntitle: صفحة 97، السؤال 47، الفرع 4\nquestion: ارسم خارطة جينية تحدد مواقع هذه الجينات.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتقع الجينات A وB وC وD على الكروموسوم نفسه. نسبة تكرار التراكيب الجينية الجديدة بين A وB = 5%، وبين C وD = 2%، ونسبة الارتباط بين D وB = 99% وبين C وA = 98%.\n\nارسم خارطة جينية تحدد مواقع هذه الجينات.\nsolution:\nكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` من التراكيب الجديدة يقابل وحدة خريطة، والعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−</mtext></math>` الارتباط.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=2</mtext></math>` مباشرة من نسبتي الجديد.\nومن الارتباط : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–B=100−99=1</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–A=100−98=2</mtext></math>`.\nإذا وضعنا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` ، فيلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2+2+1=5</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` |\n|---|---|---|---|---|\n| الموقع | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/932bdc06962e52b79696.webp)\nإذن المسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` ؛\nوتحقق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–B=1</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–A=2</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p097-q49-1\ntitle: صفحة 97، السؤال 49، الفرع 1\nquestion: ما المسافة بين جين لون الجسم وجين حجم الأجنحة على الكروموسوم بوحدة خريطة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي ذبابة الفاكهة جين لون الجسم الرمادي G سائد على جين لون الجسم الأسود (g)، وجين حجم الأجنحة الطبيعية (T) سائد على جين الأجنحة الضامرة (t). عند تزاوج ذكر أسود ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة (غير متماثلة الجينات للصفتين) نتجت أفراد بالأعداد والطرز الجينية: GgTt: 151، ggtt: 149، Ggtt: 51، ggTt: 49.\n\nما المسافة بين جين لون الجسم وجين حجم الأجنحة على الكروموسوم بوحدة خريطة؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطبيعي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للضامر. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ggtt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` فقط. الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>151 GgTt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>149 ggtt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` الأبويتين عند الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT/gt</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>51 Ggtt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>49 ggTt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gT</mtext></math>` الجديدتين.\nعدد الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=51+49=100</mtext></math>` ؛\nالعدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=151+149+51+49=400</mtext></math>`.\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(100÷400)×100=25%</mtext></math>`. إذن المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>25</mtext></math>` وحدة خريطة.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p097-q49-2\ntitle: صفحة 97، السؤال 49، الفرع 2\nquestion: اكتب الطرز الجينية للغاميتات الناتجة عن عملية العبور.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي ذبابة الفاكهة جين لون الجسم الرمادي G سائد على جين لون الجسم الأسود (g)، وجين حجم الأجنحة الطبيعية (T) سائد على جين الأجنحة الضامرة (t). عند تزاوج ذكر أسود ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة (غير متماثلة الجينات للصفتين) نتجت أفراد بالأعداد والطرز الجينية: GgTt: 151، ggtt: 149، Ggtt: 51، ggTt: 49.\n\nاكتب الطرز الجينية للغاميتات الناتجة عن عملية العبور.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطبيعي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للضامر. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ggtt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` فقط. الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>151 GgTt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>149 ggtt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` الأبويتين عند الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT/gt</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>51 Ggtt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>49 ggTt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gT</mtext></math>` الجديدتين.\nالغاميتات المعاد تركيبها هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gT</mtext></math>` ؛\nفاتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gt</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` الأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ggtt(51)</mtext></math>` ، واتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gT</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ggTt(49)</mtext></math>`.\nلا نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ggtt</mtext></math>` كغاميت لأنه طراز الفرد الناتج لا الغاميت.\n:::\n\n:::exam-question\nid: bio-q-p097-q49-3\ntitle: صفحة 97، السؤال 49، الفرع 3\nquestion: اكتب الطرز الجينية لغاميتات الأم عند عدم حدوث عبور.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي ذبابة الفاكهة جين لون الجسم الرمادي G سائد على جين لون الجسم الأسود (g)، وجين حجم الأجنحة الطبيعية (T) سائد على جين الأجنحة الضامرة (t). عند تزاوج ذكر أسود ضامر الأجنحة مع أنثى رمادية الجسم طبيعية الأجنحة (غير متماثلة الجينات للصفتين) نتجت أفراد بالأعداد والطرز الجينية: GgTt: 151، ggtt: 149، Ggtt: 51، ggTt: 49.\n\nاكتب الطرز الجينية لغاميتات الأم عند عدم حدوث عبور.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطبيعي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للضامر. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ggtt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` فقط. الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>151 GgTt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>149 ggtt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` الأبويتين عند الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT/gt</mtext></math>`.\nالفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>51 Ggtt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>49 ggTt</mtext></math>` تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Gt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gT</mtext></math>` الجديدتين.\nدون عبور لا يحدث تبادل للقطع بين الكروماتيدين؛\nفتظل غاميتات الأم الأبوية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>GT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>gt</mtext></math>` وحدها.\nعند غياب العبور كلياً يكون لكل نوع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ، أما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>151</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>149</mtext></math>` فهما العددان المشاهدان للفئتين الأبويتين في العينة التي وقع فيها عبور.\n:::\n\n:::exam-question\nid: bio-q-p097-q52\ntitle: صفحة 97، السؤال 52\nquestion: ارسم خريطة الجينات إذا كانت نسبة الارتباط بين (B، A) 96%، وبين (B، D) 87%، وبين (B، E) 92%، وكانت نسبة تكرار عملية العبور بين (D، A) 17%، ثم أوجد نسبة تكرار عملية العبور بين (E، A).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 97\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nارسم خريطة الجينات إذا كانت نسبة الارتباط بين (B، A) 96%، وبين (B، D) 87%، وبين (B، E) 92%، وكانت نسبة تكرار عملية العبور بين (D، A) 17%، وبين (D ، E) هي 5%، ثم أوجد نسبة تكرار عملية العبور بين (E، A).\nsolution:\nنسبة الارتباط تكمل نسبة التراكيب الجديدة إلى100%، ويقابل كل1% جديد وحدة خريطة في نموذج الدرس.\n\nنحوّل النسب المعطاة:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>B</mi><mi>A</mi><mo>=</mo><mn>100</mn><mo>−</mo><mn>96</mn><mo>=</mo><mn>4</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>B</mi><mi>D</mi><mo>=</mo><mn>100</mn><mo>−</mo><mn>87</mn><mo>=</mo><mn>13</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>B</mi><mi>E</mi><mo>=</mo><mn>100</mn><mo>−</mo><mn>92</mn><mo>=</mo><mn>8</mn></mrow></math>\n```\n\n\n\nومعطيا العبور المباشرانDA=17 وDE=5.\n\nبما أن13+4=17، يقعB بينD وA. وبما أن5+8=13، يقعE بينD وB.\n\nإذن الترتيبD ثمE ثمB ثمA، والمسافات5 ثم8 ثم4.\n\n![الخريطة بعد الحل](assets/lessons/curriculum-evidence/f56229e8d47536b8197b.webp)\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>E</mi><mi>A</mi><mo>=</mo><mn>8</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>12</mn></mrow></math>\n```\n\n\n\nإذن نسبة تكرار العبور بينE وA **12%**.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q55-1\ntitle: صفحة 98، السؤال 55، الفرع 1\nquestion: كم يبعد الجين H عن الجين M؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط ونسبة الانفصال والمسافة بين أربع جينات:\n\n| الجينات | نسبة الارتباط | نسبة الانفصال | المسافة/وحدة خريطة |\n|---|---|---|---|\n| H، F | 90% | — | — |\n| E، H | — | 13% | — |\n| M، F | — | 15% | — |\n| H، M | 95% | — | — |\n| E، F | — | — | 3 |\n\nكم يبعد الجين H عن الجين M؟\nsolution:\nالارتباط هو نسبة التراكيب الأبوية، والعبور مكمله إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>` ويقابل عدد وحدات الخريطة.\nالمعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–M</mtext></math>` ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>95%</mtext></math>` ، إذن العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−95%=5%</mtext></math>`.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–M=5</mtext></math>` وحدات خريطة؛\nلا نستخدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>15%</mtext></math>` الواردة للزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` لأنه زوج مختلف.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q55-2\ntitle: صفحة 98، السؤال 55، الفرع 2\nquestion: ارسم خارطة جينات لهذه الكروموسومات.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط ونسبة الانفصال والمسافة بين أربع جينات:\n\n| الجينات | نسبة الارتباط | نسبة الانفصال | المسافة/وحدة خريطة |\n|---|---|---|---|\n| H، F | 90% | — | — |\n| E، H | — | 13% | — |\n| M، F | — | 15% | — |\n| H، M | 95% | — | — |\n| E، F | — | — | 3 |\n\nارسم خارطة جينات لهذه الكروموسومات.\nsolution:\nنسبة العبور تقابل المسافة، وهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%−</mtext></math>` نسبة الارتباط. لذا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–F=10</mtext></math>` وحدات و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–M=5</mtext></math>` ؛\nكما أن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M–F=15</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–H=13</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–F=3</mtext></math>`.\nلأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5+10=15</mtext></math>` نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` على جهتين من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` ؛\nولأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10+3=13</mtext></math>` يقع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` بعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` بعيداً عن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>`.\nنجعل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>13</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` |\n|---|---|---|---|---|\n| الموقع | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>13</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/d10e02743a3e475d71ae.webp)\nالمسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` ، وتحقق جميع أزواج الجدول.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q55-3\ntitle: صفحة 98، السؤال 55، الفرع 3\nquestion: حدد أي الجينين بينهما أكبر نسبة تكرار عملية العبور، وما مقدارها؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط ونسبة الانفصال والمسافة بين أربع جينات:\n\n| الجينات | نسبة الارتباط | نسبة الانفصال | المسافة/وحدة خريطة |\n|---|---|---|---|\n| H، F | 90% | — | — |\n| E، H | — | 13% | — |\n| M، F | — | 15% | — |\n| H، M | 95% | — | — |\n| E، F | — | — | 3 |\n\nحدد أي الجينين بينهما أكبر نسبة تكرار عملية العبور، وما مقدارها؟\nsolution:\nنسبة العبور تقابل المسافة، وهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%−</mtext></math>` نسبة الارتباط. لذا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–F=10</mtext></math>` وحدات و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–M=5</mtext></math>` ؛\nكما أن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M–F=15</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–H=13</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–F=3</mtext></math>`.\nلأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5+10=15</mtext></math>` نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` على جهتين من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` ؛\nولأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10+3=13</mtext></math>` يقع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` بعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F</mtext></math>` بعيداً عن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>`.\nالطرفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` أبعد زوج؛\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–M=3+10+5=18</mtext></math>` وحدة خريطة.\nكل وحدة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تراكيب جديدة، لذلك أكبر نسبة تكرار عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18%</mtext></math>` بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q56-1\ntitle: صفحة 98، السؤال 56، الفرع 1\nquestion: ما نسبة تكرار عملية العبور بين الأزواج الآتية من الجينات: B،D / E،A؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الرسم جزءاً من خارطة الجينات لأحد الكروموسومات. نسبة تكرار عملية العبور بين A وD = 12%، ونسبة الارتباط بين E وC = 92%.\n\nما نسبة تكرار عملية العبور بين الأزواج الآتية من الجينات: B،D / E،A؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/17ed3310de4a062d9091.webp)\nsolution:\nكل وحدة خريطة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` عبور.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/17ed3310de4a062d9091.webp)\nترتيب الشكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–E=5</mtext></math>`. والمعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D=12%</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12</mtext></math>` وحدة.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–D=A–D−A–B=12−4=8</mtext></math>` ؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–D=8%</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–E=A–D+D–E=12+5=17</mtext></math>` ؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–A=17%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q56-2\ntitle: صفحة 98، السؤال 56، الفرع 2\nquestion: ما نسبة الارتباط بين الأزواج الآتية من الجينات: D،C / D،A؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الرسم جزءاً من خارطة الجينات لأحد الكروموسومات. نسبة تكرار عملية العبور بين A وD = 12%، ونسبة الارتباط بين E وC = 92%.\n\nما نسبة الارتباط بين الأزواج الآتية من الجينات: D،C / D،A؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/17ed3310de4a062d9091.webp)\nsolution:\nالعبور يقابل المسافة، والارتباط مكمله إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/17ed3310de4a062d9091.webp)\nارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–C=92%</mtext></math>` ، إذن المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–E=100−92=8</mtext></math>`. وبما أن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–E=5</mtext></math>` ، فإن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=8−5=3</mtext></math>`.\nالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–C=100%−3%=97%</mtext></math>`.\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–A</mtext></math>` معطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12%</mtext></math>` ؛\nالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–A=100%−12%=88%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p098-q57\ntitle: صفحة 98، السؤال 57\nquestion: ما الوحدة المستخدمة للتعبير عن المسافات بين جينين في الخريطة الجينية؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nما الوحدة المستخدمة للتعبير عن المسافات بين جينين في الخريطة الجينية؟\nsolution:\n**الإجابة:** وحدة خريطة، وتسمى السنتيمورغان.\n\n**الشاهد من الكتاب:**\n\n> الوحدة المستخدمة للتعبير عن المسافات بين جينين في الخريطة الجينية هي السنتيمورغان.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p098-q58\ntitle: صفحة 98، السؤال 58\nquestion: ما المقصود بالعبور؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 98\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nما المقصود بالعبور؟\nsolution:\n**الإجابة:** تبادل أجزاء متناظرة بين كروماتيدين غير شقيقين من كروموسومين متماثلين، في الطور التمهيدي الأول من الانقسام المنصف؛ فيعيد ترتيب الأليلات ويكوّن تراكيب جينية جديدة.\n\n**الشاهد من الكتاب:**\n\n> نستنتج مما سبق أن حالة الارتباط هذه يمكن أن تتغير عند تبادل أجزاء بين كروموسومين متماثلين بعملية العبور، ما يؤدي إلى إعادة تشكيل أو تركيب الأليلات.\n\n**المصدر:** صفحة 35 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p099-q60-2\ntitle: صفحة 99، السؤال 60، الفرع 2\nquestion: احسب نسبة العبور بين الجينين G وB.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 99\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. عند تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل نتج: 45.5% سوداء طويلة الذيل؛ 45.5% بيضاء قصيرة الذيل؛ 4.5% بيضاء طويلة الذيل؛ 4.5% سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين طويل الذيل G سائد على القصير g.\n\nاحسب نسبة العبور بين الجينين G وB.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للقصير. الأنثى البيضاء القصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط؛\nلذا تعكس فئات النسل غاميتات الذكر.\nالأكثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` سوداء طويلة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45.5%</mtext></math>` بيضاء قصيرة أبويتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` ؛\nوالأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` بيضاء طويلة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%</mtext></math>` سوداء قصيرة مؤتلفتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>`.\nنسبة العبور هي مجموع نسبتي الجديد : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4.5%+4.5%=9%</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p099-q61-1\ntitle: صفحة 99، السؤال 61، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 99\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الثدييات صفتا لون الجسم وطول الذيل مرتبطتان محمولتان على نفس الكروموسوم. تزاوجت أنثى سوداء اللون طويلة الذيل مع ذكر أبيض اللون قصير الذيل فكان الناتج: سوداء قصيرة الذيل (16)، بيضاء طويلة الذيل (16)، بيضاء قصيرة الذيل (84)، سوداء طويلة الذيل (84). جين الأسود B سائد على الأبيض b، وجين الذيل الطويل G سائد على القصير g.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للقصير. الذكر الأبيض القصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط. الأنثى السوداء الطويلة أنجبت أبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` ، فتحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` ؛\nلذا هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`.\nالأكثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أبيض قصير يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` ؛\nفترتيب الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` ، والغاميتان الأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` ناتجتان بالعبور.\nإذن الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` ، والذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg/bg</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>`.\nغاميتات الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` ، تتحد كلها مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` الأب، فتنتج الفئات الأربع الواردة.\n:::\n\n:::exam-question\nid: bio-q-p099-q61-2\ntitle: صفحة 99، السؤال 61، الفرع 2\nquestion: اكتب الطرز الجينية للأفراد الناتجة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 99\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الثدييات صفتا لون الجسم وطول الذيل مرتبطتان محمولتان على نفس الكروموسوم. تزاوجت أنثى سوداء اللون طويلة الذيل مع ذكر أبيض اللون قصير الذيل فكان الناتج: سوداء قصيرة الذيل (16)، بيضاء طويلة الذيل (16)، بيضاء قصيرة الذيل (84)، سوداء طويلة الذيل (84). جين الأسود B سائد على الأبيض b، وجين الذيل الطويل G سائد على القصير g.\n\nاكتب الطرز الجينية للأفراد الناتجة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للقصير. الذكر الأبيض القصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط. الأنثى السوداء الطويلة أنجبت أبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` ، فتحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` ؛\nلذا هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`.\nالأكثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أبيض قصير يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` ؛\nفترتيب الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` ، والغاميتان الأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` ناتجتان بالعبور.\nنضيف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` الأب إلى غاميت الأم في كل فئة:\n\n| غاميت الأم | الفرد الناتج | المظهر والعدد |\n|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bbgg</mtext></math>` | أسود قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbGg</mtext></math>` | أبيض طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` | أبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` | أسود طويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` |\n\nهذه طرز أفراد ثنائية المجموعة، وليست غاميتات.\n:::\n\n:::exam-question\nid: bio-q-p099-q61-3\ntitle: صفحة 99، السؤال 61، الفرع 3\nquestion: حدد الأفراد الناتجة التي تحمل تراكيب جينية جديدة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 99\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الثدييات صفتا لون الجسم وطول الذيل مرتبطتان محمولتان على نفس الكروموسوم. تزاوجت أنثى سوداء اللون طويلة الذيل مع ذكر أبيض اللون قصير الذيل فكان الناتج: سوداء قصيرة الذيل (16)، بيضاء طويلة الذيل (16)، بيضاء قصيرة الذيل (84)، سوداء طويلة الذيل (84). جين الأسود B سائد على الأبيض b، وجين الذيل الطويل G سائد على القصير g.\n\nحدد الأفراد الناتجة التي تحمل تراكيب جينية جديدة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للقصير. الذكر الأبيض القصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` فقط. الأنثى السوداء الطويلة أنجبت أبيض قصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` ، فتحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` ؛\nلذا هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`.\nالأكثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` أبيض قصير يكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` ؛\nفترتيب الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` ، والغاميتان الأقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` ناتجتان بالعبور.\nالمؤتلفون هم أفراد الفئتين القليلتين: سوداء قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg×bg</mtext></math>` ، وبيضاء طويلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG×bg</mtext></math>`.\nالمجموع الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16+16=32</mtext></math>` ؛\nمجموع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16+16+84+84=200</mtext></math>` ؛\nنسبتهم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(32÷200)×100=16%</mtext></math>`. أما الفئتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>84</mtext></math>` فهما أبويتان.\n:::\n\n:::exam-question\nid: bio-q-p100-q62-1\ntitle: صفحة 100، السؤال 62، الفرع 1\nquestion: ما نسبة حدوث عبور بين الجينين A وB؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس الخريطة الجينية المرفقة ثم أجب عن الأسئلة المتعلقة بها:\n\nما نسبة حدوث عبور بين الجينين A وB؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nsolution:\nكل وحدة خريطة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تكرار تراكيب جديدة في نموذج المنهج.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nالمسافة المباشرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B</mtext></math>` في الرسم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` وحدات؛\nلذلك نسبة العبور بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q62-2\ntitle: صفحة 100، السؤال 62، الفرع 2\nquestion: ما نسبة الارتباط بين الجينين A وC؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس الخريطة الجينية المرفقة ثم أجب عن الأسئلة المتعلقة بها:\n\nما نسبة الارتباط بين الجينين A وC؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nsolution:\nالعبور يقابل المسافة بوحدة الخريطة، والارتباط نسبة التراكيب الأبوية المكملة إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nالمسار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` يمر عبر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B:</mtext></math>` المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=3+6=9</mtext></math>` وحدات؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9%</mtext></math>`.\nالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–C=100%−9%=91%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q62-3\ntitle: صفحة 100، السؤال 62، الفرع 3\nquestion: ما نسبة تكرار التراكيب الجينية الجديدة بين الجينين B وC؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس الخريطة الجينية المرفقة ثم أجب عن الأسئلة المتعلقة بها:\n\nما نسبة تكرار التراكيب الجينية الجديدة بين الجينين B وC؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nsolution:\nنسبة التراكيب الجينية الجديدة هي نسبة المؤتلفات، وتقابل عدد وحدات الخريطة.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–C</mtext></math>` مباشرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6</mtext></math>` وحدات، إذن نسبة الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6%</mtext></math>`. لا نأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>94%</mtext></math>` لأنها نسبة الارتباط المكملة، وليست الجديد المطلوب.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q62-4\ntitle: صفحة 100، السؤال 62، الفرع 4\nquestion: ما أقل نسبة ارتباط في الخريطة المعطاة، وما قيمتها؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس الخريطة الجينية المرفقة ثم أجب عن الأسئلة المتعلقة بها:\n\nما أقل نسبة ارتباط في الخريطة المعطاة، وما قيمتها؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nsolution:\nكلما زادت المسافة زادت نسبة الجديد وانخفضت نسبة الارتباط في هذا النموذج.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/409b3c15fe0e542d38f5.webp)\nأبعد زوج هو الطرفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>`. المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–E=3+6+4=13</mtext></math>` وحدة، إذن العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>13%</mtext></math>`.\nأقل نسبة ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−13%=87%</mtext></math>` بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q63-1\ntitle: صفحة 100، السؤال 63، الفرع 1\nquestion: احسب نسبة تكرار العبور بين B وD.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | A | B | C | D |\n|---|---|---|---|---|\n| A | — | 6 | 1 | 4 |\n| B | 6 | — | 7 | 2 |\n| C | 1 | 7 | — | 5 |\n| D | 4 | 2 | 5 | — |\n\nاحسب نسبة تكرار العبور بين B وD.\nsolution:\nالسنتيمورغان الواحد يقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` تكرار عبور في نموذج هذه المسائل. نقرأ صف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` وعمود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` في الجدول فنجد المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` سنتيمورغان.\nإذن نسبة العبور بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` تساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2%</mtext></math>` ؛\nلا نضيف مسافات أخرى لأن البعد المباشر معطى.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q63-2\ntitle: صفحة 100، السؤال 63، الفرع 2\nquestion: احسب نسبة الارتباط بين A وC.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | A | B | C | D |\n|---|---|---|---|---|\n| A | — | 6 | 1 | 4 |\n| B | 6 | — | 7 | 2 |\n| C | 1 | 7 | — | 5 |\n| D | 4 | 2 | 5 | — |\n\nاحسب نسبة الارتباط بين A وC.\nsolution:\nالجدول يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–C=1</mtext></math>` سنتيمورغان؛\nكل وحدة تقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` جديد. إذن العبور بينهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>`.\nالارتباط نسبة التراكيب الأبوية الباقية : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%−1%=99%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q63-3\ntitle: صفحة 100، السؤال 63، الفرع 3\nquestion: ارسم خارطة جينية تبين مواقع الجينات الأربعة على طول الكروموسوم.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | A | B | C | D |\n|---|---|---|---|---|\n| A | — | 6 | 1 | 4 |\n| B | 6 | — | 7 | 2 |\n| C | 1 | 7 | — | 5 |\n| D | 4 | 2 | 5 | — |\n\nارسم خارطة جينية تبين مواقع الجينات الأربعة على طول الكروموسوم.\nsolution:\nالمسافات تجمع على خط الكروموسوم؛\nنضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–A=1</mtext></math>`. ولأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=5</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D=4</mtext></math>` نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>`. ولأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D–B=2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–B=7</mtext></math>` نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` |\n|---|---|---|---|---|\n| الموقع | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/e5376834a1eb485b54cb.webp)\nالمسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ؛\nوتحقق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=4+2=6</mtext></math>` وبقية الجدول.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::mcq\nid: bio-q-p102-q4\ntitle: صفحة 102، السؤال 4\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 102\nquestion: ما الجينان اللذان يكون بينهما أقل نسبة ارتباط في الخريطة الجينية المجاورة؟\n- [x] option-1 | (A، G)\n- [ ] option-2 | (R، G)\n- [ ] option-3 | (C، B)\n- [ ] option-4 | (C، R)\nexplanation:\nنسبة الارتباط مكملة للعبور؛\nلذا أقل ارتباط يكون لأبعد جينين.\n![الخريطة الأصلية](assets/lessons/curriculum-evidence/6d2908f5ff38141d8ac0.webp)\nفي الشكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=10</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–C=18</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–R=6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R–G=14</mtext></math>`. المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–G=10+18+6+14=48</mtext></math>` ؛\nبينما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R–G=14</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–B=18</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–R=6</mtext></math>`.\nأبعد زوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` ، فلهما أقل ارتباط، ومقداره وفق النموذج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100−48=52%</mtext></math>`. الاختيار الأول.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/6d2908f5ff38141d8ac0.webp)\n:::\n\n:::mcq\nid: bio-q-p103-q10\ntitle: صفحة 103، السؤال 10\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 103\nquestion: إذا كانت نسبة تكرار التراكيب الجينية الجديدة بين الجينين A وB (10%)، فكم تكون المسافة التي تفصل الجينين عن بعضهما على الكروموسوم بوحدة سنتيمورغان؟\n- [ ] option-1 | 5\n- [x] option-2 | 10\n- [ ] option-3 | 90\n- [ ] option-4 | 95\nexplanation:\nكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` من التراكيب الجينية الجديدة يقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` سنتيمورغان في الخريطة المدرسية.\nالمعطى الجديد بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` يساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10%</mtext></math>` ؛\nالمسافة إذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` سنتيمورغان، الاختيار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>`. لا نأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>90</mtext></math>` لأنها نسبة الأبويين المكملة.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p103-q12\ntitle: صفحة 103، السؤال 12\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 103\nquestion: ما عدد الأفراد الكلي في أحد التزاوجات إذا كان عدد الأفراد ذوي التراكيب الجينية الجديدة الناتجة (81 فرداً)، وكانت نسبة ظهورهم (9%)؟\n- [ ] option-1 | 819\n- [ ] option-2 | 891\n- [x] option-3 | 900\n- [ ] option-4 | 918\nexplanation:\nنسبة الجديد تساوي عدد المؤتلفين مقسوماً على العدد الكلي ثم مضروباً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100</mtext></math>`. نرمز للعدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>N</mtext></math>`.\nالمعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>81</mtext></math>` مؤتلفاً تمثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9%</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9/100=0.09</mtext></math>` من النسل.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>81/N=9/100</mtext></math>` ؛\nإذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>9N=8100</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>N=8100÷9=900</mtext></math>` فرد.\nالتحقق : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>81÷900=0.09=9%</mtext></math>` ، فالاختيار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>900</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p103-q13\ntitle: صفحة 103، السؤال 13\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 103\nquestion: كم عدد أنواع الغاميتات الناتجة من الطراز الجيني المجاور على فرض عدم حدوث عبور؟\n- [ ] option-1 | 2\n- [x] option-2 | 4\n- [ ] option-3 | 6\n- [ ] option-4 | 8\nexplanation:\nالغاميت يحمل أليلاً واحداً من كل جين. دون عبور نعد كل زوج مرتبط كوحدة واحدة، ثم نضرب في عدد اختيارات الجينات المستقلة.\n![الطراز الأصلي](assets/lessons/curriculum-evidence/260d078ec5d94171371e.webp)\nالصورة تبين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` مستقلاً عن الزوج المرتبط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB/ab</mtext></math>`. يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` اختيارين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` ، ويعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB/ab</mtext></math>` اختيارين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ab</mtext></math>`.\nالغاميتات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TAB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tab</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tAB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tab</mtext></math>` ؛\nالعدد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2×2=4</mtext></math>` ، الاختيار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>`.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/260d078ec5d94171371e.webp)\n:::\n\n:::exam-question\nid: bio-q-p109-q20-1\ntitle: صفحة 109، السؤال 20، الفرع 1\nquestion: اكتب الطراز الجيني لكل من الذكر والأنثى.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى تجارب مورغان على ذبابة الفاكهة أجري تلقيح بين ذكر وأنثى كلاهما رمادي اللون طبيعي الأجنحة غير متماثلي الجينات، فكانت ثلاثة أرباع النسل الناتج رمادية اللون طبيعية الأجنحة. باستخدام الرموز المناسبة أجب:\n\nاكتب الطراز الجيني لكل من الذكر والأنثى.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للأجنحة الطبيعية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامرة. الأبوان غير متماثلين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`. ظهور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>` رمادي طبيعي مع بقاء الصفتين معاً يلائم ارتباطاً تاماً في الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` لدى كليهما.\nكل أب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` مناصفة دون عبور؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BBGG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>`.\nإذن الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` ، وكلاهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`. هذا ترتيب الارتباط الذي يفسر انتقال الصفات معاً بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` في نموذج المسألة.\n:::\n\n:::exam-question\nid: bio-q-p109-q20-2\ntitle: صفحة 109، السؤال 20، الفرع 2\nquestion: اكتب الطرز الجينية المحتملة لأفراد الجيل الأول.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى تجارب مورغان على ذبابة الفاكهة أجري تلقيح بين ذكر وأنثى كلاهما رمادي اللون طبيعي الأجنحة غير متماثلي الجينات، فكانت ثلاثة أرباع النسل الناتج رمادية اللون طبيعية الأجنحة. باستخدام الرموز المناسبة أجب:\n\nاكتب الطرز الجينية المحتملة لأفراد الجيل الأول.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للأجنحة الطبيعية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامرة. الأبوان غير متماثلين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`. ظهور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>` رمادي طبيعي مع بقاء الصفتين معاً يلائم ارتباطاً تاماً في الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` لدى كليهما.\nكل أب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` مناصفة دون عبور؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BBGG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>`.\nالطرز الجينية المحتملة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BBGG</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2/4=1/2</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>` بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالنسبة الجينية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ؛\nوالمظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` رمادي طبيعي : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` أسود ضامر لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` يسودان في التراكيب الأولى.\n:::\n\n:::exam-question\nid: bio-q-p109-q20-3\ntitle: صفحة 109، السؤال 20، الفرع 3\nquestion: ما نمط الوراثة للصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى تجارب مورغان على ذبابة الفاكهة أجري تلقيح بين ذكر وأنثى كلاهما رمادي اللون طبيعي الأجنحة غير متماثلي الجينات، فكانت ثلاثة أرباع النسل الناتج رمادية اللون طبيعية الأجنحة. باستخدام الرموز المناسبة أجب:\n\nما نمط الوراثة للصفتين؟\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرمادي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأسود، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>G</mtext></math>` للأجنحة الطبيعية السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>g</mtext></math>` للضامرة. الأبوان غير متماثلين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>`. ظهور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>` رمادي طبيعي مع بقاء الصفتين معاً يلائم ارتباطاً تاماً في الطور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG/bg</mtext></math>` لدى كليهما.\nكل أب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` مناصفة دون عبور؛\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BBGG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbGg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbgg</mtext></math>`.\nإذن نمط الوراثة ارتباط تام دون عبور: تنتقل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` كوحدتين، بدلاً من إنتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bg</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bG</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bg</mtext></math>` بالتوزيع المستقل.\nلذلك يظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3/4</mtext></math>` بالمظهرين السائدين و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` بالمظهرين المتنحيين، ولا تنتج في هذا النموذج الفئتان المختلطتان.\n:::\n\n:::exam-question\nid: bio-q-p109-q21\ntitle: صفحة 109، السؤال 21\nquestion: أسماك (أورندا) الذهبية من أكثر أسماك الزينة اقتناء في المنازل. أجري تزاوج بين أسماك أورندا التي تمتلك زعانف مفتوحة وذيلاً مروحياً مع أسماك لها نفس الطرز الشكلية، فنتجت 290 سمكة زعانفها مفتوحة وذيلها مروحي، و98 سمكة زعانفها مغلقة وذيلها سيفي. استخدم T للذيل المروحي وt للسيفي وR للزعنفة المفتوحة وr للمغلقة. فسر النتائج على أسس وراثية مبيناً نوع الوراثة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأسماك (أورندا) الذهبية من أكثر أسماك الزينة اقتناء في المنازل. أجري تزاوج بين أسماك أورندا التي تمتلك زعانف مفتوحة وذيلاً مروحياً مع أسماك لها نفس الطرز الشكلية، فنتجت 290 سمكة زعانفها مفتوحة وذيلها مروحي، و98 سمكة زعانفها مغلقة وذيلها سيفي. استخدم T للذيل المروحي وt للسيفي وR للزعنفة المفتوحة وr للمغلقة. فسر النتائج على أسس وراثية مبيناً نوع الوراثة.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للزعنفة المفتوحة السائدة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمغلقة، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للذيل المروحي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للسيفي. ظهور المتنحي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrtt</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` في كلا الأبوين ذوي المظهر السائد، فيكونان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrTt</mtext></math>`.\nالأعداد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>290:98</mtext></math>` تقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` ، وغياب المفتوح السيفي والمغلق المروحي يوافق الارتباط التام `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RT/rt</mtext></math>` دون عبور ظاهر.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RT/rt × RT/rt</mtext></math>` ؛\nغاميتات كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rt</mtext></math>`.\nالنواتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RRTT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrTt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RrTt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>rrtt:</mtext></math>` ثلاثة مفتوحة الزعانف مروحية الذيل مقابل واحدة مغلقة الزعانف سيفية الذيل.\nإذن نوع الوراثة ارتباط دون عبور في تفسير النسبة المعطاة، مع سيادة تامة داخل كل جين.\n:::\n\n:::exam-question\nid: bio-q-p109-q22-1\ntitle: صفحة 109، السؤال 22، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من عمى الألوان ونزف الدم، من فتاة سليمة من المرضين والدها مصاب بالمرضين، فأنجبا أربعة ذكور: الأول سليم من المرضين؛ الثاني مصاب بالمرضين؛ الثالث سليم من عمى الألوان ومصاب بنزف الدم؛ الرابع مصاب بعمى الألوان وسليم من نزف الدم. b لجين الإصابة بعمى الألوان وh لجين الإصابة بنزف الدم.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\nالمرضان متنحيان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرؤية الطبيعية و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لعمى الألوان، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للسلامة من نزف الدم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للإصابة. نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` لأليلين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` نفسه.\nالأب سليم من كليهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]Y</mtext></math>`. الفتاة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]</mtext></math>` من أبيها المصاب بالمرضين؛\nولأنها سليمة من كليهما تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` الآخر، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]X[bh]</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]Y</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]X[bh]</mtext></math>`. الغاميتان الأبويتان عند الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]</mtext></math>` ؛\nوالعبور يفسر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Bh]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bH]</mtext></math>` اللذين يحتاجهما الابنان الثالث والرابع.\n:::\n\n:::exam-question\nid: bio-q-p109-q22-2\ntitle: صفحة 109، السؤال 22، الفرع 2\nquestion: اكتب الطرز الجينية للأبناء الذكور.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من عمى الألوان ونزف الدم، من فتاة سليمة من المرضين والدها مصاب بالمرضين، فأنجبا أربعة ذكور: الأول سليم من المرضين؛ الثاني مصاب بالمرضين؛ الثالث سليم من عمى الألوان ومصاب بنزف الدم؛ الرابع مصاب بعمى الألوان وسليم من نزف الدم. b لجين الإصابة بعمى الألوان وh لجين الإصابة بنزف الدم.\n\nاكتب الطرز الجينية للأبناء الذكور.\nsolution:\nالمرضان متنحيان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرؤية الطبيعية و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لعمى الألوان، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للسلامة من نزف الدم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للإصابة. نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` لأليلين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` نفسه.\nالأب سليم من كليهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]Y</mtext></math>`. الفتاة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]</mtext></math>` من أبيها المصاب بالمرضين؛\nولأنها سليمة من كليهما تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` الآخر، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]X[bh]</mtext></math>`.\nكل ابن ذكر يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب، فتحدد صفاته نسخة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` الأم.\nالأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]Y</mtext></math>` سليم من المرضين؛\nالثاني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]Y</mtext></math>` مصاب بهما؛\nالثالث `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Bh]Y</mtext></math>` سليم من عمى الألوان ومصاب بنزف الدم؛\nالرابع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bH]Y</mtext></math>` مصاب بعمى الألوان وسليم من نزف الدم.\nوجود الحالات الأربع لا يعني أن احتمالاتها متساوية؛\nلا توجد نسبة عبور معطاة.\n:::\n\n:::exam-question\nid: bio-q-p109-q22-3\ntitle: صفحة 109، السؤال 22، الفرع 3\nquestion: ما نوع الوراثة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل سليم من عمى الألوان ونزف الدم، من فتاة سليمة من المرضين والدها مصاب بالمرضين، فأنجبا أربعة ذكور: الأول سليم من المرضين؛ الثاني مصاب بالمرضين؛ الثالث سليم من عمى الألوان ومصاب بنزف الدم؛ الرابع مصاب بعمى الألوان وسليم من نزف الدم. b لجين الإصابة بعمى الألوان وh لجين الإصابة بنزف الدم.\n\nما نوع الوراثة؟\nsolution:\nالمرضان متنحيان على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للرؤية الطبيعية و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لعمى الألوان، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للسلامة من نزف الدم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` للإصابة. نكتب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` لأليلين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` نفسه.\nالأب سليم من كليهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]Y</mtext></math>`. الفتاة أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]</mtext></math>` من أبيها المصاب بالمرضين؛\nولأنها سليمة من كليهما تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` الآخر، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]X[bh]</mtext></math>`.\nصفتان متنحيتان مرتبطتان بالجنس على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، مع ارتباط جيني وعبور لدى الأم.\nدون عبور تمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[BH]</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bh]</mtext></math>` فقط. تبادل قطع بين كروماتيدين غير شقيقين في الانقسام المنصف ولّد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[Bh]</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X[bH]</mtext></math>` ، فظهر ابنان يحمل كل منهما مرضاً واحداً. هذا دليل إعادة تركيب وليس تغيراً في علاقة السيادة.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p110-q23-1\ntitle: صفحة 110، السؤال 23، الفرع 1\nquestion: ما عدد أنواع الغاميتات المحتمل تكوينها إذا حدث عبور؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الشكل الطراز الجيني لفرد ذكر. ندرس أنواع الغاميتات الممكنة التي ينتجها هذا الفرد عبر انقسامات منصفة متعددة، وليس نواتج انقسام خلية واحدة.\n\nما عدد أنواع الغاميتات المحتمل تكوينها إذا حدث عبور؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/ac96d91bcd869ab169f7.webp)\n\nsolution:\nالعدد المطلوب هو أنواع الغاميتات الممكنة للفرد عبر انقسامات مختلفة؛\nالغاميت يحمل أليلاً واحداً من كل جين.\n![الطراز الأصلي](assets/lessons/curriculum-evidence/ac96d91bcd869ab169f7.webp)\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` متماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AA</mtext></math>` فيعطي اختياراً واحداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` غير متماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` فيعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>`. الجينان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` مرتبطان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>` ؛\nبالعبور يمكن أن يعطيا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tR</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` اختيارات.\nالعدد المحتمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1×2×4=8</mtext></math>` أنواع.\nلكن لفظ «خلية» لا يتيح أن تنتج الخلية الواحدة ثمانية غاميتات؛\nالانقسام المنصف لخلية واحدة ينتج أربعة غاميتات فقط. لذلك `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8</mtext></math>` عدد الأنواع الممكنة على مستوى الفرد، وفق النطاق المحدد في السؤال.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q23-2\ntitle: صفحة 110، السؤال 23، الفرع 2\nquestion: اكتب الطرز الجينية للغاميتات المحتمل تكوينها إذا لم يحدث عبور.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الشكل الطراز الجيني لفرد ذكر. ندرس أنواع الغاميتات الممكنة التي ينتجها هذا الفرد عبر انقسامات منصفة متعددة، وليس نواتج انقسام خلية واحدة.\n\nاكتب الطرز الجينية للغاميتات المحتمل تكوينها إذا لم يحدث عبور.\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/ac96d91bcd869ab169f7.webp)\n\nsolution:\nالغاميت يحمل أليلاً واحداً لكل جين، ودون عبور تبقى تركيبات الجينين المرتبطين كما هي.\n![الطراز الأصلي](assets/lessons/curriculum-evidence/ac96d91bcd869ab169f7.webp)\nالصورة تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AA Bb</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR/tr</mtext></math>`. من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AA</mtext></math>` نأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` دائماً، ومن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` نأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` ، ومن الزوج المرتبط نأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tr</mtext></math>` فقط.\nالتركيبات الممكنة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABTR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABtr</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AbTR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Abtr</mtext></math>` ؛\nعددها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1×2×2=4</mtext></math>`. هذه الأنواع الممكنة عبر انقسامات، ولا يلزم أن تجتمع الأربعة في انقسام خلية واحدة.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q24-a\ntitle: صفحة 110، السؤال 24، الفرع a\nquestion: حدد الدور الذي تقوم به الخرائط الجينية.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nحدد الدور الذي تقوم به الخرائط الجينية.\nsolution:\n**الإجابة:** تبين الخرائط الجينية ترتيباً خطياً افتراضياً لمواقع الجينات على الكروموسوم، وتقدّر المسافات بينها من نسب التراكيب الجديدة الناتجة بالعبور.\n\n**الشاهد من الكتاب:**\n\n> التي تمثل ترتيباً خطياً افتراضياً لمواقع الجينات على طول كروموسوم معين\n\n**المصدر:** صفحة 66 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p110-q24-b1\ntitle: صفحة 110، السؤال 24، الفرع b1\nquestion: ما نسبة تكرار العبور بين الجينين M وE؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | H | E | M | P |\n|---|---|---|---|---|\n| H | — | 6 | 1 | 4 |\n| E | 6 | — | 7 | 2 |\n| M | 1 | 7 | — | 5 |\n| P | 4 | 2 | 5 | — |\n\nما نسبة تكرار العبور بين الجينين M وE؟\nsolution:\nكل سنتيمورغان يقابل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` من التراكيب الجديدة في نموذج المنهج.\nنقرأ صف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` وعمود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E:</mtext></math>` المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` سنتيمورغان، فتكون نسبة تكرار العبور بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` تساوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q24-b2\ntitle: صفحة 110، السؤال 24، الفرع b2\nquestion: ما نسبة الارتباط بين الجينين P وH؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | H | E | M | P |\n|---|---|---|---|---|\n| H | — | 6 | 1 | 4 |\n| E | 6 | — | 7 | 2 |\n| M | 1 | 7 | — | 5 |\n| P | 4 | 2 | 5 | — |\n\nما نسبة الارتباط بين الجينين P وH؟\nsolution:\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>P–H</mtext></math>` في الجدول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` سنتيمورغان، أي تكرار عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4%</mtext></math>`. نسبة الارتباط هي نسبة الأبويين المكملة إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>P–H=100%−4%=96%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q24-b3\ntitle: صفحة 110، السؤال 24، الفرع b3\nquestion: ما نسبة تكرار التراكيب الجينية الجديدة بين الجينين H وE؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | H | E | M | P |\n|---|---|---|---|---|\n| H | — | 6 | 1 | 4 |\n| E | 6 | — | 7 | 2 |\n| M | 1 | 7 | — | 5 |\n| P | 4 | 2 | 5 | — |\n\nما نسبة تكرار التراكيب الجينية الجديدة بين الجينين H وE؟\nsolution:\nالتراكيب الجديدة هي المؤتلفات الناتجة بالعبور؛\nتقابل نسبتها عدد وحدات الخريطة.\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–E=6</mtext></math>` سنتيمورغان من الجدول، فتكرار التراكيب الجديدة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6%</mtext></math>`. لا نطرح من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100</mtext></math>` لأن المطلوب الجديد نفسه.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q24-b4\ntitle: صفحة 110، السؤال 24، الفرع b4\nquestion: ارسم خريطة جينية تبين مواقع الجينات الأربعة على طول الكروموسوم.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول المسافات بين أربعة جينات على طول كروموسوم معين بوحدة السنتيمورغان:\n\n| الجين | H | E | M | P |\n|---|---|---|---|---|\n| H | — | 6 | 1 | 4 |\n| E | 6 | — | 7 | 2 |\n| M | 1 | 7 | — | 5 |\n| P | 4 | 2 | 5 | — |\n\nارسم خريطة جينية تبين مواقع الجينات الأربعة على طول الكروموسوم.\nsolution:\nنرتب الجينات على خط بحيث توافق كل المسافات. نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M–H=1</mtext></math>`. نضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>P</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` ؛\nفيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–P=4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M–P=5</mtext></math>`. ثم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` ؛\nفيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>P–E=2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H–E=6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M–E=7</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>P</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` |\n|---|---|---|---|---|\n| الموقع | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>5</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>7</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/bbb611a45283601db084.webp)\nالمسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، وعكس الرسم يمثل الترتيب نفسه.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q25-1\ntitle: صفحة 110، السؤال 25، الفرع 1\nquestion: ما نسبة ارتباط كل من الجينات (EB)، (AD)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسب ارتباط وعبور خمسة جينات محمولة على نفس الكروموسوم:\n\n| الجينات | نسبة العبور | الجينات | نسبة الارتباط |\n|---|---|---|---|\n| AB | 16% | AC | 94% |\n| EB | 2% | BC | 90% |\n| CD | 6% | EC | 88% |\n| AD | 12% | AE | 82% |\n\nما نسبة ارتباط كل من الجينات (EB)، (AD)؟\nsolution:\nنسبة الارتباط تمثل التراكيب الأبوية، ونسبة العبور تمثل الجديد؛\nمجموعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nللزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–B</mtext></math>` العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2%</mtext></math>` ، فالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−2%=98%</mtext></math>`.\nللزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D</mtext></math>` العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12%</mtext></math>` ، فالارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−12%=88%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q25-2\ntitle: صفحة 110، السؤال 25، الفرع 2\nquestion: ما نسبة العبور بين كل من الجينات (EC)، (AE)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسب ارتباط وعبور خمسة جينات محمولة على نفس الكروموسوم:\n\n| الجينات | نسبة العبور | الجينات | نسبة الارتباط |\n|---|---|---|---|\n| AB | 16% | AC | 94% |\n| EB | 2% | BC | 90% |\n| CD | 6% | EC | 88% |\n| AD | 12% | AE | 82% |\n\nما نسبة العبور بين كل من الجينات (EC)، (AE)؟\nsolution:\nنسبة العبور هي الجزء المتبقي بعد التراكيب الأبوية «نسبة الارتباط».\nللزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–C</mtext></math>` ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>88%</mtext></math>` ؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−88%=12%</mtext></math>`.\nللزوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–E</mtext></math>` ارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>82%</mtext></math>` ؛\nالعبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=100%−82%=18%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q25-3\ntitle: صفحة 110، السؤال 25، الفرع 3\nquestion: ارسم خريطة جينية تبين مواقع الجينات الخمسة على طول الكروموسوم.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسب ارتباط وعبور خمسة جينات محمولة على نفس الكروموسوم:\n\n| الجينات | نسبة العبور | الجينات | نسبة الارتباط |\n|---|---|---|---|\n| AB | 16% | AC | 94% |\n| EB | 2% | BC | 90% |\n| CD | 6% | EC | 88% |\n| AD | 12% | AE | 82% |\n\nارسم خريطة جينية تبين مواقع الجينات الخمسة على طول الكروموسوم.\nsolution:\nنحول الارتباط إلى مسافة باستعمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100−</mtext></math>` الارتباط، وكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1%</mtext></math>` عبور يقابل وحدة خريطة.\nالمسافات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–C=6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–C=10</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–C=12</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–E=18</mtext></math>` ؛\nو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–B=16</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–B=2</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C–D=6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A–D=12</mtext></math>`.\nنضع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` ، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` عند `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>`.\n\n| الجين | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` |\n|---|---|---|---|---|---|\n| الموقع | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>16</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` |\n\n![الخريطة الأصلية في الإجابات](assets/lessons/curriculum-evidence/9c9ba55603cc7ebdc000.webp)\nالمسافات المتتالية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>6</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ؛\nتحقق جميع أزواج الجدول، ومنها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B–C=16−6=10</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–C=18−6=12</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p110-q26-2\ntitle: صفحة 110، السؤال 26، الفرع 2\nquestion: ما نسبة الارتباط بين الجينين (F، E)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 110\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول نسبة الارتباط ونسبة تكرار العبور والمسافة بين أربع جينات:\n\n| الجينات | نسبة الارتباط | نسبة العبور | المسافة/وحدة خريطة |\n|---|---|---|---|\n| E، H | — | 13% | — |\n| M، H | 95% | — | — |\n| E، F | — | — | 3 |\n| F، M | — | 15% | — |\n| F، H | 90% | — | — |\n\nما نسبة الارتباط بين الجينين (F، E)؟\nsolution:\nالمسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E–F=3</mtext></math>` وحدات خريطة في الجدول، أي عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3%</mtext></math>`. الارتباط هو الباقي الأبوي إلى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\nنسبة الارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>F–E=100%−3%=97%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p117-q3b-1\ntitle: صفحة 117، السؤال 3b، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين ولغاميتاتها للصفتين معاً محدداً نسبة ظهور كل غاميت.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 117\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت الأفراد الناتجة:179 سوداء طويلة الذيل؛181 بيضاء قصيرة الذيل؛21 بيضاء طويلة الذيل؛19 سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nاكتب الطرز الجينية للأبوين ولغاميتاتها للصفتين معاً محدداً نسبة ظهور كل غاميت.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأنثى البيضاء القصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط. وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` في النسل يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` عند الذكر الأسود الطويل، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbTt</mtext></math>`.\nالفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>181</mtext></math>` أبيض قصير تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين؛\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>`. المؤتلفتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` أبيض طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>19</mtext></math>` أسود قصير تكشفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>`.\nالمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179+181+21+19=400</mtext></math>` ؛\nنسبة العبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(21+19)÷400×100=10%</mtext></math>`.\nنقدّر مجموع الفئتين الأبويتين بعد طرح العبور:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100−10=90%</mtext></math>`\nنقدّر نسبة كل غاميت أبوي بافتراض تساويهما:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>90÷2=45%</mtext></math>`\nونسبة كل غاميت مؤتلف:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10÷2=5%</mtext></math>`\n\nأما النسب المشاهدة فعلياً في العينة فهي:\n\n| الغاميت | حساب نسبته من العدد المشاهد |\n|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(179÷400)×100=44.75%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(181÷400)×100=45.25%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(21÷400)×100=5.25%</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(19÷400)×100=4.75%</mtext></math>` |\n\nالفروق الصغيرة عن 45% و5% تنتج من أخذ عينة. غاميت الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` وحده بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p117-q3b-2\ntitle: صفحة 117، السؤال 3b، الفرع 2\nquestion: ما نسبة الارتباط بين جينات الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 117\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت الأفراد الناتجة:179 سوداء طويلة الذيل؛181 بيضاء قصيرة الذيل؛21 بيضاء طويلة الذيل؛19 سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nما نسبة الارتباط بين جينات الصفتين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط؛\nلذا الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>181</mtext></math>` أبيض قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين من أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>`\nوالصغيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` أبيض طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>19</mtext></math>` أسود قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` المؤتلفتين.\nنسبة الارتباط تمثل الأبويين. عدد الأبويين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=179+181=360</mtext></math>`\nومجموع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179+181+21+19=400</mtext></math>`.\nنسبة الارتباط `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(360÷400)×100=90%</mtext></math>`.\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p117-q3b-3\ntitle: صفحة 117، السؤال 3b، الفرع 3\nquestion: ما المسافة بين جيني الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 117\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت الأفراد الناتجة:179 سوداء طويلة الذيل؛181 بيضاء قصيرة الذيل؛21 بيضاء طويلة الذيل؛19 سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nما المسافة بين جيني الصفتين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط؛\nلذا الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>181</mtext></math>` أبيض قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين من أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>`\nوالصغيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` أبيض طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>19</mtext></math>` أسود قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` المؤتلفتين.\nالمسافة تقابل نسبة المؤتلفات. عدد الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=21+19=40</mtext></math>` ؛\nمجموع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=179+181+21+19=400</mtext></math>`.\nنسبة الجديد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(40÷400)×100=10%</mtext></math>`.\nإذن المسافة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>10</mtext></math>` وحدات خريطة «سنتيمورغان».\n\n**المصدر:** صفحة 66 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p117-q3b-4\ntitle: صفحة 117، السؤال 3b، الفرع 4\nquestion: في حال عدم حدوث عبور، ما احتمال إنتاج الطراز الجيني BbTt؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 117\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الحيوانات لون الجسم وطول الذيل صفتان مرتبطتان على نفس الكروموسوم. تزاوج ذكر أسود اللون طويل الذيل مع أنثى بيضاء اللون قصيرة الذيل، فكانت الأفراد الناتجة:179 سوداء طويلة الذيل؛181 بيضاء قصيرة الذيل؛21 بيضاء طويلة الذيل؛19 سوداء قصيرة الذيل. جين الأسود B سائد على الأبيض b، وجين الذيل الطويل T سائد على القصير t.\n\nفي حال عدم حدوث عبور، ما احتمال إنتاج الطراز الجيني BbTt؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأسود السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للأبيض، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط؛\nلذا الفئتان الكبيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>179</mtext></math>` أسود طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>181</mtext></math>` أبيض قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` الأبويتين من أب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT/bt</mtext></math>`\nوالصغيرتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` أبيض طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>19</mtext></math>` أسود قصير تعكسان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bt</mtext></math>` المؤتلفتين.\nفي الفرض المطلوب نلغي العبور، فيعطي الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط، مناصفة. الأم تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt</mtext></math>` فقط.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BT × bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbTt</mtext></math>` ، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bt × bt</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bbtt</mtext></math>` ؛\nاحتمال كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nإذن احتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BbTt</mtext></math>` دون عبور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nلا نستخدم نسب الغاميتات المشاهدة التي تتضمن عبوراً.\n:::\n\n:::mcq\nid: bio-b-p038-q1-5\ntitle: الرزمة التعليمية، صفحة 38، السؤال 1-5\nquestion: ما التركيب الكروموسومي لذكر مصاب بمتلازمة إدواردز؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\n- [ ] option-1 | XXY+44\n- [x] option-2 | XY+45\n- [ ] option-3 | XY+44\n- [ ] option-4 | XY+46\nexplanation:\nمتلازمة إدواردز تعني ثلاث نسخ من الكروموسوم الجسمي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` ، بدلاً من نسختين.\nعدد الكروموسومات الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=44+1=45</mtext></math>` ؛\nالذكر يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>`.\nإذن التركيب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45+XY</mtext></math>` ، ومجموعه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>` ؛\nالاختيار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY+45</mtext></math>`.\n\n**شاهد القاعدة أو السياق من الكتاب:**\n\n> متلازمة داون Down Syndrom؛ متلازمة إدواردز Edwards Syndrom؛ متلازمة تيرنر Turner Syndrom؛ متلازمة كلينفلتر Klinefelter Syndrom؛ X؛ Y؛ XXY؛ XO؛ 21؛ 18.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-6\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-6\nquestion: البويضة المخصبة التي تحتوي على ثلاث نسخ من الكروموسوم رقم(21) إلى أي متلازمة تتطور؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [x] option-1 | داون\n- [ ] option-2 | إدواردز\n- [ ] option-3 | تيرنر\n- [ ] option-4 | أنثى ثلاثية الكروموسوم الجنسي\nexplanation:\n**الإجابة:** داون.\n\n**الشاهد من الكتاب:**\n\n> متلازمة داون Down Syndrom؛ 21.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p040-q1-8\ntitle: الرزمة التعليمية، صفحة 40، السؤال 1-8\nquestion: على أي متلازمة يدل الطراز الجيني (XO)؟\nreference: [الرزمة التعليمية، صفحة PDF 40](https://moe.edu.ps/m/4061#page=40)\n- [x] option-1 | تيرنر\n- [ ] option-2 | كلينفلتر\n- [ ] option-3 | إدواردز\n- [ ] option-4 | داون\nexplanation:\n**الإجابة:** تيرنر.\n\n**الشاهد من الكتاب:**\n\n> متلازمة تيرنر Turner Syndrom؛ XO.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q47\ntitle: تصنيف الأسئلة، السؤال 47، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: ما نوع الطفرة الكروموسومية التي تحدث عند تكرار جزء من الكروموسوم؟\n- [ ] option-1 | أ. طفرة حذف\n- [x] option-2 | ب. طفرة تكرار\n- [ ] option-3 | ج. طفرة انقلاب\n- [ ] option-4 | د. طفرة انتقال\nexplanation:\n**الإجابة:** ب. طفرة تكرار\n\n**الشاهد من الكتاب:**\n\n> حذف: حذف أو فقد جزء من الكروموسوم؛ تكرار: تكرار جزء من الكروموسوم؛ انقلاب: تنفصل قطعة من الكروموسوم وتنقلب180درجة لتتصل بشكل معكوس مع الكروموسوم؛ انتقال: تبادل لقطعتين مختلفتين بين كروموسومين غير متناظرين.\n\n**المصدر:** صفحة 36 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q48\ntitle: تصنيف الأسئلة، السؤال 48، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85 · صياغة تعليمية معدّلة\nkicker: صياغة تعليمية معدّلة\nquestion: ما نوع الطفرة الكروموسومية التي تنفصل فيها قطعة ثم تدور 180 درجة وتعود لتتصل معكوسة الاتجاه في الكروموسوم نفسه؟\n- [ ] option-1 | أ. طفرة حذف\n- [ ] option-2 | ب. طفرة تكرار\n- [x] option-3 | ج. طفرة انقلاب\n- [ ] option-4 | د. طفرة انتقال\nexplanation:\n**الإجابة: طفرة انقلاب.**\n\nيعرض شكل الكتاب الانقلاب بوصفه فصل قطعة وقلب اتجاهها 180 درجة ثم اتصالها في الكروموسوم نفسه.\n\n**المصدر:** صفحة 36 من الكتاب.\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q49\ntitle: تصنيف الأسئلة، السؤال 49، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: أي الطفرات الآتية ينعكس فيها ترتيب الجينات في جزء من الكروموسوم؟\n- [ ] option-1 | أ. طفرة حذف\n- [ ] option-2 | ب. طفرة تكرار\n- [x] option-3 | ج. طفرة انقلاب\n- [ ] option-4 | د. طفرة انتقال\nexplanation:\n**الإجابة:** ج. طفرة انقلاب\n\n**الشاهد من الكتاب:**\n\n> حذف: حذف أو فقد جزء من الكروموسوم؛ تكرار: تكرار جزء من الكروموسوم؛ انقلاب: تنفصل قطعة من الكروموسوم وتنقلب180درجة لتتصل بشكل معكوس مع الكروموسوم؛ انتقال: تبادل لقطعتين مختلفتين بين كروموسومين غير متناظرين.\n\n**المصدر:** صفحة 36 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p085-q50\ntitle: تصنيف الأسئلة، السؤال 50، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: أي الطفرات الكروموسومية التي يمثلها الشكل الآتي؟\n- [ ] option-1 | أ. طفرة حذف\n- [ ] option-2 | ب. طفرة تكرار\n- [x] option-3 | ج. طفرة انقلاب\n- [ ] option-4 | د. طفرة انتقال\nexplanation:\n![الرسم الأصلي](assets/lessons/curriculum-evidence/d310c92fd08563f2aeaf.webp)\nفي الأصل ترتيب الجينات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A B C D E F G H</mtext></math>` ، وبعد التغير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A D C B E F G H</mtext></math>`. القطعة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B C D</mtext></math>` أصبحت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>D C B</mtext></math>` ؛\nلم تُحذف ولم تُكرر، بل انعكس اتجاهها.\nإذن ج، طفرة انقلاب.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/d310c92fd08563f2aeaf.webp)\n:::\n\n:::mcq\nid: bio-q-p085-q51\ntitle: تصنيف الأسئلة، السؤال 51، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: أي الطفرات الكروموسومية التي يمثلها الشكل المقابل؟\n- [ ] option-1 | أ. طفرة حذف\n- [ ] option-2 | ب. طفرة تكرار\n- [ ] option-3 | ج. طفرة انقلاب\n- [x] option-4 | د. طفرة انتقال\nexplanation:\n![الرسم الأصلي](assets/lessons/curriculum-evidence/aaac1c8aa88679b53f65.webp)\nيظهر كروموسومان مختلفان؛\nتنتقل القطعة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A B</mtext></math>` إلى الثاني، وتقابلها القطعة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M N O</mtext></math>` إلى الأول، فيصبح أحدهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M N O C D E F G H</mtext></math>` والآخر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A B P Q R</mtext></math>`.\nهذا تبادل قطع بين كروموسومين غير متناظرين، أي طفرة انتقال، الاختيار د.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/aaac1c8aa88679b53f65.webp)\n:::\n\n:::mcq\nid: bio-q-p085-q52\ntitle: تصنيف الأسئلة، السؤال 52، صفحة 85\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 85\nquestion: كم يبلغ عدد الكروموسومات الجنسية لفرد مصاب بمتلازمة داون؟\n- [ ] option-1 | أ. 1\n- [x] option-2 | ب. 2\n- [ ] option-3 | ج. 3\n- [ ] option-4 | د. 4\nexplanation:\n**الإجابة:** ب. كروموسومان جنسيان؛ الزيادة في داون تخص الكروموسوم الجسمي21.\n\n**الشاهد من الكتاب:**\n\n> متلازمة داون Down Syndrom؛ 21؛ X.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p086-q53\ntitle: تصنيف الأسئلة، السؤال 53، صفحة 86\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nquestion: ما التركيب الكروموسومي الجنسي وعدد الكروموسومات الجسمية لأنثى داون؟\n- [x] option-1 | أ. XX +45\n- [ ] option-2 | ب. XY +45\n- [ ] option-3 | ج. XX +44\n- [ ] option-4 | د. XX +47\nexplanation:\nالأنثى تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>`. في داون توجد نسخة إضافية من الكروموسوم الجسمي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` ؛\nالجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=44+1=45</mtext></math>`.\nإذن الطراز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX+45</mtext></math>` ، ومجموعه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>` ؛\nالاختيار أ. لا تعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>` في هذا المثال عدد الجسمية وحدها.\n\n**شاهد القاعدة أو السياق من الكتاب:**\n\n> متلازمة داون Down Syndrom؛ متلازمة إدواردز Edwards Syndrom؛ متلازمة تيرنر Turner Syndrom؛ متلازمة كلينفلتر Klinefelter Syndrom؛ X؛ Y؛ XXY؛ XO؛ 21؛ 18.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p086-q54\ntitle: تصنيف الأسئلة، السؤال 54، صفحة 86\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nquestion: ما المرض الوراثي الذي ينتج عن طفرة جينية على الكروموسوم رقم12؟\n- [ ] option-1 | أ. حمى البحر الأبيض المتوسط\n- [x] option-2 | ب. فينيل كيتونيوريا\n- [ ] option-3 | ج. هنتنغتون\n- [ ] option-4 | د. إدواردز\nexplanation:\n**الإجابة:** ب. فينيل كيتونيوريا\n\n**الشاهد من الكتاب:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p086-q58\ntitle: تصنيف الأسئلة، السؤال 58، صفحة 86\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nquestion: ما الطراز الكروموسومي للخلية الجسمية لطفل مصاب بمرض فينيل كيتونيوريا؟\n- [ ] option-1 | أ. XXY +44\n- [x] option-2 | ب. XY +44\n- [ ] option-3 | ج. XY +45\n- [ ] option-4 | د. XXX +44\nexplanation:\nفينيل كيتونيوريا ينتج عن طفرة جينية على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12</mtext></math>` ، ولا يغير عدد الكروموسومات. الطفل الذكر يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` جسميّاً و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` جنسيين.\nإذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XY</mtext></math>` ومجموعه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>46</mtext></math>` ، الاختيار ب. لا نضيف كروموسوماً بسبب وجود مرض جيني.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::mcq\nid: bio-q-p086-q59\ntitle: تصنيف الأسئلة، السؤال 59، صفحة 86\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 86\nquestion: ما عدد الكروموسومات الكلي في خلية جسمية لأنثى مصابة بمرض كرابي؟\n- [ ] option-1 | أ. 44\n- [ ] option-2 | ب. 45\n- [x] option-3 | ج. 46\n- [ ] option-4 | د. 47\nexplanation:\nكرابي ينتج عن طفرة جينية متنحية على الكروموسوم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>14</mtext></math>` ، ولا يسبب زيادة أوفقد كروموسوم.\nالأنثى تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` كروموسوماً جسمياً و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX:44+2=46</mtext></math>`. إذن العدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>46</mtext></math>` ، الاختيار ج.\nhint: راجع المعطيات وحدد المطلوب، ثم قارن الخيارات الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p094-q39-1\ntitle: تصنيف الأسئلة، السؤال 39، الفرع 1، صفحة 94\nquestion: السؤال 39، الفرع 1\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 94\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين طفرة الانقلاب وطفرة الانتقال من حيث المفهوم.\nsolution:\n**الإجابة:** الانقلاب: تنفصل قطعة وتدور180° ثم تعود معكوسة الاتجاه في الكروموسوم. الانتقال: تتبادل قطعتان بين كروموسومين غير متناظرين.\n\n**الشاهد من الكتاب:**\n\n> انقلاب: تنفصل قطعة من الكروموسوم وتنقلب180درجة لتتصل بشكل معكوس مع الكروموسوم؛ انتقال: تبادل لقطعتين مختلفتين بين كروموسومين غير متناظرين.\n\n**المصدر:** صفحة 36 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p096-q45-1\ntitle: صفحة 96، السؤال 45، الفرع 1\nquestion: ما نوع الطفرة الكروموسومية المشار إليها بالرمز (س)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح إحدى الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية، ثم أجب عن الأسئلة التالية:\n\nما نوع الطفرة الكروموسومية المشار إليها بالرمز (س)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nالخلية الأبوية تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` ، لكن المخطط يجعل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ينتقلان معاً إلى غاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` ، ويترك الغاميت(هـ) بلا كروموسوم جنسي.\nإذن(س) عدم انفصال الكروموسومات الجنسية أثناء الانقسام المنصف. لا توجد إشارة إلى تبادل قطع، بل خلل في توزيع العدد.\n:::\n\n:::exam-question\nid: bio-q-p096-q45-2\ntitle: صفحة 96، السؤال 45، الفرع 2\nquestion: ما اسم الاختلال الوراثي في الفرد المشار إليه بالرمز (ص)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح إحدى الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية، ثم أجب عن الأسئلة التالية:\n\nما اسم الاختلال الوراثي في الفرد المشار إليه بالرمز (ص)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nالبويضة الطبيعية تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، والحيوان المنوي في الفرع(ص) يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` بعد عدم الانفصال.\nالإخصاب يجمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X+XY=XXY</mtext></math>` ؛\nوهذا طراز متلازمة كلينفلتر. الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` ، فيكون المجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+3=47</mtext></math>` ، والفردذكر لوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p096-q45-3\ntitle: صفحة 96، السؤال 45، الفرع 3\nquestion: كم عدد الكروموسومات الجسمية في الحيوان المنوي المشار إليه بالرمز (هـ)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح إحدى الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية، ثم أجب عن الأسئلة التالية:\n\nكم عدد الكروموسومات الجسمية في الحيوان المنوي المشار إليه بالرمز (هـ)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nالحيوان المنوي(هـ) خالٍ من كروموسوم جنسي نتيجة عدم انفصال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` إلى الغاميت الآخر؛\nوالخلل المرسوم محصور في الجنسية.\nلذلك يظل نصيبه من الجسمية نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44:44÷2=22</mtext></math>` كروموسوماً جسمياً. مجموع كروموسوماته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>` أيضاً لغياب الجنسية، لكن المطلوب الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p096-q45-4\ntitle: صفحة 96، السؤال 45، الفرع 4\nquestion: ما جنس الفرد الناتج المشار إليه بالرمز (ع)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح إحدى الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية، ثم أجب عن الأسئلة التالية:\n\nما جنس الفرد الناتج المشار إليه بالرمز (ع)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/fd9bfc4059e085f1a4f2.webp)\nالحيوان المنوي(هـ) بلا كروموسوم جنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ؛\nوالبويضة الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`. اتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XO</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحد دون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>`.\nلذلك الفرد(ع) أنثى مصابة بمتلازمة تيرنر، ومجموع كروموسوماتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+1=45</mtext></math>`. الرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` يعني غياب الكروموسوم وليس كروموسوماً إضافياً.\n:::\n\n:::exam-question\nid: bio-q-p100-q64\ntitle: صفحة 100، السؤال 64\nquestion: هناك أنواع مختلفة من الاختلالات الوراثية ناتجة عن حالات عدم الانفصال، وضح ذلك.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nهناك أنواع مختلفة من الاختلالات الوراثية ناتجة عن حالات عدم الانفصال، وضح ذلك.\nsolution:\nعدم الانفصال خلل في توزيع الكروموسومات بالانقسام المنصف. قد يبقى كروموسومان متناظران معاً في الطور الانفصالي الأول، أوتبقى كروماتيدان شقيقان معاً في الطور الانفصالي الثاني.\nينتج غاميت فيه نسختان من كروموسوم معين «`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>n+1</mtext></math>`»، وآخر بلا نسخة منه «`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>n−1</mtext></math>`»، بدلاً من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>n</mtext></math>` الطبيعي. وعند إخصاب غاميت طبيعي قد يصبح الزيجوت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2n+1</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2n−1</mtext></math>`.\nإذا كانت الزيادة في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` تظهر متلازمة داون، وإذا كان التركيب الجنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XXY</mtext></math>` تظهر كلينفلتر، وإذا كان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XO</mtext></math>` تظهر تيرنر. يحدد الكروموسوم المتأثر نوع الاختلال.\n:::\n\n:::exam-question\nid: bio-q-p100-q65\ntitle: صفحة 100، السؤال 65\nquestion: ما أنواع الطفرات الكروموسومية التي تحدث تغييراً في تركيب الكروموسوم؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nما أنواع الطفرات الكروموسومية التي تحدث تغييراً في تركيب الكروموسوم؟\nsolution:\n**الإجابة:** الحذف: فقد جزء من الكروموسوم. التكرار: تكرار جزء منه. الانقلاب: انفصال قطعة وانقلابها 180 درجة ثم اتصالها بشكل معكوس. الانتقال: تبادل قطعتين مختلفتين بين كروموسومين غير متناظرين.\n\n**الشاهد من الكتاب:**\n\n> حذف: حذف أو فقد جزء من الكروموسوم؛ تكرار: تكرار جزء من الكروموسوم؛ انقلاب: تنفصل قطعة من الكروموسوم وتنقلب180درجة لتتصل بشكل معكوس مع الكروموسوم؛ انتقال: تبادل لقطعتين مختلفتين بين كروموسومين غير متناظرين.\n\n**المصدر:** صفحة 36 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q66-a\ntitle: صفحة 100، السؤال 66، الفرع a\nquestion: أ. XXY\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nاذكر اسم الاختلال الوراثي الناجم عن كل طراز كروموسومي جنسي من الآتية:\n\nأ. XXY\nsolution:\n**الإجابة:** متلازمة كلينفلتر.\n\n**الشاهد من الكتاب:**\n\n> متلازمة كلينفلتر Klinefelter Syndrom؛ XXY.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q66-b\ntitle: صفحة 100، السؤال 66، الفرع b\nquestion: ب. XO\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nاذكر اسم الاختلال الوراثي الناجم عن كل طراز كروموسومي جنسي من الآتية:\n\nب. XO\nsolution:\n**الإجابة:** متلازمة تيرنر.\n\n**الشاهد من الكتاب:**\n\n> متلازمة تيرنر Turner Syndrom؛ XO.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q67\ntitle: صفحة 100، السؤال 67\nquestion: قارن بين متلازمة كلينفلتر ومتلازمة داون من حيث الطراز الكروموسومي الجنسي.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين متلازمة كلينفلتر ومتلازمة داون من حيث الطراز الكروموسومي الجنسي.\nsolution:\n**كلينفلتر: XXY.** يظهر في الشكل كروموسومانX وكروموسومY.\n\n**داون: XX للأنثى أوXY للذكر.** الزيادة المسببة لداون في الكروموسوم21، وهو جسمي؛ لذلك لا يحدد داون جنس الفرد. تبقى قاعدةXX للأنثى وXY للذكر كما يشرح درس تحديد الجنس.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n![الشاهد من الكتاب](assets/lessons/curriculum-evidence/5b74e4213dae7691e111.webp)\n\n**المصدر:** صفحة 32 من الكتاب.\n\n:::\n\n:::exam-question\nid: bio-q-p100-q68\ntitle: صفحة 100، السؤال 68\nquestion: ما المقصود بمرض كرابي؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nما المقصود بمرض كرابي؟\nsolution:\n**الإجابة:** مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم 14.\n\n**الشاهد من الكتاب:**\n\n> مرض كرابي Krabbe Disease، مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم14.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q69\ntitle: صفحة 100، السؤال 69\nquestion: قارن بين مرض فينيل كيتونوريا ومرض كرابي وحمى البحر الأبيض المتوسط من حيث رقم الكروموسوم الذي تحدث عليه الطفرة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين مرض فينيل كيتونوريا ومرض كرابي وحمى البحر الأبيض المتوسط من حيث رقم الكروموسوم الذي تحدث عليه الطفرة.\nsolution:\n**الإجابة:** فينيل كيتونوريا: 12؛ كرابي: 14؛ حمى البحر الأبيض المتوسط: 16.\n\n**الشاهد من الكتاب:**\n\n> تغير دائم في تسلسل القواعد النيتروجينية، ومن الأمثلة على الاختلالات الوراثية التي لها علاقة بالطفرات الجينية: مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12. مرض كرابي Krabbe Disease، مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم14. حمى البحر الأبيض المتوسط Familial Mediterranean Fever، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم16.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q70-1\ntitle: صفحة 100، السؤال 70، الفرع 1\nquestion: ما المقصود بالطفرة الجينية؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للاختلالات الوراثية التي لها علاقة بالطفرات الجينية، أجب عما يأتي:\n\nما المقصود بالطفرة الجينية؟\nsolution:\n**الإجابة:** تغير دائم في تسلسل القواعد النيتروجينية لجين معين.\n\n**الشاهد من الكتاب:**\n\n> تغير دائم في تسلسل القواعد النيتروجينية.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p100-q70-2\ntitle: صفحة 100، السؤال 70، الفرع 2\nquestion: اكتب ثلاثة اختلالات لها علاقة بالطفرات الجينية، واذكر رقم الكروموسوم الذي حدثت فيه الطفرة في كل حالة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 100\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للاختلالات الوراثية التي لها علاقة بالطفرات الجينية، أجب عما يأتي:\n\nاكتب ثلاثة اختلالات لها علاقة بالطفرات الجينية، واذكر رقم الكروموسوم الذي حدثت فيه الطفرة في كل حالة.\nsolution:\n**الإجابة:** فينيل كيتونوريا: طفرة جينية متنحية على الكروموسوم 12. كرابي: طفرة جينية متنحية على الكروموسوم 14. حمى البحر الأبيض المتوسط: طفرة جينية متنحية على الكروموسوم 16.\n\n**الشاهد من الكتاب:**\n\n> تغير دائم في تسلسل القواعد النيتروجينية، ومن الأمثلة على الاختلالات الوراثية التي لها علاقة بالطفرات الجينية: مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12. مرض كرابي Krabbe Disease، مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم14. حمى البحر الأبيض المتوسط Familial Mediterranean Fever، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم16.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p101-q71-2\ntitle: صفحة 101، السؤال 71، الفرع 2\nquestion: ما نوع الطفرة الكروموسومية المشار إليها بالرمز (أ)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية ثم أجب عن الأسئلة اللاحقة:\n\nما نوع الطفرة الكروموسومية المشار إليها بالرمز (أ)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nالخلية الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` تعطي في المخطط بويضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` وأخرى بلا كروموسوم جنسي، بدلاً من بويضتين تحمل كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\nهذا خلل عدم انفصال للكروموسومات الجنسية، وهو الطفرة(أ). إذا وقع في الانقسام الأول لا ينفصل المتناظران، وإذا وقع في الثاني لا تنفصل الكروماتيدات الشقيقة؛\nالرسم المختصر لا يحدد الطور.\n:::\n\n:::exam-question\nid: bio-q-p101-q71-3\ntitle: صفحة 101، السؤال 71، الفرع 3\nquestion: ما عدد الكروموسومات الجسمية في الفرد الناتج المشار إليه بالرمز (ب)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية ثم أجب عن الأسئلة اللاحقة:\n\nما عدد الكروموسومات الجسمية في الفرد الناتج المشار إليه بالرمز (ب)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nالفرد(ب) ناتج من بويضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` وحيوان منوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XXY</mtext></math>`. الزيادة محصورة في الجنسية.\nكل غاميت يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>` كروموسوماً جسمياً، لذلك الجسمية في الزيجوت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+22=44</mtext></math>`.\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` جسمياً؛\nأما مجموع كروموسومات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XXY</mtext></math>` فهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+3=47</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p101-q71-4\ntitle: صفحة 101، السؤال 71، الفرع 4\nquestion: ما الطراز الكروموسومي الجنسي للفرد المشار إليه بالرمز (ج)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية ثم أجب عن الأسئلة اللاحقة:\n\nما الطراز الكروموسومي الجنسي للفرد المشار إليه بالرمز (ج)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nالفرد(ج) يتكون من بويضة فقدت الكروموسوم الجنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` وحيوان منوي طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\nالتركيب الجنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O+X=XO</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحد. هذا طراز تيرنر؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` رمز الغياب، لا كروموسوم ثانٍ.\n:::\n\n:::exam-question\nid: bio-q-p101-q71-5\ntitle: صفحة 101، السؤال 71، الفرع 5\nquestion: ما جنس الفرد الناتج المشار إليه بالرمز (ج)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nادرس المخطط الذي يوضح الآليات التي يتم من خلالها ظهور بعض الاختلالات الوراثية ثم أجب عن الأسئلة اللاحقة:\n\nما جنس الفرد الناتج المشار إليه بالرمز (ج)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nsolution:\n![المخطط الأصلي](assets/lessons/curriculum-evidence/4a71524283a82245cbaf.webp)\nالفرد(ج) ناتج من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` في البويضة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` في الحيوان المنوي، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XO</mtext></math>`. لا يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` ، ويصنف أنثى مصابة بمتلازمة تيرنر.\nعدد الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` وعدد الجنسية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` ، فالمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45</mtext></math>` ؛\nزيادة أوفقد كروموسوم لا يغير قاعدة قراءة الجنس في هذا المثال.\n:::\n\n:::exam-question\nid: bio-q-p101-q72-1\ntitle: صفحة 101، السؤال 72، الفرع 1\nquestion: بين السبب الجيني للإصابة بالمرض.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيعتبر مرض فينيل كيتونوريا (PKU) من الاختلالات الوراثية التي يتم تشخيصها لدى الأطفال حديثي الولادة:\n\nبين السبب الجيني للإصابة بالمرض.\nsolution:\n**الإجابة:** طفرة جينية متنحية على الكروموسوم رقم12.\n\n**الشاهد من الكتاب:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p101-q74\ntitle: صفحة 101، السؤال 74\nquestion: صمم مخططاً لانقسام خلية تناسلية ذكرية حدث فيها عدم انفصال لزوج الكروموسومات الجنسية (XY) مبيناً حالات الإخصاب المختلفة مع بويضة طبيعية (X).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nصمم مخططاً لانقسام خلية تناسلية ذكرية حدث فيها عدم انفصال لزوج الكروموسومات الجنسية (XY) مبيناً حالات الإخصاب المختلفة مع بويضة طبيعية (X).\nsolution:\nعدم انفصال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` في الانقسام المنصف الأول يجعل الغاميتات إما تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` معاً أوتخلو منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ؛\nوتظل الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>` في كل غاميت.\n![المخطط الأصلي في الإجابات](assets/lessons/curriculum-evidence/c83509e6d1f9b272631e.webp)\n\n| الحيوان المنوي | البويضة الطبيعية | الزيجوت | النتيجة |\n|---|---|---|---|\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+XY</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+X</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XXY</mtext></math>` | كلينفلتر، ذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>` |\n| `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+O</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+X</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XO</mtext></math>` | تيرنر، أنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45</mtext></math>` |\n\nبعد الانقسام الثاني المعتاد تنتج من الخلية الأصلية غاميتان من كل نوع؛\nالجدول يجمع حالتي الإخصاب المختلفتين.\n:::\n\n:::exam-question\nid: bio-q-p101-q75\ntitle: صفحة 101، السؤال 75\nquestion: بالاعتماد على الطرز الكروموسومية كيف يمكن تشخيص كل من مريض مصاب بمتلازمة إدواردز ومتلازمة تيرنر؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nبالاعتماد على الطرز الكروموسومية كيف يمكن تشخيص كل من مريض مصاب بمتلازمة إدواردز ومتلازمة تيرنر؟\nsolution:\nنفحص الطراز الكروموسومي بعد عد الكروموسومات وترتيبها:\nإدواردز: تظهر ثلاث نسخ من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>18</mtext></math>` بدلاً من اثنتين؛\nفتوجد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45</mtext></math>` جسمياً مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` ، والمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>`.\nتيرنر: يوجد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحد فقط دون جنسي آخر؛\nالجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` والمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45</mtext></math>` ، والطراز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XO</mtext></math>`.\nلذلك لا يكفي تشخيص «زيادة» أو«نقص»؛\nنحدد أيضاً الكروموسوم الذي تغير عدده.\n:::\n\n:::exam-question\nid: bio-q-p101-q76\ntitle: صفحة 101، السؤال 76\nquestion: قارن بين مرض حمى البحر الأبيض المتوسط ومرض عسر النمو العضلي التدريجي من حيث رقم الكروموسوم الذي حدثت عليه الطفرة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين مرض حمى البحر الأبيض المتوسط ومرض عسر النمو العضلي التدريجي من حيث رقم الكروموسوم الذي حدثت عليه الطفرة.\nsolution:\n**الإجابة:** حمى البحر الأبيض المتوسط: الكروموسوم الجسمي16. عسر النمو العضلي التدريجي: الكروموسومX، وهو من الزوج الجنسي23.\n\n**الشاهد من الكتاب 1:**\n\n> حمى البحر الأبيض المتوسط Familial Mediterranean Fever، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم16.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> وأن زوج الكروموسومات الجنسية رقم 23 تحدد الجنس (XX في الأنثى، XY في الذكر)\n\n**المصدر:** صفحة 32 من الكتاب.\n\n\n\n**الشاهد من الكتاب 3:**\n\n> XᴿY أب طبيعي؛ XᴿXʳ أم طبيعية حاملة؛ XʳY ذكر مصاب.\n\n**المصدر:** صفحة 32 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p101-q78\ntitle: صفحة 101، السؤال 78\nquestion: كيف تنتج غاميتات تحتوي زيادة أو نقصاناً في عدد الكروموسومات الجسمية أو الجنسية عند حدوث طفرة عدم الانفصال؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nكيف تنتج غاميتات تحتوي زيادة أو نقصاناً في عدد الكروموسومات الجسمية أو الجنسية عند حدوث طفرة عدم الانفصال؟\nsolution:\nعادة يفترق الكروموسومان المتناظران في الانقسام المنصف الأول، وتفترق الكروماتيدات الشقيقة في الثاني، فيأخذ كل غاميت نسخة واحدة.\nإذا لم ينفصل المتناظران في الطور الانفصالي الأول، ينتقلان معاً؛\nأوإذا لم ينفصل الشقيقان في الطور الانفصالي الثاني، ينتقلان معاً.\nيحصل غاميت على نسختين بدلاً من نسخة فيصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>n+1</mtext></math>` ، ويحرم غاميت آخر منها فيصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>n−1</mtext></math>`. يمكن أن يحدث ذلك لكروموسوم جسمي أوجنسي، تبعاً للزوج الذي أخفق انفصاله.\n:::\n\n:::exam-question\nid: bio-q-p101-q79\ntitle: صفحة 101، السؤال 79\nquestion: بين بمخططين آليتين يمكن أن ينتج من خلالهما الاختلال الوراثي (متلازمة تيرنر).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 101\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nبين بمخططين آليتين يمكن أن ينتج من خلالهما الاختلال الوراثي (متلازمة تيرنر).\nsolution:\nتيرنر تحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحداً فقط؛\nلذلك يلزم غاميت خالٍ من كروموسوم جنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` يلتقي غاميتاً طبيعياً يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`. الجسمية تتوزع طبيعياً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>` في كل غاميت.\n![المخططان الأصليان في الإجابات](assets/lessons/curriculum-evidence/6766112a14c68e0e5a28.webp)\n\n| الآلية | الغاميت الشاذ | الغاميت الطبيعي | الناتج |\n|---|---|---|---|\n| عدم انفصال عند الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XY</mtext></math>` | حيوان منوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+O</mtext></math>` | بويضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+X</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XO</mtext></math>` |\n| عدم انفصال عند الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XX</mtext></math>` | بويضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+O</mtext></math>` | حيوان منوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22+X</mtext></math>` | `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+XO</mtext></math>` |\n\nفي الحالتين العدد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+1=45</mtext></math>` والفرد أنثى. غاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` ينتج لأن الكروموسومات الجنسية ذهبت معاً إلى غاميت آخر.\n:::\n\n:::mcq\nid: bio-q-p102-q2\ntitle: صفحة 102، السؤال 2\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 102\nquestion: كم عدد الكروموسومات الجسمية في الطراز الكروموسومي للاختلال الوراثي الذي يمثله الشكل المجاور؟\n- [ ] option-1 | 44\n- [x] option-2 | 45\n- [ ] option-3 | 46\n- [ ] option-4 | 47\nexplanation:\n![الطراز الكروموسومي الأصلي](assets/lessons/curriculum-evidence/8d53e7ea958cb913b8ce.webp)\nالدائرة حول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` تبين ثلاث نسخ منه، أي متلازمة داون. الكروموسوم الزائد جسمي، لذلك الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=44+1=45</mtext></math>`.\nالإجابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>45</mtext></math>` ؛\nأما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>` فهو العدد الكلي بعد إضافة كروموسومين جنسيين، وليس المطلوب.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\nexample:\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/8d53e7ea958cb913b8ce.webp)\n:::\n\n:::mcq\nid: bio-q-p103-q11\ntitle: صفحة 103، السؤال 11\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 103\nquestion: أي الاختلالات الوراثية الآتية ينجم عن طفرة جينية؟\n- [ ] option-1 | كلينفلتر\n- [ ] option-2 | تيرنر\n- [ ] option-3 | داون\n- [x] option-4 | كرابي\nexplanation:\n**الإجابة:** كرابي\n\n**الشاهد من الكتاب:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم 12.\n> مرض كرابي Krabbe Disease مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم 14.\n> حمى البحر الأبيض المتوسط Familial Mediterranean Fever، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم 16.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::exam-question\nid: bio-q-p111-q27-1a\ntitle: صفحة 111، السؤال 27، الفرع 1a\nquestion: متلازمة إدواردز.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nوضح المقصود:\n\nمتلازمة إدواردز.\nsolution:\n**متلازمة إدواردز:** وجود ثلاث نسخ من الكروموسوم الجسمي18 بدلاً من نسختين.\n\nفي الطبيعي22 زوجاً جسمياً، أي44 كروموسوماً جسمياً. تضيف النسخة الزائدة واحداً:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mn>44</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>45</mn></mrow></math>\n```\n\n\n\nومع الكروموسومين الجنسيين:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mn>45</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>47</mn></mrow></math>\n```\n\n\n\nإذن المجموع **47 كروموسوماً**.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n![الشاهد من الكتاب](assets/lessons/curriculum-evidence/70f58d1997b716996394.webp)\n\n:::\n\n:::exam-question\nid: bio-q-p111-q27-3\ntitle: صفحة 111، السؤال 27، الفرع 3\nquestion: قارن بين مرض كرابي ومرض حمى البحر الأبيض المتوسط من حيث رقم الكروموسوم الذي حدثت عليه الطفرة.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين مرض كرابي ومرض حمى البحر الأبيض المتوسط من حيث رقم الكروموسوم الذي حدثت عليه الطفرة.\nsolution:\n**الإجابة:** كرابي:14؛ حمى البحر الأبيض المتوسط:16.\n\n**الشاهد من الكتاب:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم 12.\n> مرض كرابي Krabbe Disease مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم 14.\n> حمى البحر الأبيض المتوسط Familial Mediterranean Fever، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم 16.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p111-q28-1\ntitle: صفحة 111، السؤال 28، الفرع 1\nquestion: قارن بين متلازمة داون والطراز الكروموسومي الطبيعي من حيث عدد الكروموسومات الكلية وعدد الكروموسومات الجسمية.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للطفرات الجينية والكروموسومية أجب:\n\nقارن بين متلازمة داون والطراز الكروموسومي الطبيعي من حيث عدد الكروموسومات الكلية وعدد الكروموسومات الجسمية.\nsolution:\nالطراز الطبيعي في الشكل يحوي22 زوجاً من الكروموسومات الجسمية، مع كروموسومين جنسيين.\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mtext>جسمية طبيعية</mtext><mo stretchy="false">)</mo><mo>=</mo><mn>22</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>44</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mtext>كلية طبيعية</mtext><mo stretchy="false">)</mo><mo>=</mo><mn>44</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>46</mn></mrow></math>\n```\n\n\n\nفي داون توجد نسخة إضافية من الكروموسوم الجسمي21:\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mtext>جسمية داون</mtext><mo stretchy="false">)</mo><mo>=</mo><mn>44</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>45</mn></mrow></math>\n```\n\n\n\n\n\n```mathml\n<math dir="ltr" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi>N</mi><mo stretchy="false">(</mo><mtext>كلية داون</mtext><mo stretchy="false">)</mo><mo>=</mo><mn>45</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>47</mn></mrow></math>\n```\n\n\n\nإذن **الطبيعي46 كلياً منها44 جسمياً؛ وداون47 كلياً منها45 جسمياً**.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n![الشاهد من الكتاب](assets/lessons/curriculum-evidence/70f58d1997b716996394.webp)\n\n:::\n\n:::exam-question\nid: bio-q-p111-q28-2\ntitle: صفحة 111، السؤال 28، الفرع 2\nquestion: ما سبب الإصابة بمرض كرابي؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للطفرات الجينية والكروموسومية أجب:\n\nما سبب الإصابة بمرض كرابي؟\nsolution:\n**الإجابة:** طفرة جينية متنحية على الكروموسوم رقم14.\n\n**الشاهد من الكتاب:**\n\n> مرض كرابي Krabbe Disease، مرض وراثي ناتج عن طفرة جينية متنحية على الكروموسوم رقم14.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p111-q29-1\ntitle: صفحة 111، السؤال 29، الفرع 1\nquestion: ما العدد الكلي للكروموسومات في الخلية رقم (1)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للاختلالات الوراثية ادرس الشكل المجاور ثم أجب:\n\nما العدد الكلي للكروموسومات في الخلية رقم (1)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nsolution:\n![الشكل الأصلي](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nالخلية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)</mtext></math>` بويضة طبيعية تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحداً، وليست الخلية الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XX</mtext></math>`. البويضة أحادية المجموعة فتحتوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>22</mtext></math>` جسمياً و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>`.\nالعدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=22+1=23</mtext></math>` كروموسوماً. لا ننسب إليها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` الشاذ المرسوم في الحيوان المنوي.\n:::\n\n:::exam-question\nid: bio-q-p111-q29-2\ntitle: صفحة 111، السؤال 29، الفرع 2\nquestion: اكتب الطراز الكروموسومي الجنسي للفرد رقم (2).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للاختلالات الوراثية ادرس الشكل المجاور ثم أجب:\n\nاكتب الطراز الكروموسومي الجنسي للفرد رقم (2).\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nsolution:\n![الشكل الأصلي](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nالعمود الذي يضم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)</mtext></math>` يمثل بويضة طبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ، والصف حيواناً منوياً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XY</mtext></math>` نتج بعد عدم الانفصال.\nنضم الكروموسومات الجنسية في الإخصاب : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X+XY=XXY</mtext></math>`. إذن طراز الفرد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)</mtext></math>` الجنسي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XXY</mtext></math>` ، وهو نمط كلينفلتر.\n:::\n\n:::exam-question\nid: bio-q-p111-q29-3\ntitle: صفحة 111، السؤال 29، الفرع 3\nquestion: ما اسم الاختلال الوراثي للفرد في الحالة رقم (3)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nمن خلال دراستك للاختلالات الوراثية ادرس الشكل المجاور ثم أجب:\n\nما اسم الاختلال الوراثي للفرد في الحالة رقم (3)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nsolution:\n![الشكل الأصلي](assets/lessons/curriculum-evidence/bb48e20769586f23c628.webp)\nالحالة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(3)</mtext></math>` تجمع بويضة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` مع حيوان منوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` خالٍ من كروموسوم جنسي، بعد عدم انفصال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` إلى الغاميت الآخر.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X+O=XO</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` واحد دون جنسي ثانٍ؛\nاسم الاختلال متلازمة تيرنر، والمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44+1=45</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p111-q30-1a\ntitle: صفحة 111، السؤال 30، الفرع 1a\nquestion: سبب المرض.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين مرض عسر النمو العضلي التدريجي ومرض فينيل كيتونوريا من حيث:\n\nسبب المرض.\nsolution:\n**الإجابة:** عسر النمو العضلي التدريجي: طفرة متنحية محمولة علىX. فينيل كيتونيوريا: طفرة جينية متنحية على الكروموسوم12.\n\n**الشاهد من الكتاب 1:**\n\n> مرض وراثي مرتبط بالجنس سببه طفرة متنحية محمولة على الكروموسومX\n\n**المصدر:** صفحة 62 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p111-q30-1b\ntitle: صفحة 111، السؤال 30، الفرع 1b\nquestion: الكروموسوم المسؤول.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nقارن بين مرض عسر النمو العضلي التدريجي ومرض فينيل كيتونوريا من حيث:\n\nالكروموسوم المسؤول.\nsolution:\n**الإجابة:** عسر النمو العضلي التدريجي: الكروموسومX. فينيل كيتونيوريا: الكروموسوم الجسمي12.\n\n**الشاهد من الكتاب 1:**\n\n> مرض وراثي مرتبط بالجنس سببه طفرة متنحية محمولة على الكروموسومX\n\n**المصدر:** صفحة 62 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> مرض فينيل كيتونيوريا Phenylketonuria (PKU)، مرض وراثي سببه طفرة جينية متنحية على الكروموسوم رقم12.\n\n**المصدر:** صفحة 37 من الكتاب.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p111-q31-2a\ntitle: صفحة 111، السؤال 31، الفرع 2a\nquestion: متلازمة داون.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 111\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nما سبب ظهور كل من الحالات الوراثية الآتية؟\n\nمتلازمة داون.\nsolution:\nفي نموذج عدم الانفصال، يفشل افتراق نسختي الكروموسوم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` في الانقسام المنصف، أوتفترق كروموسوماته في الأول ثم تفشل كروماتيداته الشقيقة في الثاني.\nينتج غاميت يحمل نسختين من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` بدلاً من نسخة. يتحد مع غاميت طبيعي يحمل نسخة واحدة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2+1=3</mtext></math>` نسخ من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>`.\nهكذا يظهر الطراز ذوثلاثية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>21</mtext></math>` «متلازمة داون»، ويصبح العدد الكلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>47</mtext></math>`. هذه آلية المصدر المعروضة، دون حصر جميع صور داون الطبية بها.\n:::\n\n:::mcq\nid: bio-q-p116-q1-5\ntitle: صفحة 116، السؤال 1-5\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 116\nquestion: ما عدد الكروموسومات الجسمية في شخص مصاب بمرض فينيل كيتونوريا؟\n- [x] option-1 | 44\n- [ ] option-2 | 45\n- [ ] option-3 | 46\n- [ ] option-4 | 47\nexplanation:\nفينيل كيتونيوريا مرض طفرة جينية متنحية على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>12</mtext></math>` ؛\nلا يغير عدد الكروموسومات.\nإذن عدد الكروموسومات الجسمية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>44</mtext></math>` ، الاختيار الأول. ومع الكروموسومين الجنسيين يكون المجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>46</mtext></math>` ، لكن السؤال يطلب الجسمية وحدها.\nhint: راجع معطيات السؤال وقارن البدائل الأصلية.\n:::\n\n:::mcq\nid: bio-b-p038-q1-1\ntitle: الرزمة التعليمية، صفحة 38، السؤال 1-1\nquestion: ما الاختلاف بين السيادة غير التامة والسيادة المشتركة؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\n- [ ] option-1 | السيادة غير التامة يتحكم فيها ثلاث أليلات والسيادة المشتركة يتحكم بها أليلان\n- [ ] option-2 | الصفة الوسطية في السيادة غير التامة تظهر من اجتماع جين سائد مع متنحٍ بينما المشتركة تظهر من اجتماع جينين سائدين\n- [x] option-3 | في الهجين تظهر صفة وسطية في السيادة غير التامة، ويظهر أثر الأليلين معًا في السيادة المشتركة.\n- [ ] option-4 | اجتماع جينين سائدين معاً يؤدي إلى ظهور تأثير الجينين معاً في السيادة غير التامة وظهور صفة وسطية في المشتركة\nexplanation:\nالسيادة غير التامة: الهجين يظهر مظهراً وسطياً، مثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` الأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` الأبيض.\nالسيادة المشتركة: يظهر أثر الأليلين كاملاً معاً، مثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` في الدجاج الرزي ذي الريش الأسود والأبيض.\nإذن الاختيار الثالث هو المقصود: صفة وسطية في الأولى وظهور أثر الأليلين معاً في الثانية. تعبير «جينين سائدين» في الخيار اصطلاح مدرسي؛\nالأدق أليلان لا يسود أحدهما على الآخر تماماً، لا جينان في موضعين مختلفين.\n\nhint: اقرأ السؤال وقارن بين البدائل الأصلية.\n:::\n\n:::exam-question\nid: bio-b-p038-q2-1\ntitle: الرزمة التعليمية، صفحة 38، السؤال 2-1\nquestion: الطراز الشكلي للأب.\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي والده سليم من نزف الدم (R) طبيعي الشعر، ومن فتاة سليمة من نزف الدم طبيعية الشعر. ولد لهما طفلة مصابة بمرض نزف الدم وعند بلوغها تساقط شعرها وفصيلة دمها O. ومن خلال الفحص المخبري تبين أنه لا يستطيع أي من الوالدين التبرع بالدم للآخر واحتواء دم الأم على الأنتيجين A، اكتب:\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nالطراز الشكلي للأب.\n\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تستلزم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` وأماً تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nالأم سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`. سلامة جدها الأبوي لا تمنع إصابة الأب، لأنه يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أمه لا من أبيه.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الإناث. أبو الشاب طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فأعطاه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nوالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في الأبوين. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` والأم الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` للطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأم تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فتصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ، وعدم توافق النقل في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nإذن الطراز الشكلي للأب: مصاب بنزف الدم، أصلع، وفصيلة دمه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-b-p038-q2-2\ntitle: الرزمة التعليمية، صفحة 38، السؤال 2-2\nquestion: الطراز الجيني للشاب والفتاة.\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي والده سليم من نزف الدم (R) طبيعي الشعر، ومن فتاة سليمة من نزف الدم طبيعية الشعر. ولد لهما طفلة مصابة بمرض نزف الدم وعند بلوغها تساقط شعرها وفصيلة دمها O. ومن خلال الفحص المخبري تبين أنه لا يستطيع أي من الوالدين التبرع بالدم للآخر واحتواء دم الأم على الأنتيجين A، اكتب:\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nالطراز الجيني للشاب والفتاة.\n\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تستلزم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` وأماً تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nالأم سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`. سلامة جدها الأبوي لا تمنع إصابة الأب، لأنه يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أمه لا من أبيه.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الإناث. أبو الشاب طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فأعطاه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nوالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في الأبوين. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` والأم الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` للطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأم تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فتصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ، وعدم توافق النقل في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nالطرز النهائية: الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY b⁺b Iᴮi</mtext></math>` ؛\nالفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ b⁺b Iᴬi</mtext></math>`.\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ bb ii</mtext></math>` ؛\nوأخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من كل أب وفق نوع حمل كل جين.\n:::\n\n:::exam-question\nid: bio-b-p038-q2-3\ntitle: الرزمة التعليمية، صفحة 38، السؤال 2-3\nquestion: ما احتمال إنجاب طفل ذكر سليم من المرض طبيعي الشعر وفصيلة دمه B؟\nreference: [الرزمة التعليمية، صفحة PDF 38](https://moe.edu.ps/m/4061#page=38)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي والده سليم من نزف الدم (R) طبيعي الشعر، ومن فتاة سليمة من نزف الدم طبيعية الشعر. ولد لهما طفلة مصابة بمرض نزف الدم وعند بلوغها تساقط شعرها وفصيلة دمها O. ومن خلال الفحص المخبري تبين أنه لا يستطيع أي من الوالدين التبرع بالدم للآخر واحتواء دم الأم على الأنتيجين A، اكتب:\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nما احتمال إنجاب طفل ذكر سليم من المرض طبيعي الشعر وفصيلة دمه B؟\n\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nنزف الدم متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تستلزم أباً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` وأماً تحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` ؛\nالأم سليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`. سلامة جدها الأبوي لا تمنع إصابة الأب، لأنه يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` من أمه لا من أبيه.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` في الإناث. أبو الشاب طبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فأعطاه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` ؛\nوالطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في الأبوين. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` والأم الطبيعية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` للطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأم تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فتصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ، وعدم توافق النقل في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` بأرباع؛\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ، وهو وحده طبيعي في الذكور.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi × Iᴬi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=1/4</mtext></math>`.\nبالاستقلال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/4)×(1/4)×(1/4)=1/64</mtext></math>` من كل النسل.\n:::\n\n:::exam-question\nid: bio-b-p039-q4-1\ntitle: الرزمة التعليمية، صفحة 39، السؤال 4-1\nquestion: ما نوع الوراثة في كل من الصفتين؟\nreference: [الرزمة التعليمية، صفحة PDF 39](https://moe.edu.ps/m/4061#page=39)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nجرى تلقيح بين نباتين أحدهما أملس البذور زهري الأزهار والآخر غير معروف الطراز الشكلي. كانت النتائج: ملساء زهرية(4)، مجعدة زهرية(4)، ملساء حمراء(2)، مجعدة حمراء(2)، ملساء بيضاء(2)، مجعدة بيضاء(2). نرمز للملساء A وللمجعدة a وللأزهار الحمراء R وللبيضاء W.\n\nما نوع الوراثة في كل من الصفتين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` سائد للأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للمجعد. الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` ؛\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` تلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>`.\nلون الأزهار : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+4=8</mtext></math>` والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` ؛\nأي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nإذن شكل البذور سيادة تامة، لأن وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يظهر الأملس دون مظهر وسطي. ولون الأزهار سيادة غير تامة، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` يظهر الزهري وسطياً بين الأحمر والأبيض.\n:::\n\n:::exam-question\nid: bio-b-p039-q4-2\ntitle: الرزمة التعليمية، صفحة 39، السؤال 4-2\nquestion: ما الطرز الجينية لكل من النباتين (الأبوين) للصفتين معاً؟\nreference: [الرزمة التعليمية، صفحة PDF 39](https://moe.edu.ps/m/4061#page=39)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nجرى تلقيح بين نباتين أحدهما أملس البذور زهري الأزهار والآخر غير معروف الطراز الشكلي. كانت النتائج: ملساء زهرية(4)، مجعدة زهرية(4)، ملساء حمراء(2)، مجعدة حمراء(2)، ملساء بيضاء(2)، مجعدة بيضاء(2). نرمز للملساء A وللمجعدة a وللأزهار الحمراء R وللبيضاء W.\n\nما الطرز الجينية لكل من النباتين (الأبوين) للصفتين معاً؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` سائد للأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للمجعد. الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` ؛\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` تلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>`.\nلون الأزهار : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+4=8</mtext></math>` والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` ؛\nأي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nالمعروف أملس زهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaRW</mtext></math>` ؛\nلأنه أنجب مجعداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` فيلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` فيه، والمجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aaRW</mtext></math>` مجعد زهري.\nتزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` مناصفة، وتزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` ، مطابق النسب المذكورة.\nإذن الأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AaRW × aaRW</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-b-p039-q4-3\ntitle: الرزمة التعليمية، صفحة 39، السؤال 4-3\nquestion: ما احتمال ظهور نباتات مجعدة البذور بيضاء الأزهار من بين النباتات الناتجة جميعها؟\nreference: [الرزمة التعليمية، صفحة PDF 39](https://moe.edu.ps/m/4061#page=39)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nجرى تلقيح بين نباتين أحدهما أملس البذور زهري الأزهار والآخر غير معروف الطراز الشكلي. كانت النتائج: ملساء زهرية(4)، مجعدة زهرية(4)، ملساء حمراء(2)، مجعدة حمراء(2)، ملساء بيضاء(2)، مجعدة بيضاء(2). نرمز للملساء A وللمجعدة a وللأزهار الحمراء R وللبيضاء W.\n\nما احتمال ظهور نباتات مجعدة البذور بيضاء الأزهار من بين النباتات الناتجة جميعها؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` سائد للأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للمجعد. الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` ؛\nالنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:1</mtext></math>` تلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>`.\nلون الأزهار : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+4=8</mtext></math>` والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=2+2=4</mtext></math>` ؛\nأي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nالمجعد في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ، والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nباستقلال الصفتين : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/4)=1/8</mtext></math>`.\nومن الأعداد مباشرةً: المجعد الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` ، والمجموع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4+4+2+2+2+2=16</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2/16=1/8</mtext></math>` ، فيتفق الحسابان.\n:::\n\n:::exam-question\nid: bio-b-p041-q3-2\ntitle: الرزمة التعليمية، صفحة 41، السؤال 3-2\nquestion: اكتب الطراز الجيني للأبوين وللطفلة للصفتين معاً.\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B من فتاة فصيلة دمها A سليمة من مرض عمى الألوان، فأنجبا طفلة فصيلة دمها O مصابة بعمى الألوان. جين الرؤية الطبيعية R سائد على جين عمى الألوان r.\n\nاكتب الطراز الجيني للأبوين وللطفلة للصفتين معاً.\nsolution:\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فتثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عند الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، ومن الأم السليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XʳY</mtext></math>` ، الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XᴿXʳ</mtext></math>` ، والطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii XʳXʳ</mtext></math>`. لا تمنع سلامة الأم حمل الأليل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` يسود عليه.\n:::\n\n:::exam-question\nid: bio-b-p041-q3-3\ntitle: الرزمة التعليمية، صفحة 41، السؤال 3-3\nquestion: ما احتمال إنجاب ذكر فصيلة دمه AB سليم من مرض عمى الألوان؟\nreference: [الرزمة التعليمية، صفحة PDF 41](https://moe.edu.ps/m/4061#page=41)\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل فصيلة دمه B من فتاة فصيلة دمها A سليمة من مرض عمى الألوان، فأنجبا طفلة فصيلة دمها O مصابة بعمى الألوان. جين الرؤية الطبيعية R سائد على جين عمى الألوان r.\n\nما احتمال إنجاب ذكر فصيلة دمه AB سليم من مرض عمى الألوان؟\nsolution:\nفي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>` يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` طرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فتثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عند الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، ومن الأم السليمة فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi × Iᴬi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع، فاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=1/4</mtext></math>`.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` بأرباع؛\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` احتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nباستقلال الصفتين : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/4)×(1/4)=1/16</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p095-q40-3\ntitle: صفحة 95، السؤال 40، الفرع 3\nquestion: ما الطراز الشكلي للنبات المجهول؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nجرى تلقيح بين نباتين أحدهما أملس البذور زهري الأزهار والآخر غير معروف الطراز الشكلي، ثم جمعت البذور الناتجة وزرعت فكانت الطرز الشكلية للنباتات الناتجة: ملساء البذور زهرية الأزهار (4)، ملساء البذور حمراء الأزهار (2)، مجعدة البذور زهرية الأزهار (4)، مجعدة البذور حمراء الأزهار (2)، ملساء البذور بيضاء الأزهار (2)، مجعدة البذور بيضاء الأزهار (2). يرمز لجين البذور الملساء بالرمز (A) ولجين البذور المجعدة (a)، ولجين الأزهار الحمراء (R) ولجين الأزهار البيضاء (W).\n\nما الطراز الشكلي للنبات المجهول؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` سائد للأملس و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للمجعد. الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` والمجعد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=4+2+2=8</mtext></math>` ؛\nفيلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × aa</mtext></math>` ، والمعروف أملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` فالمجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>`.\nللون سيادة غير تامة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>` أبيض؛\nالأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8</mtext></math>` والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>4</mtext></math>` ، أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nإذن النبات المجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aaRW:</mtext></math>` مجعد البذور زهري الأزهار.\n:::\n\n:::exam-question\nid: bio-q-p095-q43-1\ntitle: صفحة 95، السؤال 43، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية حصل تزاوج بين ذكر شعره أسود ولديه بروز شبيه بالقرون في العظم الجبهي (غير متماثلة الجينات)، مع أنثى شعرها منقط (يحتوي شعراً أسود وشعراً أبيض) ولديها بروز شبيه بالقرون. صفة البروز شبيه بالقرون تتأثر بالهرمونات الجنسية، وجين وجود البروز سائد عند الذكور على الجين الطبيعي. أجب مستخدماً رموزاً مناسبة.\n\nاكتب الطرز الجينية للأبوين للصفتين معاً.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للبروز و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` لغيابه؛\nالصفة متأثرة بالجنس، فيسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` في الذكر ويتنحى في الأنثى. الذكر غير متماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` وله بروز؛\nوالأنثى ذات البروز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>`.\nلون الشعر سيادة مشتركة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض، ويجمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` الشعرين معاً. الذكر الأسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` والأنثى المنقطة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>`.\nإذن الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh CᴮCᴮ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH CᴮCᵂ</mtext></math>`. ظهور الشعر المنقط يعني حضور اللونين، وليس لوناً وسطياً جديداً.\n:::\n\n:::exam-question\nid: bio-q-p095-q43-2\ntitle: صفحة 95، السؤال 43، الفرع 2\nquestion: اكتب الطرز الجينية لغاميتات الأنثى للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية حصل تزاوج بين ذكر شعره أسود ولديه بروز شبيه بالقرون في العظم الجبهي (غير متماثلة الجينات)، مع أنثى شعرها منقط (يحتوي شعراً أسود وشعراً أبيض) ولديها بروز شبيه بالقرون. صفة البروز شبيه بالقرون تتأثر بالهرمونات الجنسية، وجين وجود البروز سائد عند الذكور على الجين الطبيعي. أجب مستخدماً رموزاً مناسبة.\n\nاكتب الطرز الجينية لغاميتات الأنثى للصفتين معاً.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للبروز و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` لغيابه؛\nالصفة متأثرة بالجنس، فيسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` في الذكر ويتنحى في الأنثى. الذكر غير متماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` وله بروز؛\nوالأنثى ذات البروز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>`.\nلون الشعر سيادة مشتركة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض، ويجمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` الشعرين معاً. الذكر الأسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` والأنثى المنقطة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>`.\nطراز الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH CᴮCᵂ</mtext></math>`. الغاميت يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` دائماً، وأحد أليلي اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>`.\nغاميتاها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HCᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HCᵂ</mtext></math>` ، لكل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p095-q43-3\ntitle: صفحة 95، السؤال 43، الفرع 3\nquestion: ما احتمال إنتاج أفراد شعرها بيضاء ولها بروز شبيه بالقرون من النسل الناتج؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية حصل تزاوج بين ذكر شعره أسود ولديه بروز شبيه بالقرون في العظم الجبهي (غير متماثلة الجينات)، مع أنثى شعرها منقط (يحتوي شعراً أسود وشعراً أبيض) ولديها بروز شبيه بالقرون. صفة البروز شبيه بالقرون تتأثر بالهرمونات الجنسية، وجين وجود البروز سائد عند الذكور على الجين الطبيعي. أجب مستخدماً رموزاً مناسبة.\n\nما احتمال إنتاج أفراد شعرها بيضاء ولها بروز شبيه بالقرون من النسل الناتج؟\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للبروز و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` لغيابه؛\nالصفة متأثرة بالجنس، فيسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` في الذكر ويتنحى في الأنثى. الذكر غير متماثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` وله بروز؛\nوالأنثى ذات البروز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>`.\nلون الشعر سيادة مشتركة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴮ</mtext></math>` للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض، ويجمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` الشعرين معاً. الذكر الأسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` والأنثى المنقطة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>`.\nالأبيض يحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᵂCᵂ</mtext></math>` ، لكن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` لا يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` أبداً. تزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ × CᴮCᵂ</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᴮ</mtext></math>` أسوداً ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` منقطاً.\nإذن احتمال الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>0</mtext></math>` ، واحتمال أبيض ذي بروز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=0</mtext></math>` مهما كان جنس النسل أوتركيب البروز.\n:::\n\n:::exam-question\nid: bio-q-p095-q43-4\ntitle: صفحة 95، السؤال 43، الفرع 4\nquestion: ما نوع الوراثة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 95\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية حصل تزاوج بين ذكر شعره أسود ولديه بروز شبيه بالقرون في العظم الجبهي (غير متماثلة الجينات)، مع أنثى شعرها منقط (يحتوي شعراً أسود وشعراً أبيض) ولديها بروز شبيه بالقرون. صفة البروز شبيه بالقرون تتأثر بالهرمونات الجنسية، وجين وجود البروز سائد عند الذكور على الجين الطبيعي. أجب مستخدماً رموزاً مناسبة.\n\nما نوع الوراثة؟\nsolution:\nلون الشعر سيادة مشتركة: يظهر الأسود والأبيض معاً في الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴮCᵂ</mtext></math>` ، بدلاً من امتزاجهما إلى لون وسطي.\nالبروز الشبيه بالقرون صفة متأثرة بالجنس: جينها جسمي وتتغير سيادته باختلاف الهرمونات الجنسية؛\nفيظهر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` ببروز في الذكر، ويحتاج ظهوره في الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>`.\nهذان تصنيفان مختلفان: الأول يصف أثر أليلي اللون، والثاني أثر الجنس في إظهار أليلي البروز.\n:::\n\n:::exam-question\nid: bio-q-p096-q44-1\ntitle: صفحة 96، السؤال 44، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي ونوع الأنتيجين على سطح خلايا دمه الحمراء (أنتيجين A)، من فتاة صلعاء وبلازما دمها لا تحتوي أجساماً مضادة فأنجبا فرداً أصلع وفصيلة دمه B.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالمرأة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nمولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده على خلايا الرجل يدل على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، والمرأة بلا مضادي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` في البلازما هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Iᴬi</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb IᴬIᴮ</mtext></math>`. يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p096-q44-2\ntitle: صفحة 96، السؤال 44، الفرع 2\nquestion: اكتب غاميتات الأب.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي ونوع الأنتيجين على سطح خلايا دمه الحمراء (أنتيجين A)، من فتاة صلعاء وبلازما دمها لا تحتوي أجساماً مضادة فأنجبا فرداً أصلع وفصيلة دمه B.\n\nاكتب غاميتات الأب.\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالمرأة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nمولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده على خلايا الرجل يدل على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، والمرأة بلا مضادي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` في البلازما هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b Iᴬi</mtext></math>` ؛\nالغاميت يحمل أليلاً من كل جين. بالاستقلال نختار `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>`.\nغاميتاته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bIᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺i</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bi</mtext></math>` ، كل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p096-q44-3\ntitle: صفحة 96، السؤال 44، الفرع 3\nquestion: ما نوع الوراثة للصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي ونوع الأنتيجين على سطح خلايا دمه الحمراء (أنتيجين A)، من فتاة صلعاء وبلازما دمها لا تحتوي أجساماً مضادة فأنجبا فرداً أصلع وفصيلة دمه B.\n\nما نوع الوراثة للصفتين؟\nsolution:\n**الإجابة:** الصلع: صفة جسمية متأثرة بالجنس. فصائلABO: أليلات متعددة؛ بينIᴬ وIᴮ سيادة مشتركة، ويسود كل منهما سيادة تامة علىi.\n\n**الشاهد من الكتاب 1:**\n\n> هي الصفات التي تحمل جيناتها على الكروموسومات الجسمية، ولكنها تتأثر بالهرمونات الجنسية، ومن الأمثلة عليها صفة الصلع عند الإنسان\n\n**المصدر:** صفحة 33 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> يقصد بالأليلات المتعددة أن هنالك كثيراً من الجينات لديها أكثر من شكلين اثنين من الأليلات، ولكن لا يحصل الفرد الواحد منها إلا على أليلين فقط.\nيعد نظام الدم من الأمثلة على الأليلات المتعددة، وفي هذا النظام توجد ثلاثة أليلات\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\n**الشاهد من الكتاب 3:**\n\n> A: IᴬIᴬ أوIᴬi؛ B: IᴮIᴮ أوIᴮi؛ AB: IᴬIᴮ، أنتيجينA وأنتيجينB؛ O: ii.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\nتظهر علاقة السيادة في الجدول: Iᴬi فصيلتهA، وIᴮi فصيلتهB، أماIᴬIᴮ فيُظهر مولدي الضد معاً.\n\n:::\n\n:::exam-question\nid: bio-q-p096-q44-4\ntitle: صفحة 96، السؤال 44، الفرع 4\nquestion: ما احتمال إنجاب أنثى صلعاء فصيلة دمها B؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 96\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل أصلع والده بشعر طبيعي ونوع الأنتيجين على سطح خلايا دمه الحمراء (أنتيجين A)، من فتاة صلعاء وبلازما دمها لا تحتوي أجساماً مضادة فأنجبا فرداً أصلع وفصيلة دمه B.\n\nما احتمال إنجاب أنثى صلعاء فصيلة دمها B؟\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الرجل الأصلع أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، فهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ؛\nوالمرأة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nمولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده على خلايا الرجل يدل على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، والمرأة بلا مضادي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` في البلازما هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. الابن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × bb</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nالأنثى لا تصلع إلا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، فاحتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × IᴬIᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=1/4</mtext></math>`.\nاحتمال أنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/2)×(1/4)=1/16</mtext></math>` من كل النسل.\n:::\n\n:::exam-question\nid: bio-q-p104-q1-1\ntitle: صفحة 104، السؤال 1، الفرع 1\nquestion: ما نوع السيادة في الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأجري تلقيح بين نباتين أحدهما طويل الساق زهري الأزهار، والآخر غير معروف الطراز الشكلي، ثم جمعت البذور الناتجة وزرعت فكانت الطرز الشكلية: قصيرة الساق زهرية الأزهار (10)، طويلة الساق زهرية الأزهار (34)، طويلة الساق حمراء الأزهار (12)، طويلة الساق بيضاء الأزهار (15)، قصيرة الساق حمراء الأزهار (6)، قصيرة الساق بيضاء الأزهار (6). استخدم T لجين طول الساق وt لجين قصر الساق.\n\nما نوع السيادة في الصفتين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+12+15=61</mtext></math>` ، والقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=10+6+6=22</mtext></math>` ، أي نحو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` ؛\nهذا يلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × Tt</mtext></math>`.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، والهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=12+6=18</mtext></math>` ، والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+10=44</mtext></math>` ، والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=15+6=21</mtext></math>` ؛\nتقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nإذن طول الساق سيادة تامة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` طويل مثل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TT</mtext></math>`. ولون الأزهار سيادة غير تامة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` له مظهر زهري مستقل بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p104-q1-2\ntitle: صفحة 104، السؤال 1، الفرع 2\nquestion: ما الطرز الجينية لكل من النباتين الأبوين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأجري تلقيح بين نباتين أحدهما طويل الساق زهري الأزهار، والآخر غير معروف الطراز الشكلي، ثم جمعت البذور الناتجة وزرعت فكانت الطرز الشكلية: قصيرة الساق زهرية الأزهار (10)، طويلة الساق زهرية الأزهار (34)، طويلة الساق حمراء الأزهار (12)، طويلة الساق بيضاء الأزهار (15)، قصيرة الساق حمراء الأزهار (6)، قصيرة الساق بيضاء الأزهار (6). استخدم T لجين طول الساق وt لجين قصر الساق.\n\nما الطرز الجينية لكل من النباتين الأبوين؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+12+15=61</mtext></math>` ، والقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=10+6+6=22</mtext></math>` ، أي نحو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` ؛\nهذا يلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × Tt</mtext></math>`.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، والهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=12+6=18</mtext></math>` ، والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+10=44</mtext></math>` ، والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=15+6=21</mtext></math>` ؛\nتقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nالأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRW × TtRW</mtext></math>`.\nلكل منهما غاميتات `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tW</mtext></math>` عند الاستقلال. في الطول تنتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TT</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` ؛\nوفي اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\nإذن يتوقع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3</mtext></math>` طوال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` قصير، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` أحمر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` زهري : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` أبيض؛\nالفروق العددية عن النسبة المثالية تعكس العينة.\n:::\n\n:::exam-question\nid: bio-q-p104-q1-3\ntitle: صفحة 104، السؤال 1، الفرع 3\nquestion: ما الطراز الشكلي للنبات المجهول؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nأجري تلقيح بين نباتين أحدهما طويل الساق زهري الأزهار، والآخر غير معروف الطراز الشكلي، ثم جمعت البذور الناتجة وزرعت فكانت الطرز الشكلية: قصيرة الساق زهرية الأزهار (10)، طويلة الساق زهرية الأزهار (34)، طويلة الساق حمراء الأزهار (12)، طويلة الساق بيضاء الأزهار (15)، قصيرة الساق حمراء الأزهار (6)، قصيرة الساق بيضاء الأزهار (6). استخدم T لجين طول الساق وt لجين قصر الساق.\n\nما الطراز الشكلي للنبات المجهول؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير. الطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+12+15=61</mtext></math>` ، والقصير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=10+6+6=22</mtext></math>` ، أي نحو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>3:1</mtext></math>` ؛\nهذا يلائم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × Tt</mtext></math>`.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، والهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` زهري وسطي. الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=12+6=18</mtext></math>` ، والزهري `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=34+10=44</mtext></math>` ، والأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=15+6=21</mtext></math>` ؛\nتقارب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، فتكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW × RW</mtext></math>`.\nالمجهول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TtRW</mtext></math>` ؛\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` يجعله طويل الساق، واجتماع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` يجعله زهري الأزهار.\nإذن مظهره طويل الساق زهري الأزهار، مثل النبات المعروف؛\nواختلاف النقاء عن المظهر يفسر ظهور القصار والألوان الثلاثة في نسلهما.\n:::\n\n:::exam-question\nid: bio-q-p104-q2-1\ntitle: صفحة 104، السؤال 2، الفرع 1\nquestion: اكتب الطرز الجينية للغاميتات المرقمة (1،2).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج تلقيح بين ذكر وأنثى لصفتين وراثيتين هما شكل الشعر ولون العيون. C لجين الشعر المجعد وS لجين الشعر المستقيم، واجتماعهما ينتج شعراً مموجاً. A للعيون العسلية وa للعيون الزرقاء.\n\nاكتب الطرز الجينية للغاميتات المرقمة (1،2).\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` للمجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للمستقيم؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج بسيادة غير تامة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق في نموذج المسألة.\n![مربع بانيت الأصلي](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nأعمدة الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)</mtext></math>` تمثل توزيع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C/S</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A/a</mtext></math>` ، فالمتبقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)=Sa</mtext></math>`.\nصف الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)</mtext></math>` يتحد مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` فينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CCaa</mtext></math>` كما هو مكتوب؛\nيلزم أن يمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` ، إذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)=Ca</mtext></math>`.\nكل غاميت يحمل أليلاً واحداً للشعر وأليلاً للعين.\n:::\n\n:::exam-question\nid: bio-q-p104-q2-2\ntitle: صفحة 104، السؤال 2، الفرع 2\nquestion: ما الطرز الجينية لكل من الأبوين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج تلقيح بين ذكر وأنثى لصفتين وراثيتين هما شكل الشعر ولون العيون. C لجين الشعر المجعد وS لجين الشعر المستقيم، واجتماعهما ينتج شعراً مموجاً. A للعيون العسلية وa للعيون الزرقاء.\n\nما الطرز الجينية لكل من الأبوين؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` للمجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للمستقيم؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج بسيادة غير تامة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق في نموذج المسألة.\n![مربع بانيت الأصلي](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nغاميتات الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>SA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Sa</mtext></math>` تكشف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للشعر، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للعين؛\nإذن الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS Aa</mtext></math>`.\nغاميتا الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` تشتركان في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` وتختلفان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A/a</mtext></math>` ؛\nإذن الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC Aa</mtext></math>`.\nالشكل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CCaa</mtext></math>` في الجدول يؤكد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` من الطرفين، ولا يجعل الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p104-q2-3\ntitle: صفحة 104، السؤال 2، الفرع 3\nquestion: ما الطراز الشكلي للفرد (4)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج تلقيح بين ذكر وأنثى لصفتين وراثيتين هما شكل الشعر ولون العيون. C لجين الشعر المجعد وS لجين الشعر المستقيم، واجتماعهما ينتج شعراً مموجاً. A للعيون العسلية وa للعيون الزرقاء.\n\nما الطراز الشكلي للفرد (4)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` للمجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للمستقيم؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج بسيادة غير تامة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق في نموذج المسألة.\n![مربع بانيت الأصلي](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nالخانة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(4)</mtext></math>` من اتحاد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ca</mtext></math>` الأنثى مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Sa</mtext></math>` الذكر. نضم أليلي الشعر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` فنحصل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` ، وأليلي العين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` فنحصل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>`.\nالفرد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS aa:</mtext></math>` مموج الشعر بسبب الصفة الوسطية، وأزرق العينين لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` متنح. هذا تطبيق النموذج المعطى للعين.\n:::\n\n:::exam-question\nid: bio-q-p104-q2-4\ntitle: صفحة 104، السؤال 2، الفرع 4\nquestion: ما احتمال إنجاب ذكر يحمل الطراز الجيني رقم (3)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل مربع بانيت نتائج تلقيح بين ذكر وأنثى لصفتين وراثيتين هما شكل الشعر ولون العيون. C لجين الشعر المجعد وS لجين الشعر المستقيم، واجتماعهما ينتج شعراً مموجاً. A للعيون العسلية وa للعيون الزرقاء.\n\nما احتمال إنجاب ذكر يحمل الطراز الجيني رقم (3)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>C</mtext></math>` للمجعد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>S</mtext></math>` للمستقيم؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` مموج بسيادة غير تامة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. A</mtext></math>` للعسلي السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` للأزرق في نموذج المسألة.\n![مربع بانيت الأصلي](assets/lessons/curriculum-evidence/fdcaf5af081b5416d2e5.webp)\nالخانة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(3)</mtext></math>` من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CA</mtext></math>` الأنثى و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Sa</mtext></math>` الذكر؛\nطرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS Aa</mtext></math>`. الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS Aa</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC Aa</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS × CC</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CC</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS</mtext></math>` ، فاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CS=1/2</mtext></math>`.\nالعيون : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa × Aa</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AA</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>aa</mtext></math>` ، فاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Aa=1/2</mtext></math>`. هذا الطراز يظهر في خانتين من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>8</mtext></math>` لا في خانة واحدة فقط.\nالجنس مستقل واحتمال الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/2)×(1/2)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p104-q3-3\ntitle: صفحة 104، السؤال 3، الفرع 3\nquestion: ما احتمال ظهور خيول قصيرة العنق كستنائية الجلد سوداء العيون؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 104\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الخيول الإسبانية التي تتحدر من أصول لخيول عربية، حصل تزاوج بين ذكر حصان بالامينو الجلد قصير العنق بني العيون، مع أنثى حصان مجهولة الطراز الشكلي. النسل الناتج: 100% طويلة العنق؛ 25% سوداء العيون كستنائية الجلد، 50% بالامينو الجلد، 25% كريمية الجلد. استخدم A للعيون البنية وa للسوداء وT لطول العنق وt لقصره.\n\nما احتمال ظهور خيول قصيرة العنق كستنائية الجلد سوداء العيون؟\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطول السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصر؛\nالذكر قصير العنق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`. النسل المتوقع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>` طويل، فيلزم أن تكون الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TT</mtext></math>` ؛\nتعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` فقط، والأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` فقط.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>TT × tt</mtext></math>` يعطي جميع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` طويلاً، فلا ينتج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` قصير.\nلذلك احتمال قصير العنق كستنائي الجلد أسود العيون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=0</mtext></math>` ؛\nإذ يكفي استحالة القصر، ولا نحتاج ضرب نسب اللونين.\n:::\n\n:::exam-question\nid: bio-q-p105-q4-1\ntitle: صفحة 105، السؤال 4، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع نباتات الزينة (الأضاليا) تم تلقيح نبات أضاليا مبرقش الأزهار (أزهاره بيضاء منقطة بالأحمر) أملس الأوراق، مع نبات أضاليا مبرقش الأزهار خشن الأوراق. كانت الأفراد الناتجة: حمراء الأزهار أملس الأوراق (118)، مبرقشة الأزهار أملس الأوراق (240)، بيضاء الأزهار أملس الأوراق (120). جين أملس الأوراق B سائد على خشن الأوراق b.\n\nاكتب الطرز الجينية للأبوين للصفتين معاً.\nsolution:\nلون الأزهار سيادة مشتركة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض، والمبرقش `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ</mtext></math>` يظهر اللونين معاً. كلا الأبوين مبرقش إذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` للأوراق الملساء يسود على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للخشن؛\nالخشن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`. لأن جميع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>478</mtext></math>` فرداً أملس في نموذج النسبة المتوقعة، يكون الأملس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB × bb</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` فقط.\nإذن الأبوان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB CᴿCᵂ × bb CᴿCᵂ</mtext></math>`. غاميتات الأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` ، والثاني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` ؛\nاللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` أحمر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` مبرقش : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1</mtext></math>` أبيض، مطابق `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>118:240:120</mtext></math>` تقريباً.\n:::\n\n:::exam-question\nid: bio-q-p105-q4-2\ntitle: صفحة 105، السؤال 4، الفرع 2\nquestion: اكتب الطراز الجيني المتوقع لأفراد نباتات الزينة (الأضاليا) ذات الطراز الشكلي حمراء الأزهار خشنة الأوراق.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع نباتات الزينة (الأضاليا) تم تلقيح نبات أضاليا مبرقش الأزهار (أزهاره بيضاء منقطة بالأحمر) أملس الأوراق، مع نبات أضاليا مبرقش الأزهار خشن الأوراق. كانت الأفراد الناتجة: حمراء الأزهار أملس الأوراق (118)، مبرقشة الأزهار أملس الأوراق (240)، بيضاء الأزهار أملس الأوراق (120). جين أملس الأوراق B سائد على خشن الأوراق b.\n\nما الطراز الجيني الذي يلزم لنبات أضاليا أحمر الأزهار خشن الأوراق؟ وهل يمكن أن يظهر هذا الطراز بين أفراد التزاوج المعطى؟ وضح السبب.\n\nsolution:\nالسيادة المشتركة تعني ظهور أثر الأليلين معاً؛ لذلك نعدّ الأزهار البيضاء المنقطة بالأحمر هجينة اللون.\nلون الأزهار سيادة مشتركة : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴿ</mtext></math>` أحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᵂCᵂ</mtext></math>` أبيض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ</mtext></math>` مبرقش `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. B</mtext></math>` للأوراق الملساء سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للخشن، لذلك الخشن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nإذن الطراز الذي يجمع الأحمر والخشن هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb CᴿCᴿ</mtext></math>`.\nهذا وصف جيني نظري للطراز المطلوب؛\nلا ينتج من التزاوج المعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB CᴿCᵂ × bb CᴿCᵂ</mtext></math>` ، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB × bb</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` أملساً في جميع الأفراد، وهو ما تؤيده الأعداد.\n:::\n\n:::exam-question\nid: bio-q-p105-q4-3\ntitle: صفحة 105، السؤال 4، الفرع 3\nquestion: ما نوع الوراثة في الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع نباتات الزينة (الأضاليا) تم تلقيح نبات أضاليا مبرقش الأزهار (أزهاره بيضاء منقطة بالأحمر) أملس الأوراق، مع نبات أضاليا مبرقش الأزهار خشن الأوراق. كانت الأفراد الناتجة: حمراء الأزهار أملس الأوراق (118)، مبرقشة الأزهار أملس الأوراق (240)، بيضاء الأزهار أملس الأوراق (120). جين أملس الأوراق B سائد على خشن الأوراق b.\n\nما نوع الوراثة في الصفتين؟\nsolution:\nلون الأزهار سيادة مشتركة؛\nالمبرقش `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ</mtext></math>` يظهر بقعاً حمراء وبيضاء معاً، ويعطي تزاوج المبرقشين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ × CᴿCᵂ</mtext></math>` أحمر ومبرقشاً وأبيض بنسبة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1:2:1</mtext></math>` ، موافقة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>118:240:120</mtext></math>` تقريباً.\nملمس الأوراق سيادة تامة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` يحجب أثر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` فيكون أملس. تزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` الأملس مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` الخشن يعطي كل النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` أملساً، كما في النتائج.\n:::\n\n:::exam-question\nid: bio-q-p105-q5-1\ntitle: صفحة 105، السؤال 5، الفرع 1\nquestion: اكتب الطراز الشكلي للثور (الأب) للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول الطرز الجينية لبعض الغاميتات والأفراد الناتجة عن تزاوج بين ثور وبقرة مجهولي الطرز الشكلية للصفتين. C^R جين الشعر الأحمر وC^W جين الشعر الأبيض، وجين عدم وجود القرون B سائد على جين وجود القرون b.\n\nاكتب الطراز الشكلي للثور (الأب) للصفتين معاً.\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لعدم وجود القرون سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لوجودها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض بينهما سيادة مشتركة، فيظهر الهجين روزياً «أبيض وأحمر معاً».\n![الجدول الأصلي](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nغاميتا الثور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴿ</mtext></math>` تظهران `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` عنده. والغاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)</mtext></math>` يعطي مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` البقرة فرداً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᵂ</mtext></math>` ، فيلزم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` ؛\nإذن يحمل الثور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` أيضاً.\nطراز الثور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᴿCᵂ</mtext></math>` ؛\nوجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` يجعله عديم القرون، واجتماع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` يجعله روزي الشعر.\n:::\n\n:::exam-question\nid: bio-q-p105-q5-2\ntitle: صفحة 105، السؤال 5، الفرع 2\nquestion: اكتب الطرز الجينية لما تمثله الأرقام (1) و(2).\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول الطرز الجينية لبعض الغاميتات والأفراد الناتجة عن تزاوج بين ثور وبقرة مجهولي الطرز الشكلية للصفتين. C^R جين الشعر الأحمر وC^W جين الشعر الأبيض، وجين عدم وجود القرون B سائد على جين وجود القرون b.\n\nاكتب الطرز الجينية لما تمثله الأرقام (1) و(2).\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لعدم وجود القرون سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لوجودها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض بينهما سيادة مشتركة، فيظهر الهجين روزياً «أبيض وأحمر معاً».\n![الجدول الأصلي](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nالخانة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᵂ</mtext></math>` تنتج من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` الأم مع الغاميت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)</mtext></math>` ، فيلزم أن يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)=BCᵂ</mtext></math>`.\nالخانة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᴿ</mtext></math>` تحت غاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴿ</mtext></math>` تكشف أن غاميت الأم في الصف العلوي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` ؛\nوالصف السفلي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` ، إذن البقرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᵂ</mtext></math>`. والثور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᴿCᵂ</mtext></math>` ؛\nيعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` ، حيث العمود الرابع غير مكتوب الرأس.\nالفرد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)</mtext></math>` في العمود الرابع ناتج من `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` الأب؛\nطرازه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᵂ</mtext></math>`. إذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1)BCᵂ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(2)Bb CᵂCᵂ</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p105-q5-3\ntitle: صفحة 105، السؤال 5، الفرع 3\nquestion: ما احتمال إنتاج أفراد تحمل الطراز المشار إليه رقم (3)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 105\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nيمثل الجدول الطرز الجينية لبعض الغاميتات والأفراد الناتجة عن تزاوج بين ثور وبقرة مجهولي الطرز الشكلية للصفتين. C^R جين الشعر الأحمر وC^W جين الشعر الأبيض، وجين عدم وجود القرون B سائد على جين وجود القرون b.\n\nما احتمال إنتاج أفراد تحمل الطراز المشار إليه رقم (3)؟\n\n![الشكل الأصلي المرافق للسؤال](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` لعدم وجود القرون سائد على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` لوجودها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᵂ</mtext></math>` للأبيض بينهما سيادة مشتركة، فيكون الهجين روزياً.\n![الجدول الأصلي](assets/lessons/curriculum-evidence/50998e0df9157914745c.webp)\nالخانتان المعطاتان تكشفان الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᴿCᵂ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb CᵂCᵂ</mtext></math>`. الأب يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` ؛\nوالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BCᵂ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>`.\nالرقم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(3)</mtext></math>` في العمود الرابع والصف السفلي : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` من الأب مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᵂ</mtext></math>` من الأم، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb CᵂCᵂ</mtext></math>`.\nللقرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb × Bb</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>BB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Bb</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb=1/4</mtext></math>`. وللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ × CᵂCᵂ</mtext></math>` يعطي نصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᵂ</mtext></math>` ونصف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᵂCᵂ</mtext></math>` ؛\nاحتمال الأبيض `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nباستقلال الجينين: احتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb CᵂCᵂ=(1/4)×(1/2)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p107-q12-1\ntitle: صفحة 107، السؤال 12، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nحصل تزاوج بين ذكر طيور كريمي الريش طويل الأرجل (غير نقي لصفة طول الأرجل)، مع أنثى بنية الريش قصيرة الأرجل. نتج: ذكر بني الريش (2)، ذكر كريمي الريش (2)، أنثى بنية الريش (2)، أنثى بيضاء الريش (2). جينا طول الأرجل ولون الريش لا يقعان على نفس الكروموسوم. استخدم T للأرجل الطويلة وt للقصيرة.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\nفي الطيور الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ؛\nلون الريش هنا على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` بسيادة غير تامة. نرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` للأبيض، فيكون الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵂ</mtext></math>` كريمياً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. W</mtext></math>` المنفرد كروموسوم جنسي آخر، ويختلف عن رمز أليل اللون الأبيض المرتفع.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير؛\nالذكر طويل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` والأم قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt ZᴮZᵂ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt ZᴮW</mtext></math>`.\nغاميتا اللون الأبويتان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` الأم تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` ذكر بني، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵂ</mtext></math>` ذكر كريمي، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮW</mtext></math>` أنثى بنية، `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵂW</mtext></math>` أنثى بيضاء؛\nكل فئة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` ، مطابقة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>2</mtext></math>` لكل منها.\n:::\n\n:::exam-question\nid: bio-q-p107-q12-2\ntitle: صفحة 107، السؤال 12، الفرع 2\nquestion: اكتب الطرز الجينية للأفراد الذكور الناتجة من التزاوج.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nحصل تزاوج بين ذكر طيور كريمي الريش طويل الأرجل (غير نقي لصفة طول الأرجل)، مع أنثى بنية الريش قصيرة الأرجل. نتج: ذكر بني الريش (2)، ذكر كريمي الريش (2)، أنثى بنية الريش (2)، أنثى بيضاء الريش (2). جينا طول الأرجل ولون الريش لا يقعان على نفس الكروموسوم. استخدم T للأرجل الطويلة وt للقصيرة.\n\nاكتب الطرز الجينية للأفراد الذكور الناتجة من التزاوج.\nsolution:\nفي الطيور الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ؛\nلون الريش هنا على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` بسيادة غير تامة. نرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` للأبيض، فيكون الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵂ</mtext></math>` كريمياً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. W</mtext></math>` المنفرد كروموسوم جنسي آخر، ويختلف عن رمز أليل اللون الأبيض المرتفع.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير؛\nالذكر طويل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` والأم قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt ZᴮZᵂ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt ZᴮW</mtext></math>`. الذكر الناتج يأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` من الأب، فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᴮ</mtext></math>` بنياً أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵂ</mtext></math>` كريمياً.\nالأرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` طويل و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` قصير مناصفة.\nالطرز الذكرية `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt ZᴮZᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt ZᴮZᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt ZᴮZᵂ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt ZᴮZᵂ</mtext></math>` ؛\nكل منها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/8</mtext></math>` من كل النسل أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>` بين الذكور.\n:::\n\n:::exam-question\nid: bio-q-p107-q12-3\ntitle: صفحة 107، السؤال 12، الفرع 3\nquestion: ما احتمال ظهور أنثى بيضاء طويلة الأرجل في النسل الناتج من التزاوج؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nحصل تزاوج بين ذكر طيور كريمي الريش طويل الأرجل (غير نقي لصفة طول الأرجل)، مع أنثى بنية الريش قصيرة الأرجل. نتج: ذكر بني الريش (2)، ذكر كريمي الريش (2)، أنثى بنية الريش (2)، أنثى بيضاء الريش (2). جينا طول الأرجل ولون الريش لا يقعان على نفس الكروموسوم. استخدم T للأرجل الطويلة وt للقصيرة.\n\nما احتمال ظهور أنثى بيضاء طويلة الأرجل في النسل الناتج من التزاوج؟\nsolution:\nفي الطيور الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` ؛\nلون الريش هنا على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` بسيادة غير تامة. نرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴮ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` للأبيض، فيكون الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴮZᵂ</mtext></math>` كريمياً `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>. W</mtext></math>` المنفرد كروموسوم جنسي آخر، ويختلف عن رمز أليل اللون الأبيض المرتفع.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` للطويل السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` للقصير؛\nالذكر طويل غير نقي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` والأم قصيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt ZᴮZᵂ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt ZᴮW</mtext></math>`. الأنثى البيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵂW</mtext></math>` تحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵂ</mtext></math>` من الأب و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` من الأم؛\nاحتمالها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/2)=1/4</mtext></math>` من كل النسل.\nالأرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt × tt:</mtext></math>` غاميتا `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>T</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>t</mtext></math>` تعطيان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Tt</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>tt</mtext></math>` ، فاحتمال الطويل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالجينان مستقلان كما نص السؤال؛\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/4)×(1/2)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p107-q13-1\ntitle: صفحة 107، السؤال 13، الفرع 1\nquestion: اكتب الطراز الشكلي للرجل لصفة أنيميا الفول.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل طرازه الشكلي غير معروف بالنسبة لمرض التفول (أنيميا الفول)، والأجسام المضادة في بلازما دمه من نوع A فقط، من فتاة فصيلة دمها غير معروفة لكنها سليمة من أنيميا الفول. أنجبا بنتاً فصيلة دمها A ومصابة بأنيميا الفول. لم تنجح عملية نقل الدم من الزوجة إلى زوجها، بينما نجحت من الزوج إلى الزوجة مع إهمال العامل الرايزيسي. استخدم r لجين الإصابة بأنيميا الفول، وهو جين متنحٍ على الكروموسوم الجنسي X.\n\nاكتب الطراز الشكلي للرجل لصفة أنيميا الفول.\n\nsolution:\nأنيميا الفول متنحية على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` كما نص السؤال؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` للمرض و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للسلامة. البنت المصابة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تحتاج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من الأب ومن الأم.\nالأب يمنح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` لابنته، فلا بد أن يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ، وهو مصاب بأنيميا الفول. لا يكشف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` المرض؛\nهذا معطى خاص بفصيلة الدم.\n:::\n\n:::exam-question\nid: bio-q-p107-q13-2\ntitle: صفحة 107، السؤال 13، الفرع 2\nquestion: اكتب الطرز الجينية لكل من الرجل والفتاة والبنت.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل طرازه الشكلي غير معروف بالنسبة لمرض التفول (أنيميا الفول)، والأجسام المضادة في بلازما دمه من نوع A فقط، من فتاة فصيلة دمها غير معروفة لكنها سليمة من أنيميا الفول. أنجبا بنتاً فصيلة دمها A ومصابة بأنيميا الفول. لم تنجح عملية نقل الدم من الزوجة إلى زوجها، بينما نجحت من الزوج إلى الزوجة مع إهمال العامل الرايزيسي. استخدم r لجين الإصابة بأنيميا الفول، وهو جين متنحٍ على الكروموسوم الجنسي X.\n\nاكتب الطرز الجينية لكل من الرجل والفتاة والبنت.\n\nsolution:\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nأنيميا الفول متنحية على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تثبت أن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` والأم السليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده عند الرجل يعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح عطائه للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nإذن الرجل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XʳY</mtext></math>` ؛\nالفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ XᴿXʳ</mtext></math>` ؛\nالبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XʳXʳ</mtext></math>`. يسود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ، ويظهران معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p107-q13-3\ntitle: صفحة 107، السؤال 13، الفرع 3\nquestion: ما احتمال إنجاب ذكر فصيلة دمه B وسليم من أنيميا الفول بين النسل؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج رجل طرازه الشكلي غير معروف بالنسبة لمرض التفول (أنيميا الفول)، والأجسام المضادة في بلازما دمه من نوع A فقط، من فتاة فصيلة دمها غير معروفة لكنها سليمة من أنيميا الفول. أنجبا بنتاً فصيلة دمها A ومصابة بأنيميا الفول. لم تنجح عملية نقل الدم من الزوجة إلى زوجها، بينما نجحت من الزوج إلى الزوجة مع إهمال العامل الرايزيسي. استخدم r لجين الإصابة بأنيميا الفول، وهو جين متنحٍ على الكروموسوم الجنسي X.\n\nما احتمال إنجاب ذكر فصيلة دمه B وسليم من أنيميا الفول بين النسل؟\n\nsolution:\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nأنيميا الفول متنحية على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` تثبت أن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` والأم السليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` وحده عند الرجل يعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`. نجاح عطائه للزوجة وفشل العكس يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>`. البنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` أخذت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، لذا الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` والبنت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nالدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi × IᴬIᴮ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴬIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴮIᴮ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` ؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=2/4=1/2</mtext></math>`.\nالمرض والجنس `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY × XᴿXʳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳXʳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` ؛\nالذكر السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` حالته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nبالاستقلال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/2)×(1/4)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p107-q14-1\ntitle: صفحة 107، السؤال 14، الفرع 1\nquestion: اكتب الطراز الشكلي والجيني للفتاة للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمه A سليم من عمى الألوان من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا ولداً مصاباً بعمى الألوان فصيلة دمه B، وولداً آخر سليماً من عمى الألوان فصيلة دمه O. باستخدام الرموز المناسبة أجب:\n\nاكتب الطراز الشكلي والجيني للفتاة للصفتين معاً.\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الابنان يأخذان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب، ووجود سليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ومصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` عند الأم، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` سليمة حاملة.\nالولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` فيثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. الولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب؛\nومع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عند الأم تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nالفتاة سليمة حاملة لعمى الألوان وفصيلتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ؛\nطرازها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XᴿXʳ</mtext></math>`. لا يمكن أن تكون مصابة، لأنها أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` للابن السليم.\n:::\n\n:::exam-question\nid: bio-q-p107-q14-2\ntitle: صفحة 107، السؤال 14، الفرع 2\nquestion: اكتب الطراز الجيني للشاب.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمه A سليم من عمى الألوان من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا ولداً مصاباً بعمى الألوان فصيلة دمه B، وولداً آخر سليماً من عمى الألوان فصيلة دمه O. باستخدام الرموز المناسبة أجب:\n\nاكتب الطراز الجيني للشاب.\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الابنان يأخذان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب، ووجود سليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ومصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` عند الأم، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` سليمة حاملة.\nالولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` فيثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. الولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب؛\nومع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عند الأم تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nالأب سليم من عمى الألوان فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ، وفصيلته `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` مع منحه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` للولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` تجعله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`.\nإذن الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XᴿY</mtext></math>` ؛\nلا نستلزم إصابته من وجود ابن مصاب، لأن الابن أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` منه و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` من أمه.\n:::\n\n:::exam-question\nid: bio-q-p107-q14-3\ntitle: صفحة 107، السؤال 14، الفرع 3\nquestion: ما احتمال إنجاب بنت سليمة من عمى الألوان فصيلة دمها (AB)؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمه A سليم من عمى الألوان من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا ولداً مصاباً بعمى الألوان فصيلة دمه B، وولداً آخر سليماً من عمى الألوان فصيلة دمه O. باستخدام الرموز المناسبة أجب:\n\nما احتمال إنجاب بنت سليمة من عمى الألوان فصيلة دمها (AB)؟\nsolution:\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>r</mtext></math>` مصاب. الابنان يأخذان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Y</mtext></math>` من الأب، ووجود سليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ومصاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XʳY</mtext></math>` يثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` عند الأم، فهي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` سليمة حاملة.\nالولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` فيثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين؛\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>`. الولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮ</mtext></math>` من الأم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` من الأب؛\nومع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عند الأم تصبح `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>`.\nالدم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi × Iᴮi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=1/4</mtext></math>`.\nكل بنت تأخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` من الأب السليم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿY</mtext></math>` ؛\nمع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xʳ</mtext></math>` الأم تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴿXʳ</mtext></math>` وكلتاهما سليمة.\nاحتمال بنت سليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/2×1=1/2</mtext></math>`.\nبالاستقلال: احتمال بنت سليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB=(1/2)×(1/4)=1/8</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p107-q14-4\ntitle: صفحة 107، السؤال 14، الفرع 4\nquestion: ما مبدأ الوراثة لكل من الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 107\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب فصيلة دمه A سليم من عمى الألوان من فتاة مجهولة الطراز الشكلي للصفتين، فأنجبا ولداً مصاباً بعمى الألوان فصيلة دمه B، وولداً آخر سليماً من عمى الألوان فصيلة دمه O. باستخدام الرموز المناسبة أجب:\n\nما مبدأ الوراثة لكل من الصفتين؟\nsolution:\n**الإجابة:** فصائلABO: أليلات متعددة، وبينIᴬ وIᴮ سيادة مشتركة. عمى الألوان: صفة متنحية مرتبطة بالكروموسومX.\n\n**الشاهد من الكتاب 1:**\n\n> يقصد بالأليلات المتعددة أن هنالك كثيراً من الجينات لديها أكثر من شكلين اثنين من الأليلات، ولكن لا يحصل الفرد الواحد منها إلا على أليلين فقط.\nيعد نظام الدم من الأمثلة على الأليلات المتعددة، وفي هذا النظام توجد ثلاثة أليلات\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\n**الشاهد من الكتاب 2:**\n\n> A: IᴬIᴬ أوIᴬi؛ B: IᴮIᴮ أوIᴮi؛ AB: IᴬIᴮ، أنتيجينA وأنتيجينB؛ O: ii.\n\n**المصدر:** صفحة 30 من الكتاب.\n\n\n\n**الشاهد من الكتاب 3:**\n\n> XʰY مصاب؛ XᴴXʰ حاملات.\n\n\n\n\n\nدليل المعلم يعرضXʰY مصاباً وXᴴXʰ حاملة، وهو نموذج صفة متنحية علىX.\n\n:::\n\n:::exam-question\nid: bio-q-p108-q15-1\ntitle: صفحة 108، السؤال 15، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية صفة البروزات الشبيهة بالقرون سائدة عند الذكور ومتنحية عند الإناث، ويختلف الطراز الشكلي للذكور عنه للإناث في حالة عدم تماثل الجينات. تزاوج ذكر عديم القرون أحمر اللون مع أنثى بقرون بيضاء اللون، فكان النسل: جميع الذكور بقرون ولونها قرميدي، وجميع الإناث بدون قرون ولونها قرميدي.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للقرون و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور ويتنحى عند الإناث. الذكر عديم القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأنثى ذات القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، واجتماعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` يعطي القرميدي في نموذج السؤال. الذكر أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` والأنثى بيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ RR</mtext></math>` ، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb WW</mtext></math>`. غاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺R</mtext></math>` وغاميت الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bW</mtext></math>` ، فيكون النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b RW</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p108-q15-2\ntitle: صفحة 108، السؤال 15، الفرع 2\nquestion: اكتب الطرز الجينية لغاميتات الذكر.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية صفة البروزات الشبيهة بالقرون سائدة عند الذكور ومتنحية عند الإناث، ويختلف الطراز الشكلي للذكور عنه للإناث في حالة عدم تماثل الجينات. تزاوج ذكر عديم القرون أحمر اللون مع أنثى بقرون بيضاء اللون، فكان النسل: جميع الذكور بقرون ولونها قرميدي، وجميع الإناث بدون قرون ولونها قرميدي.\n\nاكتب الطرز الجينية لغاميتات الذكر.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للقرون و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور ويتنحى عند الإناث. الذكر عديم القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأنثى ذات القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، واجتماعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` يعطي القرميدي في نموذج السؤال. الذكر أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` والأنثى بيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\nالذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ RR</mtext></math>` متماثل في الموضعين؛\nلذلك يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` في جميع غاميتاته.\nالنوع الوحيد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺R</mtext></math>` واحتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>100%</mtext></math>` ؛\nلا نضيف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bR</mtext></math>` لأنه لا يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p108-q15-3\ntitle: صفحة 108، السؤال 15، الفرع 3\nquestion: اكتب الطرز الجينية للأفراد الناتجة من التزاوج.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي إحدى سلالات الماشية صفة البروزات الشبيهة بالقرون سائدة عند الذكور ومتنحية عند الإناث، ويختلف الطراز الشكلي للذكور عنه للإناث في حالة عدم تماثل الجينات. تزاوج ذكر عديم القرون أحمر اللون مع أنثى بقرون بيضاء اللون، فكان النسل: جميع الذكور بقرون ولونها قرميدي، وجميع الإناث بدون قرون ولونها قرميدي.\n\nاكتب الطرز الجينية للأفراد الناتجة من التزاوج.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للقرون و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابها؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود عند الذكور ويتنحى عند الإناث. الذكر عديم القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأنثى ذات القرون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>R</mtext></math>` للأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` للأبيض، واجتماعهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` يعطي القرميدي في نموذج السؤال. الذكر أحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RR</mtext></math>` والأنثى بيضاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>WW</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ RR</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺R</mtext></math>` فقط، والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb WW</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bW</mtext></math>` فقط؛\nالنسل كله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b RW</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>RW</mtext></math>` قرميدي في الجنسين. الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` ذو قرون في الذكور وبلا قرون في الإناث، لأن سيادة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` تتغير بالجنس.\nإذن الطراز الجيني واحد لجميع النسل، مع اختلاف المظهر الجنسي للقرون.\n:::\n\n:::exam-question\nid: bio-q-p108-q16-1\ntitle: صفحة 108، السؤال 16، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع عصافير الزينة صفة وجود العرف سائدة في الذكور ومتنحية في الإناث، ويختلف الطراز الشكلي في الذكور عنه للإناث عند عدم تماثل الجينات. تزاوج ذكر ريشه مخطط وبدون عرف مع أنثى غير مخططة الريش ولها عرف. النسل: نصف الذكور مخطط وله عرف والنصف الآخر غير مخطط وله عرف؛ نصف الإناث مخطط وبدون عرف والنصف الآخر غير مخطط وبدون عرف. A لجين الريش المخطط السائد على غير المخطط a، وهذه الصفة مرتبطة بالجنس.\n\nاكتب الطرز الجينية للأبوين.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` لغيابه؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` يسود في الذكور ويتنحى في الإناث. الذكر بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hh</mtext></math>` والأنثى ذات عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>` ، فيكون كل النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` ، الذكور بعرف والإناث بلا عرف.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للريش المخطط السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` لغير المخطط، والجين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` في الطيور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` للذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` للأنثى. الأم غير مخططة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵃW</mtext></math>` ، والأب مخطط أنجب غير مخطط فيحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` أيضاً أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴬZᵃ</mtext></math>`.\nإذن الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hh ZᴬZᵃ</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH ZᵃW</mtext></math>`. تزاوج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᴬ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵃ</mtext></math>` الأب مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Zᵃ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>W</mtext></math>` الأم يعطي ذكوراً وإناثاً في كل منها نصف مخطط ونصف غير مخطط، موافقاً للنتائج.\n:::\n\n:::exam-question\nid: bio-q-p108-q16-2\ntitle: صفحة 108، السؤال 16، الفرع 2\nquestion: اكتب الطرز الجينية لغاميتات الأبوين.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع عصافير الزينة صفة وجود العرف سائدة في الذكور ومتنحية في الإناث، ويختلف الطراز الشكلي في الذكور عنه للإناث عند عدم تماثل الجينات. تزاوج ذكر ريشه مخطط وبدون عرف مع أنثى غير مخططة الريش ولها عرف. النسل: نصف الذكور مخطط وله عرف والنصف الآخر غير مخطط وله عرف؛ نصف الإناث مخطط وبدون عرف والنصف الآخر غير مخطط وبدون عرف. A لجين الريش المخطط السائد على غير المخطط a، وهذه الصفة مرتبطة بالجنس.\n\nاكتب الطرز الجينية لغاميتات الأبوين.\nsolution:\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>h</mtext></math>` لغيابه؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>H</mtext></math>` يسود في الذكور ويتنحى في الإناث. الذكر بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hh</mtext></math>` والأنثى ذات عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH</mtext></math>` ، فيكون كل النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Hh</mtext></math>` ، الذكور بعرف والإناث بلا عرف.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` للريش المخطط السائد و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` لغير المخطط، والجين على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Z</mtext></math>` في الطيور `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZZ</mtext></math>` للذكر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZW</mtext></math>` للأنثى. الأم غير مخططة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᵃW</mtext></math>` ، والأب مخطط أنجب غير مخطط فيحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>a</mtext></math>` أيضاً أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ZᴬZᵃ</mtext></math>`.\nيحمل الغاميت أليلاً للعرف وكروموسوماً جنسياً واحداً.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hh ZᴬZᵃ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hZᴬ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>hZᵃ</mtext></math>` مناصفة.\nالأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HH ZᵃW</mtext></math>` تعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HZᵃ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>HW</mtext></math>` مناصفة.\nلا يغيران تنوع العرف لأن كل أب متماثل فيه؛التنوع فقط في الكروموسومات الجنسية.\n:::\n\n:::exam-question\nid: bio-q-p108-q17-1\ntitle: صفحة 108، السؤال 17، الفرع 1\nquestion: ما الطراز الجيني لكل من الشاب والفتاة للصفات الثلاث؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي (والده كان ذا شعر طبيعي)، من فتاة ذات شعر طبيعي سليمة من مرض عمى الألوان. أنجبا طفلة مصابة بعمى الألوان فصيلة دمها O وعند بلوغها تساقط شعرها. تبين بالفحص المخبري أن أياً من الأبوين لا يستطيع التبرع للآخر بالدم، ويوجد مولد ضد A على أغشية خلايا الدم الحمراء للأم. استخدم M لجين عدم الإصابة بعمى الألوان.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nما الطراز الجيني لكل من الشاب والفتاة للصفات الثلاث؟\n\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>m</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐXᵐ</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵐ</mtext></math>` لدى الأب فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐY</mtext></math>` ، والأم السليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴹXᵐ</mtext></math>`.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكور ومتنح في الإناث. الشاب أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، وأعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nفهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. الأم الطبيعية التي أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` أيضاً.\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فتثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين. وجود مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند الأم يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ؛\nوعدم التبرع بين الوالدين في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nإذن الشاب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi XᵐY b⁺b</mtext></math>` ، والفتاة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi XᴹXᵐ b⁺b</mtext></math>`. لا نحمل أليل الصلع على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\nفهو جين جسمي متأثر بالجنس.\n\n\n\n:::\n\n:::exam-question\nid: bio-q-p108-q17-2\ntitle: صفحة 108، السؤال 17، الفرع 2\nquestion: ما نوع الأجسام المضادة في بلازما دم الزوج؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي (والده كان ذا شعر طبيعي)، من فتاة ذات شعر طبيعي سليمة من مرض عمى الألوان. أنجبا طفلة مصابة بعمى الألوان فصيلة دمها O وعند بلوغها تساقط شعرها. تبين بالفحص المخبري أن أياً من الأبوين لا يستطيع التبرع للآخر بالدم، ويوجد مولد ضد A على أغشية خلايا الدم الحمراء للأم. استخدم M لجين عدم الإصابة بعمى الألوان.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nما نوع الأجسام المضادة في بلازما دم الزوج؟\n\nsolution:\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` للطفلة يعني `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، لذلك تحمل الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ؛\nومع مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` من فصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>`. عدم توافق النقل في الاتجاهين مع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` يحصر الأب في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` ، ووجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` عنده يجعله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nفصيلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` تحمل مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` على الخلايا، وفي بلازمتها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` فقط. إذن الأجسام المضادة لدى الزوج من نوع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Anti</mtext></math>`-`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` ، وفق نموذج `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ABO</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p108-q17-3\ntitle: صفحة 108، السؤال 17، الفرع 3\nquestion: ما احتمال إنجاب طفلة سليمة من المرض طبيعية الشعر وفصيلة دمها B من بين النسل؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nتزوج شاب غير معروف الطراز الشكلي (والده كان ذا شعر طبيعي)، من فتاة ذات شعر طبيعي سليمة من مرض عمى الألوان. أنجبا طفلة مصابة بعمى الألوان فصيلة دمها O وعند بلوغها تساقط شعرها. تبين بالفحص المخبري أن أياً من الأبوين لا يستطيع التبرع للآخر بالدم، ويوجد مولد ضد A على أغشية خلايا الدم الحمراء للأم. استخدم M لجين عدم الإصابة بعمى الألوان.\n\nاعتمد توافق كريات الدم الحمراء في نظام ABO فقط، مع إهمال عوامل التوافق الأخرى.\n\nما احتمال إنجاب طفلة سليمة من المرض طبيعية الشعر وفصيلة دمها B من بين النسل؟\n\nsolution:\nفي صفة الشعر نرمز إلى أليل الصلع بـ b، وإلى أليل الشعر الطبيعي بـ b⁺؛ وتتغير سيادتهما تبعاً للجنس.\nنفسر التبرع في هذه المسألة وفق توافق كريات الدم الحمراء في نظام ABO.\nعمى الألوان متنح على `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>X</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>M</mtext></math>` سليم و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>m</mtext></math>` مصاب. الطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐXᵐ</mtext></math>` تثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Xᵐ</mtext></math>` لدى الأب فيكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐY</mtext></math>` ، والأم السليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴹXᵐ</mtext></math>`.\nالصلع `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` سائد في الذكور ومتنح في الإناث. الشاب أخذ `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` من أبيه الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، وأعطى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للطفلة الصلعاء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nفهو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>`. الأم الطبيعية التي أعطت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` أيضاً.\nالطفلة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` هي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` ، فتثبت `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` في الوالدين. وجود مولد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` عند الأم يجعلها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴬi</mtext></math>` ؛\nوعدم التبرع بين الوالدين في الاتجاهين يجعل الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` أي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi</mtext></math>`.\nالمرض والجنس : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐY × XᴹXᵐ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴹXᵐ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐXᵐ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴹY</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᵐY</mtext></math>` بأرباع؛\nالبنت السليمة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>XᴹXᵐ</mtext></math>` احتمالها `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nالشعر : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2 b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4 bb</mtext></math>` ؛\nفي الإناث الطبيعي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=1/4+1/2=3/4</mtext></math>`.\nالدم : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴮi × Iᴬi</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>AB</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>A</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>O</mtext></math>` بأرباع؛\nاحتمال `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>B=1/4</mtext></math>`.\nبالاستقلال : `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>(1/4)×(3/4)×(1/4)=3/64</mtext></math>`.\n:::\n\n:::exam-question\nid: bio-q-p108-q18-1\ntitle: صفحة 108، السؤال 18، الفرع 1\nquestion: اكتب الطرز الجينية المحتملة للأبوين للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من الأرانب يكون لون فرائها بنياً I^R أو أسود I^G أو ملوناً بني وأسود أو أبيض ii، وحجم الأذن الكبيرة صفة متنحية في الذكور وسائدة في الإناث. حصل تزاوج بين ذكر وأنثى كلاهما ملون بني وأسود وبآذان كبيرة.\n\nاكتب الطرز الجينية المحتملة للأبوين للصفتين معاً.\nsolution:\nلون الفراء يظهر أثر الأليلين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴿ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴳ</mtext></math>` للأسود معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ</mtext></math>` ؛\nكلا الأبوين ملونان فيكونان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ</mtext></math>`.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` للأذن الكبيرة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` للصغيرة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` متنح في الذكر وسائد في الأنثى. الذكر الكبير يجب أن يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` ، والأنثى الكبيرة يجوز أن تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>`.\nالذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ EE</mtext></math>` ؛\nوالأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ EE</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ Ee</mtext></math>`.\nلا يفرض كبر أذن الأنثى نقاءها، لأن الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>` كبير فيها؛\nأما الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>` فصغير، ولذلك لا يصلح للأب الكبير.\n:::\n\n:::exam-question\nid: bio-q-p108-q18-2\ntitle: صفحة 108، السؤال 18، الفرع 2\nquestion: اكتب الطرز الجينية لغاميتات الذكر.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من الأرانب يكون لون فرائها بنياً I^R أو أسود I^G أو ملوناً بني وأسود أو أبيض ii، وحجم الأذن الكبيرة صفة متنحية في الذكور وسائدة في الإناث. حصل تزاوج بين ذكر وأنثى كلاهما ملون بني وأسود وبآذان كبيرة.\n\nاكتب الطرز الجينية لغاميتات الذكر.\nsolution:\nلون الفراء يظهر أثر الأليلين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴿ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴳ</mtext></math>` للأسود معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ</mtext></math>` ؛\nكلا الأبوين ملونان فيكونان `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ</mtext></math>`.\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` للأذن الكبيرة و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` للصغيرة؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` متنح في الذكر وسائد في الأنثى. الذكر الكبير يجب أن يكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` ، والأنثى الكبيرة يجوز أن تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>`.\nالأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ EE</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` دائماً وأحد أليلي اللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴿ</mtext></math>` أو `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴳ</mtext></math>`.\nغاميتاه `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿE</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴳE</mtext></math>` ، احتمال كل منهما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`. لا يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` لأنه لا يحمله، رغم وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` ضمن أليلات هذا النوع.\n:::\n\n:::exam-question\nid: bio-q-p108-q18-3\ntitle: صفحة 108، السؤال 18، الفرع 3\nquestion: ما نمط الوراثة للصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من الأرانب يكون لون فرائها بنياً I^R أو أسود I^G أو ملوناً بني وأسود أو أبيض ii، وحجم الأذن الكبيرة صفة متنحية في الذكور وسائدة في الإناث. حصل تزاوج بين ذكر وأنثى كلاهما ملون بني وأسود وبآذان كبيرة.\n\nما نمط الوراثة للصفتين؟\nsolution:\nلون الفراء يخضع لأليلات متعددة؛\nيوجد `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴿ</mtext></math>` للبني و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴳ</mtext></math>` للأسود و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>i</mtext></math>` للأبيض في الجماعة، وكل فرد يحمل اثنين فقط. بين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Iᴳ</mtext></math>` سيادة مشتركة، فيظهر البني والأسود معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>IᴿIᴳ</mtext></math>` ، بينما `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ii</mtext></math>` أبيض.\nحجم الأذن صفة جسمية متأثرة بالجنس؛\nأليل الكبيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` متنح في الذكر وسائد في الأنثى. لذلك `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>` صغير الأذنين إذا كان ذكراً وكبير الأذنين إذا كان أنثى.\n:::\n\n:::exam-question\nid: bio-q-p108-q18-4\ntitle: صفحة 108، السؤال 18، الفرع 4\nquestion: ما احتمال ظهور ذكور بأذان كبيرة لأب بأذان كبيرة وأم بأذان صغيرة؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 108\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي نوع من الأرانب يكون لون فرائها بنياً I^R أو أسود I^G أو ملوناً بني وأسود أو أبيض ii، وحجم الأذن الكبيرة صفة متنحية في الذكور وسائدة في الإناث. حصل تزاوج بين ذكر وأنثى كلاهما ملون بني وأسود وبآذان كبيرة.\n\nفي تزاوج آخر، ما احتمال ظهور ذكور بآذان كبيرة من أب بآذان كبيرة وأم بآذان صغيرة؟\n\nsolution:\nهذا الفرع يغير صفة الأم إلى صغيرة الأذن. نرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` للكبير و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` للصغير؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` متنح في الذكور وسائد في الإناث.\nالأب الذكر الكبير `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` ؛\nالأم الأنثى الصغيرة `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>ee</mtext></math>` ، لأن وجود `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` واحد يكفي لكبر أذن الأنثى.\nغاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>E</mtext></math>` والأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>e</mtext></math>` ؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE × ee</mtext></math>` يعطي جميع النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>`. الهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Ee</mtext></math>` صغير الأذن في الذكور وكبير في الإناث.\nإذن لا يظهر ذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>EE</mtext></math>` كبير؛\nاحتمال ذكور كبيرة الأذن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=0</mtext></math>`. لا نستخدم طراز الأم الكبيرة في المقدمة لأنه تغير صراحةً في هذا الفرع.\n:::\n\n:::exam-question\nid: bio-q-p109-q19-1\ntitle: صفحة 109، السؤال 19، الفرع 1\nquestion: اكتب الطرز الجينية للأبوين للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الطيور تكون صفة لون الريش إما أحمر R أو أخضر G أو ملون بالأحمر والأخضر، وصفة وجود العرف b سائدة عند الذكور ومتنحية عند الإناث. تزاوج ذكر أحمر اللون بدون عرف مع أنثى خضراء اللون بعرف، وكانت أفراد الجيل الأول جميعها ملونة بالأحمر والأخضر، وجميع الذكور بعرف وجميع الإناث بدون عرف.\n\nاكتب الطرز الجينية للأبوين للصفتين معاً.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` لأليل الريش الأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴳ</mtext></math>` للأخضر؛\nبينهما سيادة مشتركة فيظهر اللونان معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>`. الأب الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴿ</mtext></math>` والأم الخضراء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴳCᴳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابه؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الأب بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأم ذات عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nإذن الذكر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺ CᴿCᴿ</mtext></math>` ، والأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb CᴳCᴳ</mtext></math>`. غاميت الأب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Cᴿ</mtext></math>` وغاميت الأم `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴳ</mtext></math>` ؛\nفيكون كل النسل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b CᴿCᴳ</mtext></math>` ، موافقاً اللونين مع اختلاف العرف بين الجنسين.\n:::\n\n:::exam-question\nid: bio-q-p109-q19-2\ntitle: صفحة 109، السؤال 19، الفرع 2\nquestion: اكتب الطرز الجينية لأفراد الجيل الأول للصفتين معاً.\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الطيور تكون صفة لون الريش إما أحمر R أو أخضر G أو ملون بالأحمر والأخضر، وصفة وجود العرف b سائدة عند الذكور ومتنحية عند الإناث. تزاوج ذكر أحمر اللون بدون عرف مع أنثى خضراء اللون بعرف، وكانت أفراد الجيل الأول جميعها ملونة بالأحمر والأخضر، وجميع الذكور بعرف وجميع الإناث بدون عرف.\n\nاكتب الطرز الجينية لأفراد الجيل الأول للصفتين معاً.\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` لأليل الريش الأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴳ</mtext></math>` للأخضر؛\nبينهما سيادة مشتركة فيظهر اللونان معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>`. الأب الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴿ</mtext></math>` والأم الخضراء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴳCᴳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابه؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الأب بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأم ذات عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nكل غاميت من الأب يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺Cᴿ</mtext></math>` ، وكل غاميت من الأم يحمل `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bCᴳ</mtext></math>`.\nإذن جميع أفراد الجيل الأول `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b CᴿCᴳ. CᴿCᴳ</mtext></math>` يظهر اللونين في الجنسين، و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` يعطي ذكراً بعرف وأنثى بلا عرف؛\nلأن علاقة سيادة أليل العرف تتغير باختلاف الجنس.\n:::\n\n:::exam-question\nid: bio-q-p109-q19-3\ntitle: صفحة 109، السؤال 19، الفرع 3\nquestion: ما مبدأ الوراثة لكل من الصفتين؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الطيور تكون صفة لون الريش إما أحمر R أو أخضر G أو ملون بالأحمر والأخضر، وصفة وجود العرف b سائدة عند الذكور ومتنحية عند الإناث. تزاوج ذكر أحمر اللون بدون عرف مع أنثى خضراء اللون بعرف، وكانت أفراد الجيل الأول جميعها ملونة بالأحمر والأخضر، وجميع الذكور بعرف وجميع الإناث بدون عرف.\n\nما مبدأ الوراثة لكل من الصفتين؟\nsolution:\nلون الريش سيادة مشتركة؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>` يظهر الأحمر والأخضر معاً، ولا يتحول إلى لون وسطي واحد.\nالعرف صفة جسمية متأثرة بالجنس؛\nالهجين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` يظهر بعرف في الذكر وبلا عرف في الأنثى، لأن `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث.\nلذلك يجوز أن يشترك جميع أفراد الجيل الأول في الطراز الجيني نفسه ويختلف مظهر العرف بين الجنسين.\n:::\n\n:::exam-question\nid: bio-q-p109-q19-4\ntitle: صفحة 109، السؤال 19، الفرع 4\nquestion: ما احتمال ظهور إناث ملونة بالأحمر والأخضر وبعرف في أفراد الجيل الثاني؟\nreference: تصنيف أسئلة الأحياء توجيهي 2025 (1).pdf · صفحة PDF 109\nanswer-label: الإجابة والشرح من المجموعة المصححة\nbody:\nفي أحد أنواع الطيور تكون صفة لون الريش إما أحمر R أو أخضر G أو ملون بالأحمر والأخضر، وصفة وجود العرف b سائدة عند الذكور ومتنحية عند الإناث. تزاوج ذكر أحمر اللون بدون عرف مع أنثى خضراء اللون بعرف، وكانت أفراد الجيل الأول جميعها ملونة بالأحمر والأخضر، وجميع الذكور بعرف وجميع الإناث بدون عرف.\n\nما احتمال ظهور إناث ملونة بالأحمر والأخضر وبعرف في أفراد الجيل الثاني؟\nsolution:\nنرمز `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴿ</mtext></math>` لأليل الريش الأحمر و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>Cᴳ</mtext></math>` للأخضر؛\nبينهما سيادة مشتركة فيظهر اللونان معاً في `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>`. الأب الأحمر `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴿ</mtext></math>` والأم الخضراء `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴳCᴳ</mtext></math>`.\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` للعرف و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺</mtext></math>` لغيابه؛\n`mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b</mtext></math>` يسود في الذكور ويتنحى في الإناث. الأب بلا عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` ، والأم ذات عرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>`.\nالجيل الأول كله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b CᴿCᴳ</mtext></math>` ؛\nللحصول على الجيل الثاني يتزاوج فردان من هذا الطراز، مع استقلال صفة اللون والعرف في نموذج المسألة.\nاللون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ × CᴿCᴳ</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴿ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴿCᴳ</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>CᴳCᴳ</mtext></math>` ؛\nاحتمال اللونين `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>`.\nالعرف `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b × b⁺b</mtext></math>` يعطي `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b⁺</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>b⁺b</mtext></math>` و `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ؛\nالأنثى ذات العرف يجب أن تكون `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>bb</mtext></math>` ، واحتماله `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/4</mtext></math>`.\nاحتمال الأنثى `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>1/2</mtext></math>` ؛\nالمطلوب `mathml: <math xmlns="http://www.w3.org/1998/Math/MathML" dir="ltr"><mtext>=(1/2)×(1/2)×(1/4)=1/16</mtext></math>` من كل الجيل الثاني.\n:::';export default t("non-mendelian-inheritance",source);
